// ============================================================
// Certus — SIE Products & Risks question bank (wave 1)
//
// Written AFTER the readings that teach this material, which is the
// order we should have used from the start. Every concept here is
// taught in sie.ts: the money market chapter, the insurance chapter,
// the indenture section of the debt chapter, and the alternatives
// section of the products chapter.
//
// WEIGHTING: Products is 44% of the SIE (33 of 75 scored questions),
// the heaviest area on the exam, and our weakest topic at 14% of target.
//
// DIFFICULTY: deliberately skewed to bands 1 and 2. The existing SIE
// bank is 6% easy / 21% medium / 73% hard on an ENTRY-LEVEL exam —
// a bank a beginner bounces off. These fill the ramp.
//
// NOTE: literal strings only — no shared constants for topicId/topicName.
// The audit, coverage, verifier and alignment scripts all parse this file
// as TEXT with regex, so a `topicId: T` reference resolves to nothing and
// the questions become invisible to every quality gate. Learned the hard
// way: 35 questions silently counted for zero.
// ============================================================

import { Question } from "./types";

export const sieProductsQuestions: Question[] = [
  { id: "sie-mm-001", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A money market instrument is generally defined as debt maturing in:",
    choices: ["One year or less", "Two to five years", "Five to ten years", "More than ten years"],
    answerIndex: 0,
    explanation: "Money market instruments mature in one year or less. That short maturity is what keeps both credit risk and interest rate risk small, and it is why money market funds suit a client whose objective is preservation of capital or who needs the money soon. The longer ranges describe notes and bonds, which carry real price sensitivity to rate changes." },
  { id: "sie-mm-002", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A corporation needs 45 days of funding to cover payroll before receivables arrive. It issues an unsecured note at a discount, with no collateral pledged. This instrument is:",
    choices: ["A banker's acceptance", "Commercial paper", "A negotiable certificate of deposit", "A repurchase agreement"],
    answerIndex: 1,
    explanation: "Commercial paper is exactly this: an unsecured, short-term discount note a corporation issues for current transactions like payroll or inventory. Because nothing is pledged, only strong credits can issue it cheaply. A banker's acceptance would carry a BANK's guarantee and finance a trade; a negotiable CD is a bank deposit, not corporate borrowing; and a repo is a collateralised loan against securities." },
  { id: "sie-mm-003", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "What is the maximum maturity of commercial paper?",
    choices: ["30 days", "90 days", "270 days", "One year"],
    answerIndex: 2,
    explanation: "270 days. The limit is not a market convention but a legal boundary: Section 3(a)(3) of the Securities Act of 1933 exempts from registration a note maturing in 270 days or less issued for current transactions. Staying inside that window lets the issuer skip a registration statement and prospectus, which is the whole economic point. Paper at 271 days would require registration, so nobody issues it." },
  { id: "sie-mm-004", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A banker's acceptance differs from commercial paper primarily because it:",
    choices: ["Has no maximum maturity", "Is issued only by the U.S. Treasury", "Pays a semiannual coupon", "Carries a bank's guarantee of payment"],
    answerIndex: 3,
    explanation: "A banker's acceptance starts as a time draft in an international trade and becomes tradeable when a BANK stamps it 'accepted', converting one company's promise into a bank's obligation. That guarantee is the defining difference from unsecured commercial paper. Both cap at 270 days, neither is a Treasury product, and both are discount instruments with no coupon." },
  { id: "sie-mm-005", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A negotiable certificate of deposit requires a minimum denomination of:",
    choices: ["$100,000", "$1,000", "$10,000", "$1,000,000"],
    answerIndex: 0,
    explanation: "$100,000 is the minimum, though in practice these trade in $1 million and larger sizes. 'Negotiable' means it can be SOLD to another investor before maturity, which is the distinction from a retail CD that must be held and carries an early-withdrawal penalty. Note that FDIC insurance stops at $250,000, so a jumbo CD is largely uninsured." },
  { id: "sie-mm-006", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A customer holds a $1,000,000 negotiable CD at one bank. How much is FDIC insured?",
    choices: ["$500,000", "$250,000", "$1,000,000", "Nothing, because negotiable CDs are securities"],
    answerIndex: 1,
    explanation: "FDIC coverage is $250,000 per depositor per insured bank, so $750,000 of this position is uninsured and the holder carries real bank credit risk. That exposure is precisely why negotiable CDs yield more than small insured CDs. They remain bank deposits rather than securities, so the last option is wrong on its face." },
  { id: "sie-mm-007", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A dealer sells Treasuries to a bank and agrees to buy them back in seven days at a higher price. From the DEALER's perspective this is:",
    choices: ["A reverse repurchase agreement, and the dealer is lending", "An outright sale with no obligation to repurchase", "A repurchase agreement, and the dealer is borrowing", "A banker's acceptance"],
    answerIndex: 2,
    explanation: "The dealer receives cash now and must return more cash later, so the dealer is BORROWING and the trade is a repo from its side. The bank, which hands over cash and gets more back, is lending — the identical trade is a REVERSE repo from the bank's seat. The Treasuries serve as collateral, which is why repo rates sit below unsecured rates." },
  { id: "sie-mm-008", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A dealer enters a repo: sells $10,000,000 of Treasuries and repurchases them seven days later for $10,004,000. The $4,000 represents:",
    choices: ["A capital gain to the dealer", "A commission paid to the bank", "An underwriting spread", "Interest on a collateralized loan"],
    answerIndex: 3,
    explanation: "A repo is economically a secured loan, and the difference between the sale price and the repurchase price is the interest on it: $10,004,000 − $10,000,000 = $4,000 for seven days. It is a cost to the dealer, not a gain. No commission or underwriting is involved — this is a principal transaction between two parties." },
  { id: "sie-mm-009", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "The federal funds rate is the rate at which:",
    choices: ["Banks lend reserves to each other overnight", "The Federal Reserve lends directly to banks", "Banks lend to their best corporate customers", "The Treasury borrows for one year"],
    answerIndex: 0,
    explanation: "Fed funds is the overnight, unsecured rate banks charge EACH OTHER for reserves. The rate the Fed charges banks borrowing directly from it is the DISCOUNT rate. The rate to top corporate borrowers is the prime rate, and one-year Treasury borrowing is the T-bill. The Fed targets the fed funds rate rather than setting it by decree." },
  { id: "sie-mm-010", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which money market instrument is issued at a discount by the U.S. government?",
    choices: ["Treasury note", "Treasury bill", "Banker's acceptance", "Negotiable CD"],
    answerIndex: 1,
    explanation: "The Treasury BILL is the government's money market instrument: no coupon, issued at a discount, maturing at face value in one year or less. Treasury notes run two to ten years and pay semiannual coupons, so they are not money market instruments. Banker's acceptances and negotiable CDs are bank products, not government issues." },
  { id: "sie-ins-001", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "In a VARIABLE annuity, investment risk is borne by:",
    choices: ["The insurance company", "The subaccount manager", "The contract holder", "FINRA"],
    answerIndex: 2,
    explanation: "A variable annuity's assets sit in a SEPARATE account whose subaccounts the holder selects, so performance flows through to the holder and the payout varies. The insurer bears investment risk only in a FIXED annuity, where it guarantees the rate from its general account. Managers are not liable for market losses, and FINRA is a regulator, not a guarantor." },
  { id: "sie-ins-002", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which life insurance product provides pure death benefit with NO cash value?",
    choices: ["Whole life", "Universal life", "Variable life", "Term life"],
    answerIndex: 3,
    explanation: "Term life is pure death benefit for a stated period: nothing accumulates, nothing is invested, and it is by far the cheapest way to buy a given amount of coverage. Whole, universal and variable life all build cash value, which is exactly why they cost more for the same death benefit. Term suits a temporary need such as a mortgage or dependent children." },
  { id: "sie-ins-003", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A product is funded through the insurer's SEPARATE account. This means:",
    choices: ["The contract holder bears investment risk and it is a security", "The insurer guarantees the value from its own assets", "The product is FDIC insured", "No securities registration is needed to sell it"],
    answerIndex: 0,
    explanation: "The separate account is legally segregated and holds subaccounts the holder chooses, so performance passes straight through and the HOLDER bears investment risk. That is precisely what makes the product a security requiring a securities registration to sell. Guarantees come from the GENERAL account, and insurance products are never FDIC insured — that covers bank deposits." },
  { id: "sie-ins-004", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which product requires BOTH a securities registration and a state insurance license to sell?",
    choices: ["Fixed annuity", "Variable annuity", "Whole life policy", "Term life policy"],
    answerIndex: 1,
    explanation: "A variable annuity is both an insurance contract and a security, because the separate account puts investment risk on the contract holder. That dual character requires both licences. Fixed annuities, whole life and term life are all funded from the general account with the insurer bearing investment risk, so they are insurance products only." },
  { id: "sie-ins-005", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "At annuitization of a variable annuity, the number of ANNUITY UNITS:",
    choices: ["Varies, while their value is fixed", "Both the number and the value are fixed", "Is fixed, while their value continues to vary", "Both the number and the value continue to vary"],
    answerIndex: 2,
    explanation: "At annuitization, accumulation units convert to annuity units and the NUMBER is then fixed for life. Their VALUE keeps moving with the separate account, which is why a variable annuity payment changes month to month. If both were fixed the contract would be a fixed annuity, and a varying number of units describes the accumulation phase instead." },
  { id: "sie-ins-006", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "During the accumulation phase of a variable annuity, the holder purchases:",
    choices: ["Annuity units", "Mutual fund shares", "Guaranteed interest certificates", "Accumulation units"],
    answerIndex: 3,
    explanation: "While paying in, the holder buys ACCUMULATION units, and their number grows with each contribution. These convert to ANNUITY units only at annuitization, when the contract switches from saving to paying income. The subaccounts resemble mutual funds but the holder owns units of the separate account, not fund shares directly." },
  { id: "sie-ins-007", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A client wants the largest possible death benefit for the lowest premium and has no need for savings. The suitable recommendation is:",
    choices: ["Term life", "Variable life", "Whole life", "A variable annuity"],
    answerIndex: 0,
    explanation: "Term delivers the most coverage per premium dollar because none of the premium funds a savings component. Recommending variable or whole life to a client whose stated need is maximum coverage at minimum cost is a classic unsuitable recommendation — those cost far more per dollar of death benefit. An annuity is an income product and provides no meaningful death benefit at all." },
  { id: "sie-ins-008", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A FIXED annuity protects the holder from investment risk but exposes them to:",
    choices: ["Credit risk on the subaccounts", "Purchasing power risk", "Prepayment risk", "Currency risk"],
    answerIndex: 1,
    explanation: "A fixed annuity pays a guaranteed dollar amount from the general account, so the insurer absorbs investment risk. What the holder keeps is PURCHASING POWER risk: a level payment buys less each year as prices rise. Subaccounts exist only in variable contracts, prepayment risk belongs to mortgage securities, and currency risk requires foreign exposure." },
  { id: "sie-ins-009", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which life policy allows the holder to vary both the premium and the death benefit?",
    choices: ["Term life", "Whole life", "Universal life", "Straight life"],
    answerIndex: 2,
    explanation: "Universal life is defined by that flexibility: the holder may pay more in a good year and less in a lean one, and may adjust the death benefit, within policy limits. Whole life (also called straight life) has a fixed premium and fixed death benefit. Term has a level premium for its period and no cash value to draw on." },
  { id: "sie-dbt-001", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "The written contract between a bond issuer and its bondholders is the:",
    choices: ["Prospectus", "Official statement", "Registration statement", "Indenture"],
    answerIndex: 3,
    explanation: "The indenture sets the coupon, maturity, collateral, covenants, and holders' rights on default. A prospectus is the disclosure document for a new issue, an official statement is the municipal analogue of a prospectus, and a registration statement is what gets filed with the SEC. Only the indenture is the contract itself." },
  { id: "sie-dbt-002", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A sinking fund provision requires the issuer to:",
    choices: ["Set money aside to retire the debt gradually", "Pay a higher coupon in later years", "Redeem the bonds only if rates fall", "Pledge specific assets as collateral"],
    answerIndex: 0,
    explanation: "A sinking fund obliges the issuer to set aside money each year to retire part of the issue before maturity, which lowers default risk because the debt is repaid progressively rather than in one lump at the end. That protection favours the HOLDER. Redeeming when rates fall describes a CALL provision, and pledging assets describes a secured bond." },
  { id: "sie-dbt-003", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A call provision on a bond primarily benefits:",
    choices: ["The bondholder", "The issuer", "The trustee", "The underwriter"],
    answerIndex: 1,
    explanation: "The call is exercised at the ISSUER's option, and issuers call when rates have FALLEN so they can refinance more cheaply. That is the worst moment for the holder, who loses an above-market coupon and must reinvest at the new lower rate — call risk and reinvestment risk are the same event. A PUT provision is the one that favours the holder." },
  { id: "sie-dbt-004", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A subordinated debenture ranks:",
    choices: ["Above all secured creditors", "Equal to preferred stock", "Below other unsecured debt in liquidation", "Ahead of senior debentures"],
    answerIndex: 2,
    explanation: "Subordinated means junior: it ranks below other unsecured debt in the liquidation waterfall, which is why it must offer a higher yield to attract buyers. It still ranks ahead of preferred and common STOCK, since all debt outranks equity. Secured creditors are paid before any unsecured claim, subordinated or otherwise." },
  { id: "sie-dbt-005", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor holds a mortgage-backed security. Interest rates FALL sharply. The most likely consequence is:",
    choices: ["Extension risk — the security's average life lengthens", "Default risk rises as homeowners struggle to pay", "No effect, since mortgage payments are contractually fixed", "Prepayment risk — principal returns early, to be reinvested at lower rates"],
    answerIndex: 3,
    explanation: "Homeowners refinance when rates fall, returning principal to the certificate holder exactly when reinvestment opportunities are worst. That is PREPAYMENT risk. EXTENSION risk is the mirror image and occurs when rates RISE: prepayments slow and the holder is locked into a below-market yield for longer. Falling rates make mortgages easier to service, not harder." },
  { id: "sie-dbt-006", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Under the Trust Indenture Act of 1939, larger public corporate bond issues must appoint a:",
    choices: ["Trustee to enforce the indenture for holders", "Market maker to maintain a two-sided quote", "Transfer agent to track bondholders", "Registrar to prevent over-issuance"],
    answerIndex: 0,
    explanation: "The trustee is an independent party charged with enforcing the indenture on behalf of bondholders, who are far too dispersed to act collectively. Municipal and U.S. government issues are exempt from the requirement. Transfer agents and registrars maintain ownership records, and market makers provide liquidity — none of them enforce the contract." },
  { id: "sie-alt-001", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "In a limited partnership, the GENERAL partner has:",
    choices: ["Liability capped at their investment", "Unlimited personal liability and management control", "No role in managing the business", "The same rights as a limited partner"],
    answerIndex: 1,
    explanation: "The general partner runs the program and accepts unlimited personal liability for partnership obligations — that exposure is the price of control. Limited partners are passive investors whose liability stops at what they invested, which is the entire reason the limited partnership form exists. Reversing the two roles is the most common error on this topic." },
  { id: "sie-alt-002", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A limited partner who begins actively managing the partnership's business risks:",
    choices: ["Being taxed at corporate rates", "Forfeiting their capital contribution", "Losing their limited liability protection", "Becoming the trustee of the partnership"],
    answerIndex: 2,
    explanation: "Limited liability is granted in exchange for PASSIVITY. A limited partner who takes on management may be treated as a general partner and lose the liability cap, which is why the passivity is enforced rather than optional. Inspecting the books, voting on major matters, and suing the general partner are all permitted and do not forfeit the protection." },
  { id: "sie-alt-003", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A direct participation program passes through to investors:",
    choices: ["Income only, never losses", "Losses only, never income", "Neither, since it is taxed at the entity level", "Both income and losses"],
    answerIndex: 3,
    explanation: "A DPP is a flow-through entity, so income, gains, losses, deductions and credits all pass to the investors and nothing is taxed at the partnership level. That contrasts directly with a REIT, which passes through INCOME but not losses — the distinction the exam tests. Note the limit: passive losses generally offset only passive income, not wages." },
  { id: "sie-alt-004", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor wants real estate exposure that can be sold quickly. The better recommendation is:",
    choices: ["A listed REIT", "A real estate limited partnership", "A raw land DPP", "A private placement real estate fund"],
    answerIndex: 0,
    explanation: "A listed REIT trades on an exchange and is therefore liquid, and it must distribute at least 90% of taxable income, which is why it is held for income. Limited partnerships, raw land programs and private placements are all illiquid by design with no meaningful secondary market — precisely what this client said they cannot accept." },
  { id: "sie-alt-005", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "In the dissolution of a limited partnership, the order of payment is:",
    choices: ["General partners, limited partners, secured creditors, general creditors", "Secured creditors, general creditors, limited partners, general partners", "Limited partners, general partners, all creditors", "All partners equally, then creditors"],
    answerIndex: 1,
    explanation: "Creditors always precede owners, and secured creditors precede unsecured ones. Among the owners, LIMITED partners are paid before GENERAL partners — the general partner, who holds control and unlimited liability, stands last. Any ordering that pays partners before creditors inverts the basic principle that debt outranks equity." },
  { id: "sie-alt-006", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Commodities differ from most securities because they:",
    choices: ["Pay a guaranteed dividend each quarter", "Are insured against loss by the SIPC", "Generate no income, so the entire return depends on price", "Carry no price volatility"],
    answerIndex: 2,
    explanation: "A barrel of oil or an ounce of gold pays no coupon and no dividend, so the whole return comes from price movement. Their appeal is diversification and inflation hedging, since commodity prices often rise as the purchasing power of fixed payments falls. They are notably volatile, and SIPC protects brokerage customers against firm failure, not against market losses." },
  { id: "sie-rsk-001", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which risk CANNOT be reduced by diversification?",
    choices: ["Business risk", "Credit risk", "Liquidity risk", "Market risk"],
    answerIndex: 3,
    explanation: "Market risk is SYSTEMATIC: it moves everything at once, so holding more securities does not escape it. Business, credit and liquidity risks are all UNSYSTEMATIC — specific to one company or issuer — and offset across a diversified portfolio. Because unsystematic risk can be removed for free, the market does not pay investors extra for bearing it." },
  { id: "sie-rsk-002", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Inflation risk is also known as:",
    choices: ["Purchasing power risk", "Default risk", "Reinvestment risk", "Liquidity risk"],
    answerIndex: 0,
    explanation: "Inflation risk and purchasing power risk are the same thing: the erosion in what a fixed payment will buy. It hits long-dated fixed-rate bonds hardest and is SYSTEMATIC, since it affects all fixed payments simultaneously and cannot be diversified away. That is exactly why TIPS exist." },
  { id: "sie-rsk-003", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor holds a single stock representing 80% of their portfolio. The primary concern is:",
    choices: ["Systematic risk, which concentration increases", "Unsystematic risk taken without additional expected return", "Reinvestment risk on the dividend payments", "Prepayment risk on the position"],
    answerIndex: 1,
    explanation: "Concentration loads up on company-specific — unsystematic — risk, and because that risk could be eliminated for free by diversifying, the market offers no additional expected return for carrying it. The investor is taking uncompensated risk, which is what makes the position imprudent. Systematic risk depends on market exposure rather than on how many names are held." },
  { id: "sie-rsk-004", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A bondholder's securities are called when rates fall. The investor now faces:",
    choices: ["Default risk on the redeemed bonds", "Currency risk on the proceeds", "Reinvestment risk at the new lower rates", "Extension risk on the position"],
    answerIndex: 2,
    explanation: "Being called returns principal precisely when reinvestment opportunities have worsened, so call risk and reinvestment risk are two faces of one event. The issuer has paid in full, so there is no default. Extension risk is the opposite scenario, arising when rates RISE and principal comes back more slowly than expected." },
  { id: "sie-trd-101", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "An order entered with no stated duration expires:",
    choices: ["At the end of the calendar month", "Only when the customer cancels it", "After 30 calendar days", "At the close of that trading day"],
    answerIndex: 3,
    explanation: "An order with no duration specified is a DAY order, the default, and it dies at the close if unfilled. An order that carries over day to day is GOOD TIL CANCELLED and must be marked GTC explicitly. Nothing expires on a monthly or 30-day schedule by default, though firms often ask customers to reconfirm open orders periodically." },
  { id: "sie-trd-102", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer enters a FILL OR KILL order. This means the order must be:",
    choices: ["Executed completely and immediately, or cancelled entirely", "Executed completely, but the firm may wait for a fill", "Executed partially now, with the rest cancelled", "Held open until the customer cancels it"],
    answerIndex: 0,
    explanation: "Fill or kill is the strictest qualifier: the ENTIRE order must execute IMMEDIATELY or the whole thing is cancelled. Waiting for a complete fill describes ALL OR NONE. Taking what is available now and cancelling the rest describes IMMEDIATE OR CANCEL. Holding open indefinitely is GTC." },
  { id: "sie-trd-103", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which order qualifier permits a PARTIAL execution but requires whatever fills to happen immediately?",
    choices: ["Fill or kill", "Immediate or cancel", "All or none", "Good til cancelled"],
    answerIndex: 1,
    explanation: "Immediate or cancel takes whatever quantity is available right now and cancels the remainder, so partial fills are allowed. Fill or kill and all or none both forbid partial execution — the difference between those two is timing, since AON may wait while FOK may not. GTC concerns duration, not completeness." },
  { id: "sie-trd-104", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "An ALL OR NONE order differs from a FILL OR KILL order because AON:",
    choices: ["Permits partial execution", "Expires at the close of the trading day", "May wait for a complete fill rather than executing instantly", "Applies only to municipal securities"],
    answerIndex: 2,
    explanation: "Both require the whole order to fill, so neither permits partials. The distinction is TIMING: all or none may be worked over time until the full quantity is available, while fill or kill demands immediate execution or cancellation. Neither is limited to a product type, and duration is a separate instruction." },
  { id: "sie-trd-105", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Regular-way settlement for a common stock transaction is:",
    choices: ["Two business days after the trade (T+2)", "Three business days after the trade (T+3)", "The same day as the trade", "One business day after the trade (T+1)"],
    answerIndex: 3,
    explanation: "Regular way is T+1 for stocks, corporate and municipal bonds, government securities and listed options, effective since May 2024. T+2 was the prior standard and still appears in outdated study material, which is exactly why the exam tests it. Same-day settlement happens only by specific agreement as a cash trade." },
  { id: "sie-trd-106", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A trade settles on Tuesday under regular way. Under Regulation T, the customer's payment is due:",
    choices: ["Two business days after settlement", "On the trade date", "On the settlement date", "Thirty calendar days after the trade"],
    answerIndex: 0,
    explanation: "Settlement and the payment deadline are different things. SETTLEMENT (T+1) is when securities and money change hands between firms; REGULATION T is when the CUSTOMER must pay their firm, two business days after settlement. The exam pairs these deliberately to see whether the candidate treats them as one date." },
  { id: "sie-trd-107", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer grants a third party written authority to trade the account but not to withdraw funds. This is a:",
    choices: ["Full power of attorney", "Limited power of attorney", "Discretionary authorization to the representative", "Custodial appointment"],
    answerIndex: 1,
    explanation: "A LIMITED power of attorney permits trading only. A FULL power additionally permits withdrawing cash and securities. Both differ from the registered representative's own DISCRETION, which is the firm's authority to choose security, amount, or whether to trade — also requiring written authorization. A custodian acts for a minor under UTMA or UGMA." },
  { id: "sie-trd-108", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A client receives a retirement plan distribution personally and intends to move it to an IRA. They must complete the rollover within:",
    choices: ["30 days", "90 days", "60 days", "One calendar year"],
    answerIndex: 2,
    explanation: "A rollover that passes through the account holder's hands must be redeposited within 60 DAYS or it becomes a taxable distribution, and only one such rollover is permitted per twelve-month period. A direct custodian-to-custodian TRANSFER avoids the clock and the annual limit entirely, which is why it is the safer recommendation in nearly every case." },
  { id: "sie-trd-109", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Buying and selling the same security with no change in beneficial ownership is:",
    choices: ["A permitted tax-loss strategy", "A legitimate way to add liquidity", "Allowed if disclosed to the customer", "A wash trade, which is prohibited"],
    answerIndex: 3,
    explanation: "A wash trade creates entirely fictitious activity — nobody's ownership actually changes — in order to suggest volume or manufacture a tax loss. It is a prohibited manipulation. Disclosure does not cure it, and it adds no real liquidity precisely because no genuine position changes hands." },
  { id: "sie-trd-110", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Entering orders late in the session specifically to influence the closing price is called:",
    choices: ["Marking the close", "Front-running", "Churning", "Selling away"],
    answerIndex: 0,
    explanation: "Marking the close targets the closing price, which matters because closing prices set fund valuations, index levels and reported performance. Front-running is trading ahead of a known customer order. Churning is excessive trading for commissions. Selling away is doing securities business outside the firm without approval." },
  { id: "sie-trd-111", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Excessive trading in a customer's account to generate commissions is:",
    choices: ["Front-running", "Churning", "Commingling", "Structuring"],
    answerIndex: 1,
    explanation: "Churning is judged against the customer's stated objectives and resources rather than any fixed number of trades — the same activity could be appropriate for an active trader and abusive for a retiree seeking income. Commingling mixes customer and firm assets; structuring breaks up cash transactions to dodge reporting." },
  { id: "sie-trd-112", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A currency transaction report (CTR) must be filed for cash transactions exceeding:",
    choices: ["$5,000 in a day", "$25,000 in a day", "$10,000 in a day", "$3,000 in a day"],
    answerIndex: 2,
    explanation: "The CTR threshold is $10,000 in cash in a single day, and filing is mechanical with no judgement involved. The $5,000 figure belongs to the SUSPICIOUS ACTIVITY REPORT, which does require judgement and must never be disclosed to the customer. Reversing the two numbers is the most common error on AML questions." },
  { id: "sie-trd-113", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer makes several cash deposits just under $10,000 on consecutive days. This is:",
    choices: ["Permitted, since each deposit is below the threshold", "Only a concern if the total exceeds $50,000", "Acceptable if the customer explains the reason", "Structuring, a federal crime the firm must report"],
    answerIndex: 3,
    explanation: "Deliberately breaking a large cash transaction into smaller pieces to stay under the CTR threshold is STRUCTURING, a federal crime by the customer and a red flag the firm must report on a SAR. Staying below the reporting line is the offence itself, so no explanation cures it and no higher total is required to trigger concern." },
  { id: "sie-trd-114", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A firm files a suspicious activity report. It may inform the customer:",
    choices: ["Never — disclosing a SAR is itself a violation", "Only after the SAR has been accepted", "Only if the customer asks directly", "Within 30 days of filing"],
    answerIndex: 0,
    explanation: "Telling a customer a SAR has been filed is 'tipping off' and is itself a violation, because it defeats the entire purpose of the report. There is no waiting period, no disclosure on request, and no timeframe after which it becomes permissible. Contrast this with the CTR, which is a routine mechanical filing." },
  { id: "sie-trd-115", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "In a JTWROS account, a deceased owner's interest passes to:",
    choices: ["The deceased owner's estate under their will", "The surviving owner automatically, outside probate", "The broker-dealer holding the account", "A court-appointed administrator"],
    answerIndex: 1,
    explanation: "Joint tenants with right of survivorship passes the interest to the survivor automatically, bypassing probate. TENANTS IN COMMON is the registration that sends the deceased's share to their ESTATE under the will. Same two people, same assets, opposite outcome — which is why the registration choice is substantive rather than clerical." },
  { id: "sie-trd-116", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "On notice of a customer's death, the firm must first:",
    choices: ["Liquidate the positions to cash", "Transfer the assets to the next of kin", "Cancel open orders and freeze the account", "Continue trading under the existing authority"],
    answerIndex: 2,
    explanation: "The firm cancels all open orders and freezes the account immediately, then awaits a death certificate, letters testamentary or of administration, and any applicable tax waivers. Acting on prior instructions is not permitted — discretion dies with the customer. Liquidating or transferring before documentation would be acting without authority." },
  { id: "sie-trd-117", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A UTMA custodial account is opened for a minor. The gift is:",
    choices: ["Revocable by the donor at any time", "Owned by the custodian until the minor turns 18", "Held jointly by the custodian and the minor", "Irrevocable, and the assets belong to the minor immediately"],
    answerIndex: 3,
    explanation: "The transfer is IRREVOCABLE and the assets legally belong to the minor from the moment of the gift; the custodian merely manages them. Control passes to the minor outright at the age of majority, which frequently surprises donors who assumed they retained influence. The custodian may not trade on margin or speculate." },
  { id: "sie-trd-118", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A registered representative wants to choose which security to buy in a customer's account without calling first. This requires:",
    choices: ["Prior written discretionary authority from the customer", "Verbal permission on the day of the trade", "Only a principal's approval", "Nothing, if the trade is suitable"],
    answerIndex: 0,
    explanation: "Choosing the SECURITY or the AMOUNT always requires written discretionary authority before it is exercised. The narrow exception is discretion as to TIME and PRICE only, on a specified security and quantity, which may be accepted verbally and is good only for that day. Suitability does not substitute for authority." },
  { id: "sie-trd-119", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "The first day a stock trades WITHOUT the right to an upcoming dividend is the:",
    choices: ["Record date", "Ex-dividend date", "Declaration date", "Payable date"],
    answerIndex: 1,
    explanation: "The ex-dividend date is the first day a buyer no longer receives the dividend, and under T+1 settlement it now coincides with the record date. Declaration is when the board announces; record is when the issuer checks its books; payable is when cash arrives. On the ex-date the stock typically opens lower by roughly the dividend." },
  { id: "sie-trd-120", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer buys stock the morning of the ex-dividend date. They will:",
    choices: ["Receive the dividend, since they own it on the record date", "Receive half the dividend, prorated", "Not receive the dividend; the seller keeps it", "Receive the dividend only if they hold to the payable date"],
    answerIndex: 2,
    explanation: "Buying ON the ex-date means buying without the dividend attached — the seller retains it. To collect, the purchase must occur BEFORE the ex-date. Dividends are never prorated between buyer and seller, and holding to the payable date is irrelevant if the purchase came too late to establish the entitlement." },
  { id: "sie-reg-101", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "The federal agency with ultimate authority over the U.S. securities markets is the:",
    choices: ["FINRA", "MSRB", "SIPC", "SEC"],
    answerIndex: 3,
    explanation: "The Securities and Exchange Commission is the federal regulator, created by the Securities Exchange Act of 1934. FINRA and the MSRB are self-regulatory organisations operating under SEC oversight, and SIPC is not a regulator at all — it protects customers when a broker-dealer fails." },
  { id: "sie-reg-102", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "The MSRB writes rules for municipal securities dealers but:",
    choices: ["Has no enforcement authority of its own", "Also examines and disciplines every dealer", "Reports directly to Congress rather than the SEC", "Registers municipal representatives itself"],
    answerIndex: 0,
    explanation: "The MSRB is a rule-WRITING body with no enforcement power. Its rules are enforced by FINRA for broker-dealers, by bank regulators for bank dealers, and by the SEC. This split is a reliable exam question because it is genuinely unusual — most regulators do both." },
  { id: "sie-reg-103", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "The Securities Act of 1933 principally governs:",
    choices: ["Secondary market trading and exchanges", "New issues, through registration and prospectus delivery", "Investment adviser registration", "Insider trading penalties"],
    answerIndex: 1,
    explanation: "The 1933 Act is the 'paper act': it regulates the PRIMARY market by requiring a registration statement and prospectus delivery so buyers of new issues get the facts. The 1934 Act governs secondary trading, created the SEC, and addresses manipulation and insider trading. Adviser registration comes from the Investment Advisers Act of 1940." },
  { id: "sie-reg-104", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "Which act created the Securities and Exchange Commission?",
    choices: ["The Securities Act of 1933", "The Investment Company Act of 1940", "The Securities Exchange Act of 1934", "The Trust Indenture Act of 1939"],
    answerIndex: 2,
    explanation: "The 1934 Act created the SEC and gave it authority over secondary trading, exchanges and broker-dealers. The 1933 Act came first but was administered by the FTC until the SEC existed. The 1940 Act governs investment companies; the Trust Indenture Act governs corporate bond indentures." },
  { id: "sie-reg-105", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "SIPC protects a brokerage customer against:",
    choices: ["Losses from a decline in the market value of their holdings", "Poor recommendations by a registered representative", "Default of a bond issuer in their portfolio", "Failure of the broker-dealer holding their assets"],
    answerIndex: 3,
    explanation: "SIPC covers the failure of the INTERMEDIARY, restoring securities and cash up to $500,000 per customer with a $250,000 cash sublimit. It emphatically does not insure investment performance — a stock falling from $80 to $3 is market risk the investor accepted. Issuer default is credit risk, also uncovered." },
  { id: "sie-reg-106", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "A customer's account at a failed broker-dealer holds $380,000 in securities and $270,000 in cash. SIPC coverage is:",
    choices: ["$500,000, the overall per-customer ceiling", "$650,000, the full account value", "$630,000, securities plus the cash sublimit", "$250,000, the cash limit only"],
    answerIndex: 0,
    explanation: "Apply the cash sublimit first: $250,000 of the $270,000 cash is protected. Securities of $380,000 plus covered cash of $250,000 is $630,000, which exceeds the $500,000 overall ceiling, so coverage caps at $500,000. The customer becomes a general creditor for the remainder — both limits must be applied, in that order." },
  { id: "sie-reg-107", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "Which form is filed to register an individual with FINRA through a member firm?",
    choices: ["Form U5", "Form U4", "Form ADV", "Form BD"],
    answerIndex: 1,
    explanation: "Form U4 is the individual's registration application, disclosing employment history, criminal charges, regulatory actions, customer complaints and financial events. Form U5 is filed when they LEAVE. Form ADV registers investment advisers, and Form BD registers the broker-dealer entity itself." },
  { id: "sie-reg-108", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "When a registered representative leaves a firm, the firm must file Form U5 within:",
    choices: ["10 business days", "60 days", "30 days", "90 days"],
    answerIndex: 2,
    explanation: "The firm files Form U5 within 30 days of termination and must provide a copy to the individual. Material changes to a U4 are generally reported within 30 days as well, with certain disclosure events requiring 10 business days. Both forms feed the CRD system and BrokerCheck, which is why accuracy is treated so seriously." },
  { id: "sie-reg-109", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "A communication distributed to more than 25 retail investors within 30 calendar days is classified as:",
    choices: ["Correspondence, reviewable under firm procedures", "An institutional communication", "Exempt from FINRA review", "A retail communication, requiring principal approval before first use"],
    answerIndex: 3,
    explanation: "More than 25 retail investors in 30 days makes it a RETAIL communication, which needs principal approval BEFORE first use. Twenty-five or fewer is CORRESPONDENCE, reviewed per firm procedures without pre-approval. Institutional communications go only to institutional investors. Nothing in this scheme is exempt from review." },
  { id: "sie-reg-110", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Under Regulation Best Interest, when two products are both suitable but one pays the representative substantially more, the representative must:",
    choices: ["Weigh cost and alternatives, and not put their own interest first", "Recommend the higher-paying product if it is suitable", "Disclose the difference and then recommend either freely", "Refer the client to another representative"],
    answerIndex: 0,
    explanation: "Reg BI's CARE obligation requires evaluating cost and reasonably available alternatives among suitable options, and the firm may not place its financial interest ahead of the customer's. Under the OLD suitability standard recommending the higher-paying suitable product was defensible — closing that gap is precisely what Reg BI did. Disclosure alone does not cure the conflict." },
  { id: "sie-reg-111", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "Gifts given in connection with business are limited to:",
    choices: ["$250 per person per year", "$100 per person per year", "$500 per person per year", "No limit if disclosed"],
    answerIndex: 1,
    explanation: "The limit is $100 per person per year, deliberately low enough to prevent influence rather than to price it. Ordinary business entertainment where both parties are present is treated separately and is not counted as a gift, provided it is neither so frequent nor so lavish as to raise a conflict." },
  { id: "sie-reg-112", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "A dispute between a customer and a member firm resolved through FINRA arbitration is:",
    choices: ["Non-binding, and either party may withdraw", "Automatically appealable to federal court", "Binding, with essentially no right of appeal", "Decided by the SEC rather than an arbitration panel"],
    answerIndex: 2,
    explanation: "Arbitration is BINDING and the grounds for appeal are extremely narrow. MEDIATION is the voluntary, non-binding alternative that either party may abandon at any point. That binding-versus-voluntary contrast is the tested distinction, and the SEC does not decide these disputes." },
  { id: "sie-mkt-101", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "In the PRIMARY market, the proceeds of a sale go to:",
    choices: ["The selling investor", "The exchange", "The clearing corporation", "The issuer"],
    answerIndex: 3,
    explanation: "Primary market means the security is sold for the first time and the ISSUER receives the money to build something. In the SECONDARY market one investor sells to another and the issuer receives nothing. Following the cash is the fastest way to tell the two apart." },
  { id: "sie-mkt-102", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "An investor buys 500 shares of a listed company from another investor on an exchange. This is:",
    choices: ["A secondary market transaction", "A primary market transaction", "An initial public offering", "A private placement"],
    answerIndex: 0,
    explanation: "The shares already exist and the money goes to the selling investor, not the company, so it is a secondary market trade. An IPO and a private placement are both primary transactions where the issuer is raising capital. Note that the company receives nothing here despite its stock changing hands." },
  { id: "sie-mkt-103", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "A broker acting as AGENT for a customer is compensated by:",
    choices: ["A markup on the price", "A commission", "The bid-ask spread", "An underwriting concession"],
    answerIndex: 1,
    explanation: "An agent stands between buyer and seller, never owns the security, and charges a COMMISSION. A DEALER acts as principal from its own inventory and earns the markup or markdown embedded in the price. The confirmation must disclose which capacity the firm acted in, because the conflict is different in each case." },
  { id: "sie-mkt-104", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "A firm buys securities into its own inventory and resells them to a customer. It is acting as:",
    choices: ["A broker, earning a commission", "An investment adviser, earning a fee", "A dealer, earning a markup", "A transfer agent, earning a filing fee"],
    answerIndex: 2,
    explanation: "Trading from its own account makes the firm a PRINCIPAL — a dealer — and its compensation is the markup built into the price. It takes real ownership risk while holding the inventory, which is why the compensation model differs from an agency commission. Advisers charge fees for advice; transfer agents maintain records." },
  { id: "sie-mkt-105", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "The organisation that holds securities in book-entry form so ownership can change without certificates moving is the:",
    choices: ["Transfer agent", "Registrar", "Market maker", "Depository (DTC)"],
    answerIndex: 3,
    explanation: "The Depository Trust Company immobilises securities so that ownership transfers are ledger entries rather than physical deliveries. The TRANSFER AGENT maintains the issuer's ownership records; the REGISTRAR audits the transfer agent to prevent over-issuance; a market maker provides liquidity by quoting both sides." },
  { id: "sie-mkt-106", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "The registrar's role is deliberately separated from the transfer agent's in order to:",
    choices: ["Prevent the company from over-issuing shares", "Speed up the settlement cycle", "Reduce the cost of a new issue", "Provide liquidity in the secondary market"],
    answerIndex: 0,
    explanation: "The registrar audits the transfer agent to ensure the number of shares outstanding never exceeds the number authorised. Separating the two means no single party can both create the records and verify them — a basic control principle. It has nothing to do with settlement speed, issue cost, or liquidity." },
  { id: "sie-mkt-107", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Why does the issuer care about a liquid SECONDARY market, given it receives no proceeds from it?",
    choices: ["Because the issuer collects a fee on each secondary trade", "Liquidity lowers the return investors demand, reducing the issuer's cost of capital", "Because secondary trading is required before a primary offering", "It does not — issuers are indifferent to secondary trading"],
    answerIndex: 1,
    explanation: "No rational investor funds a thirty-year bond without a way out. The ability to sell in year four is what makes them willing to buy at issue, and it lowers the yield they demand — which directly lowers the issuer's cost of capital. The secondary market subsidises the primary one; issuers collect nothing from it directly." },
  { id: "sie-mkt-108", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "FINRA is best described as:",
    choices: ["A federal government agency", "A division of the Federal Reserve", "A self-regulatory organisation overseen by the SEC", "An industry trade association with no rulemaking power"],
    answerIndex: 2,
    explanation: "FINRA is an SRO: it writes conduct rules, licenses representatives, examines firms and disciplines them, all subject to SEC approval and oversight. It is not a government agency and has no connection to the Federal Reserve. It has real rulemaking and enforcement power, unlike a trade association." },
  { id: "sie-mkt-109", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which best describes the relationship between the FDIC and SIPC?",
    choices: ["Both insure against investment losses", "FDIC covers securities; SIPC covers deposits", "SIPC is a division of the FDIC", "FDIC insures bank deposits; SIPC protects brokerage customers if the firm fails"],
    answerIndex: 3,
    explanation: "FDIC insures BANK DEPOSITS against bank failure up to $250,000. SIPC protects BROKERAGE customers against broker-dealer failure up to $500,000. Neither protects against investment losses, and a security bought at a bank is not an FDIC-insured deposit — a disclosure requirement that exists because customers routinely assume otherwise." },
  { id: "sie-mkt-110", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 3,
    stem: "A pension fund buys 40,000 shares directly from another institution, negotiating price privately and bypassing the exchange. This trade occurred in the:",
    choices: ["Fourth market", "Third market", "Primary market", "Second market"],
    answerIndex: 0,
    explanation: "Institution-to-institution trading that bypasses exchanges entirely is the FOURTH market. The THIRD market is exchange-listed stock traded over the counter. Neither is the primary market, since the shares already exist and the issuer receives nothing. Note that 'primary vs secondary' and 'first through fourth market' are two different classifications, and the exam tests both." },
  { id: "sie-trd-121", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A MARKET order guarantees:",
    choices: ["The price, but not execution", "Execution, but not the price", "Both execution and price", "Neither execution nor price"],
    answerIndex: 1,
    explanation: "A market order fills immediately at the best available price, so execution is certain and price is not. A LIMIT order reverses that: your price or better, or no fill at all. No single order type guarantees both, which is the fundamental trade-off behind every order decision." },
  { id: "sie-trd-122", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A LIMIT order to buy will execute:",
    choices: ["At the limit price or higher", "Only exactly at the limit price", "At the limit price or lower", "At the next market price regardless"],
    answerIndex: 2,
    explanation: "A buy limit sets a CEILING: fill at that price or better, and better means lower. A sell limit sets a FLOOR — that price or higher. Requiring an exact match would make limits nearly unfillable, and ignoring the limit entirely describes a market order." },
  { id: "sie-trd-123", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "An investor owns stock at $60 and places a sell stop at $52. Overnight news drops the stock to $41 at the open. The order fills near:",
    choices: ["$52", "$60", "It does not fill", "$41"],
    answerIndex: 3,
    explanation: "A plain stop becomes a MARKET order once triggered, so it fills at the best available price after the gap — around $41. The stop guaranteed that a sale would occur, not the price. A stop-LIMIT at $52 would have avoided the bad fill but likely would not have executed at all, leaving the position falling." },
  { id: "sie-trd-124", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A STOP-LIMIT order, once triggered, becomes a:",
    choices: ["Limit order", "Market order", "Day order", "Fill or kill order"],
    answerIndex: 0,
    explanation: "A stop-limit converts to a LIMIT order at the trigger, which protects the execution price but reintroduces the risk of no fill — the very scenario the stop was meant to escape. A plain stop converts to a MARKET order, guaranteeing the sale but not the price. That single difference is the whole comparison." },
  { id: "sie-trd-125", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Under Regulation T, the initial margin requirement for a new equity purchase is:",
    choices: ["25%", "50%", "30%", "100%"],
    answerIndex: 1,
    explanation: "Reg T, set by the Federal Reserve, requires a 50% initial deposit on a new equity purchase. The 25% figure is FINRA's MAINTENANCE minimum for a long position, and 30% is the short-side maintenance requirement. Full payment applies to cash accounts, options and new issues." },
  { id: "sie-trd-126", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which account requires the customer to sign an agreement before trading?",
    choices: ["A cash account", "A custodial account", "A margin account", "A joint account"],
    answerIndex: 2,
    explanation: "A margin account requires a signed margin agreement containing the credit and hypothecation agreements, because the customer is borrowing and pledging collateral. A CASH account requires no customer signature, though a principal must still approve it. Custodial and joint accounts have their own documentation but no borrowing agreement." },
  { id: "sie-trd-127", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "The hypothecation agreement in a margin account allows the firm to:",
    choices: ["Lend the customer's securities to short sellers", "Trade the account at the firm's discretion", "Charge commissions above the disclosed rate", "Pledge the customer's securities as collateral for its own loan"],
    answerIndex: 3,
    explanation: "Hypothecation pledges the customer's securities as collateral so the firm can finance the margin loan. Lending those shares out requires the separate and OPTIONAL loan consent agreement. Discretion requires written authorization, and commissions must match what was disclosed." },
  { id: "sie-trd-128", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Front-running is best described as trading:",
    choices: ["Ahead of a known customer block order", "On material nonpublic corporate information", "Excessively to generate commissions", "Away from the firm without approval"],
    answerIndex: 0,
    explanation: "Front-running exploits knowledge of a pending customer order whose size is likely to move the price. Trading on material nonpublic corporate information is INSIDER trading, excessive trading for commissions is CHURNING, and doing securities business outside the firm is SELLING AWAY." },
  { id: "sie-trd-129", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A representative executes securities transactions outside their firm without notifying it. This is:",
    choices: ["Commingling", "Selling away", "Structuring", "Painting the tape"],
    answerIndex: 1,
    explanation: "Selling away is conducting securities business away from the employing firm without written notice and, where compensation is involved, approval. It defeats the firm's supervision entirely, which is why it is treated so seriously. Commingling mixes assets; structuring evades cash reporting; painting the tape fakes market activity." },
  { id: "sie-trd-130", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Deliberately placing a customer's fund purchase just below a breakpoint is:",
    choices: ["Permitted if the customer chose the amount", "Required to keep the investment diversified", "Breakpoint selling, a prohibited practice", "Acceptable with principal approval"],
    answerIndex: 2,
    explanation: "The representative has an affirmative duty to inform a customer when a modest increase would reach a breakpoint and cut the sales charge. Placing the order just below it keeps the charge — and the representative's compensation — high, which is the violation. Customer choice does not excuse the failure to inform." },
  { id: "sie-trd-131", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Mixing customer securities with the firm's own assets is called:",
    choices: ["Hypothecation", "Rehypothecation", "Netting", "Commingling"],
    answerIndex: 3,
    explanation: "Commingling is prohibited because customer property must remain identifiable and segregated from the firm's, so it is protected if the firm fails. Hypothecation is the legitimate pledging of customer securities as collateral under a signed agreement. Netting is an offsetting settlement process." },
  { id: "sie-trd-132", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Customer complaints must be reported to FINRA:",
    choices: ["Quarterly", "Monthly", "Annually", "Within 24 hours"],
    answerIndex: 0,
    explanation: "Written complaints concerning the firm's securities business are reported quarterly, and the firm must keep a written record of each. That record-keeping is what makes patterns visible across time and across representatives, which is the point of the requirement." },
  { id: "sie-trd-133", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "An account statement must be sent to a customer at least:",
    choices: ["Annually in all cases", "Quarterly, and monthly when there is activity", "Monthly in all cases", "Only on customer request"],
    answerIndex: 1,
    explanation: "Statements go out at least quarterly, and monthly in any month with activity. Confirmations are separate and must be sent at or before completion of each transaction, disclosing whether the firm acted as agent or principal." },
  { id: "sie-trd-134", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A customer identification program requires collecting all of the following EXCEPT:",
    choices: ["Name", "Date of birth", "The customer's annual investment return target", "Taxpayer identification number"],
    answerIndex: 2,
    explanation: "CIP collects identity information: name, date of birth, physical address and a taxpayer identification number, verified before the account may trade. A return target is an investment OBJECTIVE — gathered for suitability, not for identity verification. The two serve entirely different regulatory purposes." },
  { id: "sie-prd-201", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Preferred stock generally differs from common stock in that preferred:",
    choices: ["Carries greater voting power per share", "Has unlimited appreciation potential", "Ranks behind common in liquidation", "Pays a fixed dividend and usually carries no vote"],
    answerIndex: 3,
    explanation: "Preferred pays a fixed stated dividend, ranks ahead of common for dividends and liquidation, and normally carries no vote. Because the payment is fixed its price moves inversely with interest rates, much like a bond. Ranking behind common inverts the waterfall — common is always last." },
  { id: "sie-prd-202", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "When market interest rates RISE, the price of an existing fixed-coupon bond will:",
    choices: ["Fall", "Rise", "Stay the same", "Move in the same direction as rates"],
    answerIndex: 0,
    explanation: "A bond paying a fixed coupon becomes less competitive when new bonds offer more, so its price must fall until its yield matches. This inverse relationship is the single most heavily tested fact in fixed income, and longer maturities and lower coupons move the most for a given rate change." },
  { id: "sie-prd-203", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A bond trading at a DISCOUNT has a yield to maturity that is:",
    choices: ["Below its coupon rate", "Above its coupon rate", "Equal to its coupon rate", "Unrelated to its coupon rate"],
    answerIndex: 1,
    explanation: "At a discount the buyer collects the coupon AND gains as the price pulls up to par, so every forward-looking yield exceeds the nominal coupon: nominal < current < YTM. At a PREMIUM the entire ordering flips. Memorise the direction rather than any particular numbers." },
  { id: "sie-prd-204", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "An open-end mutual fund order placed at 11:00 a.m. is executed at:",
    choices: ["The prior day's closing NAV", "The NAV at the moment of the order", "The next NAV computed, normally at the 4:00 p.m. close", "A price negotiated with the fund"],
    answerIndex: 2,
    explanation: "Forward pricing fills the order at the NEXT NAV calculated, which stops traders exploiting stale prices with information arriving during the day. Using the prior close would create exactly that arbitrage. Open-end fund shares do not trade intraday at all — that describes ETFs and closed-end funds." },
  { id: "sie-prd-205", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which pooled vehicle holds a FIXED portfolio and has no investment adviser making ongoing decisions?",
    choices: ["An open-end mutual fund", "A closed-end fund", "An actively managed ETF", "A unit investment trust"],
    answerIndex: 3,
    explanation: "A UIT holds a fixed, unmanaged portfolio and terminates on a preset date — it has no board and no adviser, which is precisely what distinguishes it. Open-end funds, closed-end funds and active ETFs all have ongoing management making decisions about what to hold." },
  { id: "sie-prd-206", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A call option gives its OWNER the right to:",
    choices: ["Buy the underlying at the strike price", "Sell the underlying at the strike price", "Collect a dividend on the underlying", "Vote the underlying shares"],
    answerIndex: 0,
    explanation: "A call is the right to BUY at the strike; a PUT is the right to sell. The owner holds a right and the writer holds an obligation, which is why a buyer's loss is capped at the premium while a naked call writer's loss is theoretically unlimited. Options confer no dividend or voting rights." },
  { id: "sie-prd-207", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor owns a 50 call while the stock trades at $58. The option's intrinsic value is:",
    choices: ["$50", "$8", "$58", "Zero, until exercised"],
    answerIndex: 1,
    explanation: "Intrinsic value for a call is stock minus strike: $58 − $50 = $8, and it can never be negative. Intrinsic value ignores what was paid — if the premium was $5, the position is in-the-money by $8 but nets only $3. Being in-the-money and being profitable are different tests." },
  { id: "sie-prd-208", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which risk is UNSYSTEMATIC and therefore diversifiable?",
    choices: ["Market risk", "Inflation risk", "Business risk", "Interest rate risk"],
    answerIndex: 2,
    explanation: "Business risk is specific to one company and offsets across a diversified portfolio. Market, inflation and interest rate risk are all SYSTEMATIC — they move everything at once and cannot be diversified away, which is precisely why they are the risks investors are compensated for bearing." },
  { id: "sie-prd-209", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A Ginnie Mae pass-through security differs from a Fannie Mae security because Ginnie Mae carries:",
    choices: ["A higher coupon in every interest rate environment", "No prepayment risk whatsoever", "State and local tax exemption", "The explicit full faith and credit of the U.S. government"],
    answerIndex: 3,
    explanation: "Ginnie Mae is a government corporation within HUD and its securities carry the EXPLICIT full faith and credit guarantee. Fannie Mae and Freddie Mac are government-sponsored ENTERPRISES with only an assumed, implied backing. Both carry prepayment risk, and pass-through interest is fully taxable at all levels." },
  { id: "sie-prd-210", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A client in a high tax bracket seeking tax-free income should generally avoid holding municipal bonds in:",
    choices: ["An IRA", "A taxable brokerage account", "A joint account", "A trust account"],
    answerIndex: 0,
    explanation: "An IRA is already tax-deferred, so putting a tax-exempt bond inside one surrenders the muni's lower pre-tax yield for a benefit the account already provides. It is a classic unsuitable recommendation. In a TAXABLE account the exemption is exactly what the high-bracket client is paying for." },
  { id: "sie-prd-211", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Common stockholders have a claim on company assets that ranks:",
    choices: ["First, ahead of secured creditors", "Last, after all creditors and preferred shareholders", "Equal with bondholders", "Ahead of preferred shareholders"],
    answerIndex: 1,
    explanation: "Common stock is the RESIDUAL claim — paid only after every creditor and every preferred shareholder is satisfied. That last position is exactly why common carries the greatest risk and the greatest long-run return potential: there is no ceiling on the upside because there is no floor under the downside." },
  { id: "sie-prd-212", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Treasury stock is stock that has been:",
    choices: ["Authorized but never issued", "Issued by the U.S. Treasury", "Issued and then repurchased by the company", "Pledged as collateral for a loan"],
    answerIndex: 2,
    explanation: "Treasury stock is issued shares the company bought back. It carries no vote and receives no dividend — a company cannot pay itself — and it is excluded from shares OUTSTANDING, which is the figure that matters for EPS, voting and dividends. Despite the name it has nothing to do with the U.S. Treasury." },
  { id: "sie-prd-213", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A company has 10 million shares authorized, 6 million issued, and holds 1 million in treasury. Shares outstanding equal:",
    choices: ["6 million", "9 million", "10 million", "5 million"],
    answerIndex: 3,
    explanation: "Outstanding equals issued minus treasury: 6 million − 1 million = 5 million. Authorized is only the charter ceiling and says nothing about what is in public hands. Only the outstanding figure counts for earnings per share, voting and dividend payments." },
  { id: "sie-prd-214", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A rights offering allows existing shareholders to buy new shares at a price that is:",
    choices: ["Below the current market price", "Above the current market price", "Equal to the current market price", "Set by auction on the exchange"],
    answerIndex: 0,
    explanation: "Rights are priced BELOW market, which is what gives each right immediate computable value and lets shareholders preserve their proportional ownership. WARRANTS are the opposite — long-term and struck ABOVE market, so they carry no intrinsic value when issued." },
  { id: "sie-prd-215", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An American Depositary Receipt lets a U.S. investor hold foreign shares. The holder still bears:",
    choices: ["No risk beyond that of a domestic share", "Currency risk", "Only political risk", "Only liquidity risk"],
    answerIndex: 1,
    explanation: "An ADR removes the mechanics of foreign settlement but not the economics: the underlying is still denominated in a foreign currency, so exchange-rate moves flow through to the ADR's value. ADR holders also typically have no voting rights, and political risk in the issuer's home country remains." },
  { id: "sie-prd-216", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A 2-for-1 stock split results in:",
    choices: ["Twice the shares at the same price", "Half the shares at twice the price", "Twice the shares at half the price, same total value", "A taxable gain to the shareholder"],
    answerIndex: 2,
    explanation: "A split changes share count and price proportionally, leaving total position value unchanged — and the cost basis per share halves along with the price. Nothing is received, so there is no taxable event. A REVERSE split runs the other way, usually to maintain an exchange listing standard." },
  { id: "sie-prd-217", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A convertible bond with $1,000 par and a $40 conversion price converts into:",
    choices: ["40 shares", "400 shares", "2.5 shares", "25 shares"],
    answerIndex: 3,
    explanation: "Conversion ratio = par ÷ conversion price = $1,000 ÷ $40 = 25 shares. If the stock trades at $52, parity is 25 × $52 = $1,300, so the bond is worth at least that on conversion grounds. Dividing the other way or confusing price with ratio produces the distractors." },
  { id: "sie-prd-218", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which security represents OWNERSHIP rather than a loan?",
    choices: ["Common stock", "A corporate bond", "A Treasury note", "Commercial paper"],
    answerIndex: 0,
    explanation: "Equity is ownership; everything else listed is debt. A bondholder is a creditor with a contractual claim on interest and principal and ranks ahead of owners in liquidation. A shareholder owns a residual claim with no promised payment but unlimited upside." },
  { id: "sie-prd-219", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A zero-coupon bond's holder owes tax annually on:",
    choices: ["Nothing until the bond matures", "Phantom accreted interest never received in cash", "The full face value each year", "Dividends declared by the issuer"],
    answerIndex: 1,
    explanation: "A zero pays no cash interest, but the discount accretes toward par each year and the IRS treats that accretion as taxable interest income — phantom income, taxed without cash to pay it. That is why zeros are often held in tax-deferred accounts. Bonds pay interest, not dividends." },
  { id: "sie-prd-220", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which bond feature would a bondholder most want in a falling-rate environment?",
    choices: ["A call provision", "A shorter maturity", "Call protection", "A lower coupon"],
    answerIndex: 2,
    explanation: "When rates fall, issuers call bonds to refinance cheaply, stripping the holder of an above-market coupon and forcing reinvestment at lower rates. CALL PROTECTION prevents that for a stated period. A call provision is what the holder is trying to avoid, and short maturities and low coupons both reduce the gain from falling rates." },
  { id: "sie-prd-221", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "The par value of a corporate bond is conventionally:",
    choices: ["$100", "$500", "$10,000", "$1,000"],
    answerIndex: 3,
    explanation: "Corporate bonds are conventionally $1,000 par, and bond quotes are a PERCENTAGE of that — a quote of 98 means $980. Preferred stock conventionally uses $100 par, which is why a 6% preferred pays $6 a year. Mixing the two conventions is a common source of arithmetic errors." },
  { id: "sie-prd-222", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A municipal bond's interest is generally exempt from federal tax, but the CAPITAL GAIN on selling it is:",
    choices: ["Fully taxable", "Also exempt", "Exempt only in the issuer's state", "Taxed at half the ordinary rate"],
    answerIndex: 0,
    explanation: "Only the INTEREST enjoys the federal exemption. A gain from selling a muni above the purchase price is a capital gain and is fully taxable like any other. Candidates routinely over-generalise the exemption, which is exactly why the exam tests it." },
  { id: "sie-prd-223", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A general obligation municipal bond is backed by:",
    choices: ["The revenues of a single financed facility", "The issuer's full faith, credit, and taxing power", "A federal government guarantee", "A bank letter of credit in all cases"],
    answerIndex: 1,
    explanation: "A GO pledges the issuer's taxing power, which is why it usually requires voter approval and falls under statutory debt limits. A REVENUE bond is backed only by the receipts of the project it financed, with no recourse to taxing power. Municipal bonds carry no federal guarantee." },
  { id: "sie-prd-224", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is analysed using a DEBT SERVICE COVERAGE RATIO?",
    choices: ["A general obligation bond", "Common stock", "A revenue bond", "A money market fund"],
    answerIndex: 2,
    explanation: "Revenue bonds are repaid from a single project's receipts, so the analysis centres on whether net revenues comfortably exceed the payments due — the coverage ratio. GO analysis instead examines the TAX BASE: assessed values, debt per capita, and collection trends." },
  { id: "sie-prd-225", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A closed-end fund's market price:",
    choices: ["Always equals net asset value", "Is set once daily by the fund", "Is guaranteed by the sponsor", "May trade above or below its net asset value"],
    answerIndex: 3,
    explanation: "A closed-end fund issues a fixed share count once and then trades on an exchange, so supply and demand set the price and it may sit at a persistent premium or discount to NAV. Open-end funds transact at NAV by definition. ETFs trade intraday too, but arbitrage keeps them close to NAV." },
  { id: "sie-trd-135", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "In a TENANTS IN COMMON account, a deceased owner's share passes to:",
    choices: ["The deceased owner's estate", "The surviving owner automatically", "The broker-dealer", "FINRA"],
    answerIndex: 0,
    explanation: "Tenants in common sends the deceased's share to their ESTATE under their will. JTWROS is the registration that passes it automatically to the survivor outside probate. Same two people, same assets, opposite outcome — which is why the registration choice is substantive." },
  { id: "sie-trd-136", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "How many minors may be named on a single UTMA custodial account?",
    choices: ["Two", "One", "Any number of siblings", "Unlimited"],
    answerIndex: 1,
    explanation: "One custodian and one minor per account. Assets belong to that minor from the moment of the irrevocable gift, so commingling two children's property in one account would be incompatible with the structure." },
  { id: "sie-trd-137", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A custodian in a UTMA account may NOT:",
    choices: ["Buy common stock", "Sell securities held in the account", "Trade the account on margin", "Reinvest dividends"],
    answerIndex: 2,
    explanation: "Margin and speculative strategies are off limits because the standard is prudent management of property belonging to someone else. Ordinary purchases, sales and reinvestment are all within the custodian's authority — the restriction targets leverage and speculation, not activity." },
  { id: "sie-trd-138", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "An options account requires the options disclosure document to be delivered:",
    choices: ["Within 15 days after the first trade", "Only on customer request", "Annually thereafter", "At or before account approval"],
    answerIndex: 3,
    explanation: "The ODD must reach the customer at or before the time the account is approved for options. Separately, the signed options agreement is due within 15 days of approval; if it does not arrive, the account may only CLOSE existing positions, not open new ones." },
  { id: "sie-trd-139", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which regulator administers the SIE exam?",
    choices: ["FINRA", "The SEC", "The MSRB", "SIPC"],
    answerIndex: 0,
    explanation: "FINRA writes the conduct rules, licenses representatives and administers this exam. The SEC oversees FINRA as a self-regulatory organisation but does not run the exam. The MSRB writes municipal rules with no enforcement power, and SIPC protects customers when a firm fails." },
  { id: "sie-trd-140", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A trade confirmation must disclose whether the firm acted as:",
    choices: ["Buyer or seller of last resort", "Agent or principal", "Underwriter or trustee", "Custodian or registrar"],
    answerIndex: 1,
    explanation: "Capacity disclosure is required because the conflict differs entirely: an AGENT charges a commission and stands between two parties, while a PRINCIPAL trades from inventory and earns a markup embedded in the price. The customer cannot evaluate the cost without knowing which occurred." },
  { id: "sie-trd-141", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A cash account requires the customer to pay for a purchase:",
    choices: ["Half up front under Reg T", "Nothing until the position is sold", "In full", "Only if the position declines"],
    answerIndex: 2,
    explanation: "A cash account requires full payment — no borrowing is involved, which is the whole distinction from a margin account. Reg T's 50% deposit applies to MARGIN purchases. Nothing about a cash account defers payment or ties it to performance." },
  { id: "sie-trd-142", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which retirement account has NO required minimum distributions during the original owner's lifetime?",
    choices: ["Traditional IRA", "401(k)", "SEP IRA", "Roth IRA"],
    answerIndex: 3,
    explanation: "The Roth is funded with after-tax dollars, so the government has already been paid and has no reason to force withdrawals. Traditional IRAs, 401(k)s and SEPs are all tax-deferred, so RMDs begin at 73 under current law to start collecting the deferred tax." },
  { id: "sie-trd-143", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A withdrawal from a traditional IRA before age 59½ generally incurs:",
    choices: ["A 10% penalty plus ordinary income tax", "A 10% penalty only", "Ordinary income tax only", "No penalty if under $10,000"],
    answerIndex: 0,
    explanation: "The distribution is taxable as ordinary income AND carries a 10% early-withdrawal penalty. Narrow exceptions exist — death, disability, first-time home purchase, certain medical and education expenses — but the default is both. A dollar threshold alone does not exempt it." },
  { id: "sie-trd-144", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is a LEADING economic indicator?",
    choices: ["The unemployment rate", "Building permits", "Corporate profits", "The prime rate"],
    answerIndex: 1,
    explanation: "Building permits are issued before ground is broken, so they anticipate activity. Unemployment is the classic LAGGING indicator — firms cut and hire only after conditions have clearly changed. Corporate profits and the prime rate also lag." },
  { id: "sie-trd-145", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Insider trading liability extends to:",
    choices: ["Only corporate officers and directors", "Only the person who first learned the information", "Anyone who receives a tip and trades on it", "Only trades exceeding $50,000"],
    answerIndex: 2,
    explanation: "Liability reaches tippees, not just the original source — receiving material nonpublic information and trading on it is enough. There is no dollar threshold, and the rule is not limited to insiders by title. Penalties can reach three times the profit gained or loss avoided." },
  { id: "sie-trd-146", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A registered representative wants to work a second job unrelated to securities. They must:",
    choices: ["Do nothing, since it is unrelated", "Obtain SEC approval", "Resign their registration", "Provide prior written notice to the firm"],
    answerIndex: 3,
    explanation: "Outside business activities must be disclosed to the firm in writing BEFORE engaging in them, regardless of whether they involve securities — the firm decides whether a conflict exists, not the representative. Private SECURITIES transactions carry the additional requirement of firm approval where compensation is involved." },
  { id: "sie-trd-147", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "The three stages of money laundering, in order, are:",
    choices: ["Placement, layering, integration", "Layering, placement, integration", "Integration, placement, layering", "Placement, integration, layering"],
    answerIndex: 0,
    explanation: "PLACEMENT puts illicit cash into the financial system, LAYERING moves it through complex transactions to obscure its origin, and INTEGRATION returns it looking legitimate. The order matters because the firm's controls target each stage differently — CIP catches placement, transaction monitoring catches layering." },
  { id: "sie-trd-148", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "OFAC maintains a list that firms must screen customers against. It is the list of:",
    choices: ["Statutorily disqualified representatives", "Specially Designated Nationals", "Restricted persons for IPO purchases", "Accredited investors"],
    answerIndex: 1,
    explanation: "OFAC publishes the Specially Designated Nationals list, and firms must screen against it and block prohibited transactions. Statutory disqualification concerns who may associate with a member firm, restricted persons concerns new equity issues under Rule 5130, and accredited investor status concerns private placements." },
  { id: "sie-trd-149", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A firm inadvertently receives customer funds it should not hold. To avoid being deemed to have custody it should:",
    choices: ["Hold them in a segregated account indefinitely", "Apply them to the customer's next purchase", "Return them promptly, generally within three business days", "Report the receipt to FINRA and retain them"],
    answerIndex: 2,
    explanation: "Prompt return — typically within three business days — avoids the custody designation and the surprise-examination and qualified-custodian requirements that follow it. Holding the funds, however segregated, is precisely what constitutes custody. Reporting does not cure it." },
  { id: "sie-trd-150", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Most broker-dealer books and records must be retained for at least:",
    choices: ["One year", "Five years in all cases", "Ten years in all cases", "Three years, the first two easily accessible"],
    answerIndex: 3,
    explanation: "The general rule is three years with the first two in an easily accessible place. Certain records — customer account records, articles of incorporation, partnership agreements — run six years or the life of the firm. One year is never sufficient for any category." },
  { id: "sie-prd-226", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which of these is a SYSTEMATIC risk?",
    choices: ["Interest rate risk", "Credit risk", "Liquidity risk", "Regulatory risk"],
    answerIndex: 0,
    explanation: "Interest rate risk moves all fixed-income prices at once and cannot be diversified away. Credit, liquidity and regulatory risk are all issuer- or industry-specific — unsystematic — and offset across a diversified portfolio. Only systematic risk carries an expected return premium." },
  { id: "sie-prd-227", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A mutual fund's net asset value is computed:",
    choices: ["Continuously throughout the trading day", "Once per day, after the market close", "Weekly", "Only when shares are redeemed"],
    answerIndex: 1,
    explanation: "NAV is struck once daily, normally at the 4:00 p.m. close, and every order that day fills at that next computed NAV under forward pricing. Continuous intraday pricing describes exchange-traded products, not open-end funds." },
  { id: "sie-prd-228", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "The maximum sales charge FINRA permits on a mutual fund is:",
    choices: ["5% of the amount invested", "3% of net asset value", "8.5% of the public offering price", "There is no limit"],
    answerIndex: 2,
    explanation: "8.5% of the POP is the ceiling, and a fund may only charge the maximum if it offers breakpoints, rights of accumulation, and reinvestment of dividends at NAV. A fund omitting those features must charge less. Note the charge is measured against the POP, not the NAV." },
  { id: "sie-prd-229", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which mutual fund share class is the ONLY one eligible for breakpoints?",
    choices: ["Class B", "Class C", "All classes equally", "Class A"],
    answerIndex: 3,
    explanation: "Only Class A shares, which carry the front-end load, receive breakpoint discounts. Class B uses a contingent deferred charge that declines over time, and Class C carries a level load with permanently higher annual expenses. That is why a large, long-horizon investment belongs in Class A." },
  { id: "sie-prd-230", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A letter of intent allows an investor to claim a breakpoint now by committing to invest the total within:",
    choices: ["13 months", "6 months", "12 months", "24 months"],
    answerIndex: 0,
    explanation: "13 months, and it may be backdated up to 90 days to capture a recent purchase. RIGHTS OF ACCUMULATION differ: they count existing holdings toward the next breakpoint and never expire, so no commitment is required." },
  { id: "sie-prd-231", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A REIT must distribute at least what share of taxable income to keep its tax treatment?",
    choices: ["50%", "90%", "75%", "100%"],
    answerIndex: 1,
    explanation: "At least 90%, which is exactly why REITs are held for income. Note the feature that separates a REIT from a DPP: a REIT passes through INCOME but not losses, while a direct participation program passes through both." },
  { id: "sie-prd-232", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor buys a put option. Their maximum loss is:",
    choices: ["The strike price", "Unlimited", "The premium paid", "The strike minus the premium"],
    answerIndex: 2,
    explanation: "A buyer's loss is always capped at the premium — they hold a right, not an obligation, and can simply let it expire. The strike minus premium is the maximum GAIN on a long put, realised if the stock falls to zero. Unlimited loss belongs only to the naked call WRITER." },
  { id: "sie-prd-233", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which position carries theoretically UNLIMITED loss?",
    choices: ["A long call buyer", "A long put buyer", "A covered call writer", "A naked call writer"],
    answerIndex: 3,
    explanation: "There is no ceiling on how high a stock can rise, so an uncovered call writer's obligation is unbounded — which is why naked call writing carries the strictest approval and margin requirements. Buyers risk only the premium, and a covered writer already owns the stock to deliver." },
  { id: "sie-prd-234", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Treasury bills are issued with a maturity of:",
    choices: ["One year or less", "Two to ten years", "Over ten years", "Thirty years exactly"],
    answerIndex: 0,
    explanation: "T-bills mature in one year or less (4 to 52 weeks), are sold at a discount with no coupon, and mature at face value. Two to ten years describes Treasury NOTES; over ten years describes Treasury BONDS. Both notes and bonds pay semiannual coupons." },
  { id: "sie-prd-235", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "TIPS protect an investor by adjusting:",
    choices: ["The coupon rate each quarter", "Principal with the Consumer Price Index", "The maturity date with inflation", "The credit rating with economic conditions"],
    answerIndex: 1,
    explanation: "TIPS adjust PRINCIPAL with the CPI, so both the coupon payments (a fixed rate applied to rising principal) and the final principal grow with inflation. That addresses purchasing power risk, the systematic risk that erodes fixed payments and hits long-dated bonds hardest." },
  { id: "sie-mkt-111", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "An initial public offering takes place in the:",
    choices: ["Secondary market", "Third market", "Primary market", "Fourth market"],
    answerIndex: 2,
    explanation: "An IPO sells newly created shares for the first time and the ISSUER receives the proceeds, which is the definition of a primary market transaction. Third and fourth markets are both classifications WITHIN the secondary market, describing venue rather than whether the security is new." },
  { id: "sie-mkt-112", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "The THIRD market refers to:",
    choices: ["Institution-to-institution trades bypassing exchanges", "New issues sold directly to institutions", "Foreign securities traded in the U.S.", "Exchange-listed securities traded over the counter"],
    answerIndex: 3,
    explanation: "The third market is listed stock traded OTC. The FOURTH market is institution to institution, bypassing exchanges entirely. Both sit inside the secondary market — 'primary vs secondary' and 'first through fourth' are two different classifications and the exam tests both." },
  { id: "sie-mkt-113", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "A market maker earns compensation from:",
    choices: ["The bid-ask spread", "A commission on each trade", "An advisory fee", "An underwriting concession"],
    answerIndex: 0,
    explanation: "A market maker quotes a continuous two-sided market and profits from the spread between what it pays and what it receives, taking inventory risk in exchange. Commissions belong to agency brokers, advisory fees to investment advisers, and concessions to selling-group members in a new issue." },
  { id: "sie-mkt-114", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "The transfer agent's principal responsibility is to:",
    choices: ["Guarantee the issuer's dividend payments", "Maintain the record of who owns the issuer's securities", "Set the offering price of a new issue", "Make a market in the issuer's stock"],
    answerIndex: 1,
    explanation: "The transfer agent maintains ownership records, issues and cancels certificates, and handles lost or stolen ones. It guarantees nothing and prices nothing. The REGISTRAR audits the transfer agent so that no single party both creates and verifies the records." },
  { id: "sie-prd-236", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Cumulative preferred stock differs from non-cumulative because missed dividends:",
    choices: ["Are permanently forgiven", "Convert automatically into common shares", "Accumulate and must be paid before any common dividend", "Increase the par value of the preferred"],
    answerIndex: 2,
    explanation: "Cumulative means arrears build up and the whole backlog must clear before common receives anything. On NON-cumulative preferred a skipped dividend is simply gone. Conversion is a separate feature, and par value never changes with missed payments." },
  { id: "sie-prd-237", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A 6% cumulative preferred ($100 par) skipped two years. Before common is paid, the holder receives:",
    choices: ["$12", "$6", "$606", "$18"],
    answerIndex: 3,
    explanation: "Annual dividend is 6% of $100 par = $6. Two skipped years accumulate to $12, plus the current year's $6, for $18 per share. The $12 figure omits the current year and $6 counts only the current year — both are the arrears calculation done halfway." },
  { id: "sie-prd-238", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Participating preferred stock may receive:",
    choices: ["More than its stated dividend rate", "Only its stated rate, never more", "Dividends before secured creditors", "Voting rights equal to common"],
    answerIndex: 0,
    explanation: "Participating preferred can share in additional distributions beyond the fixed stated rate when the company performs well. Straight preferred is capped at its stated rate. No equity is ever paid before creditors, and preferred normally carries no vote at all." },
  { id: "sie-prd-239", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Callable preferred stock is a feature that benefits:",
    choices: ["The holder, who can force redemption", "The issuer, who can redeem when rates fall", "Both parties equally", "Neither party in practice"],
    answerIndex: 1,
    explanation: "The call belongs to the ISSUER and is exercised when rates have fallen and the fixed dividend has become expensive to keep paying. That caps the holder's upside at exactly the wrong moment. A feature letting the HOLDER force redemption would be a put, not a call." },
  { id: "sie-prd-240", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Warrants are typically issued:",
    choices: ["To existing shareholders in a rights offering", "By the U.S. Treasury at auction", "Attached to a bond offering as a sweetener", "Only to institutional investors"],
    answerIndex: 2,
    explanation: "Warrants are long-term and usually attached to a debt issue to make it more attractive, struck ABOVE the current market so they carry no intrinsic value at issue. RIGHTS go to existing shareholders, are short-term, and are struck BELOW market so they have immediate value." },
  { id: "sie-prd-241", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A stock's ex-dividend price typically opens:",
    choices: ["Higher by roughly the dividend amount", "Unchanged, since the dividend is separate", "At the prior day's high", "Lower by roughly the dividend amount"],
    answerIndex: 3,
    explanation: "A buyer on the ex-date is purchasing the same company minus an imminent cash payment, so the price adjusts down by approximately the dividend. Existing holders lose nothing — they receive that value as cash instead of share price." },
  { id: "sie-prd-242", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A bond quoted at 98 has a dollar price of:",
    choices: ["$980", "$98", "$9,800", "$1,098"],
    answerIndex: 0,
    explanation: "Corporate bond quotes are a PERCENTAGE of $1,000 par, so 98 means 98% of par = $980. Reading the quote as dollars gives $98, which would be an implausible price for a bond. Government notes use a different convention entirely — 32nds, written with a hyphen." },
  { id: "sie-prd-243", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A Treasury note quoted 99-16 has a price of:",
    choices: ["99.16% of par", "99.5% of par", "99.016% of par", "116% of par"],
    answerIndex: 1,
    explanation: "Government notes and bonds are quoted in 32nds: 16/32 = 0.5, so 99-16 is 99.5% of par, or $995 on $1,000. Reading the digits after the hyphen as decimals gives 99.16% and is the error the convention is designed to catch." },
  { id: "sie-prd-244", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which bond type is backed only by the general credit of the issuer, with no specific collateral?",
    choices: ["A mortgage bond", "An equipment trust certificate", "A debenture", "A collateral trust bond"],
    answerIndex: 2,
    explanation: "A debenture pledges nothing specific — it rests on the issuer's general creditworthiness. Mortgage bonds pledge real property, equipment trust certificates pledge rolling stock, and collateral trust bonds pledge securities the issuer owns." },
  { id: "sie-prd-245", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Accrued interest on a CORPORATE bond is calculated using:",
    choices: ["Actual/actual", "Actual/360", "30/365", "30/360"],
    answerIndex: 3,
    explanation: "Corporate and municipal bonds use 30/360 — every month counts as 30 days, the year as 360. GOVERNMENT bonds use actual/actual, real calendar days over the real year. Interest accrues from the last coupon date up to but NOT including settlement." },
  { id: "sie-prd-246", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "An ETF differs from an open-end mutual fund primarily because the ETF:",
    choices: ["Trades intraday at market prices", "Is priced only once per day", "Cannot be sold short", "Has no expense ratio"],
    answerIndex: 0,
    explanation: "An ETF trades on an exchange throughout the session, so the execution price is known at the moment of the trade. An open-end fund uses forward pricing and fills at the next computed NAV. ETFs can be sold short and do carry expense ratios." },
  { id: "sie-prd-247", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A 12b-1 fee covers:",
    choices: ["The front-end sales load", "Distribution and marketing costs, charged annually against assets", "Portfolio manager compensation only", "Custodial safekeeping only"],
    answerIndex: 1,
    explanation: "The 12b-1 fee pays for distribution and marketing and is deducted annually from fund assets, so it compounds against the investor over time. A fund charging more than 0.25% may not call itself no-load. It is separate from any front-end or deferred sales charge." },
  { id: "sie-prd-248", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Rights of accumulation differ from a letter of intent because rights of accumulation:",
    choices: ["Require a 13-month commitment", "Apply only to Class C shares", "Count existing holdings and never expire", "Eliminate the sales charge entirely"],
    answerIndex: 2,
    explanation: "Rights of accumulation count what the investor already holds toward the next breakpoint, with no commitment and no expiry. A LETTER OF INTENT claims a breakpoint now against a promise to invest the total within 13 months. Neither eliminates the charge; both reduce it." },
  { id: "sie-prd-249", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A hedge fund is typically available only to:",
    choices: ["Any retail investor", "Investors under age 59½", "Municipal employees", "Accredited investors"],
    answerIndex: 3,
    explanation: "Hedge funds are sold through private placements to accredited investors, who qualify on income, net worth excluding primary residence, or professional credentials. They are illiquid, lightly regulated compared with registered funds, and carry no retail suitability presumption." },
  { id: "sie-prd-250", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor seeking current income with the lowest credit risk should consider:",
    choices: ["Treasury securities", "High-yield corporate bonds", "Small-cap growth stocks", "Naked call writing"],
    answerIndex: 0,
    explanation: "Treasuries carry the full faith and credit of the United States and are considered free of credit risk, though not of interest rate risk. High-yield bonds are speculative-grade by definition, growth stocks pay little or no income, and naked call writing is a speculative strategy with unlimited loss." },
  { id: "sie-prd-251", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Reinvestment risk is greatest for a bond with:",
    choices: ["A zero coupon held to maturity", "A high coupon and a call provision", "A very long maturity and low coupon", "No coupon and no call feature"],
    answerIndex: 1,
    explanation: "Reinvestment risk is the risk of having to redeploy cash at lower rates, so it grows with how much cash comes back early — a high coupon plus a call means large, frequent payments and a possible early return of principal. A ZERO pays nothing until maturity, so it has essentially no reinvestment risk." },
  { id: "sie-prd-252", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which product is NOT a security?",
    choices: ["A variable annuity", "A variable life policy", "A fixed annuity", "A mutual fund"],
    answerIndex: 2,
    explanation: "A fixed annuity is funded from the insurer's general account and the INSURER bears investment risk, so it is an insurance product only. Variable annuities and variable life use the SEPARATE account, putting risk on the holder, which makes them securities. Mutual funds are securities by definition." },
  { id: "sie-prd-253", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor is 30 years old with a long horizon and high risk tolerance. The least suitable recommendation is:",
    choices: ["A diversified equity fund", "A growth-oriented ETF", "A balanced fund", "A money market fund for the entire portfolio"],
    answerIndex: 3,
    explanation: "A money market fund for the whole portfolio wastes a thirty-year horizon on an instrument that barely outpaces inflation — the mismatch is between the product and the TIME HORIZON, not the risk tolerance. The other three all permit long-run growth appropriate to the profile." },
  { id: "sie-prd-254", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which pair correctly matches an objective to a product?",
    choices: ["Preservation of capital — Treasury bills", "Preservation of capital — small-cap equity", "Aggressive growth — money market fund", "Current income — zero-coupon bonds"],
    answerIndex: 0,
    explanation: "T-bills are short, government-backed and highly liquid, which is exactly what preservation of capital requires. Small-cap equity is the opposite. A money market fund cannot deliver aggressive growth, and a zero pays no current income at all — it pays everything at maturity." },
  { id: "sie-trd-151", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A discretionary order must be:",
    choices: ["Executed only at the market open", "Marked as discretionary and reviewed", "Approved by the SEC in advance", "Limited to $10,000 in value"],
    answerIndex: 1,
    explanation: "Every discretionary order must be identified as such and reviewed, which is how the firm supervises an authority that bypasses the customer on each trade. The written authorization must be in place beforehand. No dollar cap or timing restriction applies." },
  { id: "sie-trd-152", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A registered representative may accept verbal discretion only as to:",
    choices: ["The security to be purchased", "The dollar amount to invest", "Time and price of a specified trade, for that day", "Whether to trade at all"],
    answerIndex: 2,
    explanation: "The narrow exception covers TIME and PRICE on a specified security and quantity, and it is good only for that day. Choosing the SECURITY, the AMOUNT, or WHETHER to trade is full discretion and always requires prior written authorization." },
  { id: "sie-trd-153", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which account type requires a corporate resolution?",
    choices: ["An individual account", "A JTWROS account", "A UTMA account", "A corporate account"],
    answerIndex: 3,
    explanation: "A corporate resolution names the individuals authorized to trade on the entity's behalf. A partnership account needs the partnership agreement for the same reason. Individual, joint and custodial accounts each have their own documentation but no corporate authorization." },
  { id: "sie-trd-154", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "The purpose of the customer identification program is to:",
    choices: ["Verify who the customer is before the account trades", "Determine the customer's risk tolerance", "Set the account's margin limit", "Assign a registered representative"],
    answerIndex: 0,
    explanation: "CIP verifies IDENTITY — name, date of birth, address and taxpayer identification number — and is an anti-money-laundering requirement. Risk tolerance and objectives are gathered for SUITABILITY, an entirely separate purpose serving a different rule." },
  { id: "sie-trd-155", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "An unsolicited order that the representative believes is unwise:",
    choices: ["Must be refused", "May generally be executed, but must be marked unsolicited", "Requires written customer acknowledgment of the risk", "Must be approved by FINRA first"],
    answerIndex: 1,
    explanation: "Suitability obligations attach to RECOMMENDATIONS, and an unsolicited order carries none — the customer initiated it. The firm must mark it unsolicited, and mismarking a solicited trade to escape the suitability analysis is a serious violation and a common fact pattern." },
  { id: "sie-prd-255", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "The holder of a put option profits when the underlying stock:",
    choices: ["Rises above the strike price", "Stays exactly at the strike price", "Falls below the strike price by more than the premium", "Pays a larger dividend"],
    answerIndex: 2,
    explanation: "A put is the right to SELL at the strike, so it gains value as the stock falls — but the fall must exceed the premium paid before the position profits. Breakeven for a long put is strike minus premium. Rising prices benefit the call buyer instead." },
  { id: "sie-prd-256", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An option contract normally covers:",
    choices: ["1 share", "500 shares", "1,000 shares", "100 shares"],
    answerIndex: 3,
    explanation: "The standard equity option contract covers 100 shares, which is why a premium quoted as 5 costs $500. Forgetting the multiplier is one of the most common arithmetic errors in options questions — every per-share figure must be multiplied by 100 for the contract." },
  { id: "sie-prd-257", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An option with a $50 strike on a stock trading at $44 is:",
    choices: ["Out-of-the-money if it is a call", "In-the-money if it is a call", "At-the-money regardless of type", "Worthless in all cases"],
    answerIndex: 0,
    explanation: "A call is in-the-money only when the stock is ABOVE the strike, so at $44 against a $50 strike the call is out-of-the-money with zero intrinsic value. The same $50 PUT would be in-the-money by $6. An out-of-the-money option still has time value and is not worthless before expiry." },
  { id: "sie-prd-258", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which organisation issues and guarantees every listed option?",
    choices: ["FINRA", "The Options Clearing Corporation", "The SEC", "The Depository Trust Company"],
    answerIndex: 1,
    explanation: "The OCC stands between every buyer and writer, which removes counterparty risk — a holder never has to worry about whether the specific person who sold the option can perform. FINRA and the SEC regulate; DTC holds securities in book-entry form." },
  { id: "sie-prd-259", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A money market fund seeks to maintain a stable net asset value of:",
    choices: ["$10.00 per share", "$100.00 per share", "$1.00 per share", "Whatever the portfolio yields"],
    answerIndex: 2,
    explanation: "Retail money market funds aim to hold a $1.00 NAV, which is what lets investors treat them as a cash equivalent. Falling below that — 'breaking the buck' — is rare and notable precisely because the stable value is the product's entire purpose." },
  { id: "sie-prd-260", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor concerned about outliving their savings faces:",
    choices: ["Credit risk, addressed by diversification", "Prepayment risk, addressed by shorter maturities", "Currency risk, addressed by hedging", "Longevity risk, which an annuity is designed to address"],
    answerIndex: 3,
    explanation: "Longevity risk is the risk of living longer than the money lasts, and an annuity addresses it by converting a sum into income the insurer must pay for life. Credit, prepayment and currency risks are all real but concern the securities held, not the duration of the holder's life." },
  { id: "sie-prd-261", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is TRUE of a bond selling at a PREMIUM?",
    choices: ["Its yield to maturity is below its coupon rate", "Its yield to maturity is above its coupon rate", "Its current yield equals its coupon rate", "It must be in default"],
    answerIndex: 0,
    explanation: "At a premium the buyer will lose the premium as the price pulls down to par, so every forward-looking yield falls below the coupon: nominal > current > YTM > YTC. At a DISCOUNT the ordering flips entirely. A premium usually signals a coupon above current market rates — the opposite of distress." },
  { id: "sie-prd-262", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which investor is LEAST suited to municipal bonds?",
    choices: ["A high-bracket taxable investor", "Someone in a low tax bracket", "A high-earner in the issuer's own state", "An investor seeking tax-free income"],
    answerIndex: 1,
    explanation: "The muni's benefit is the tax exemption, and its pre-tax yield is lower to compensate. A low-bracket investor gives up yield for an exemption worth little to them. In-state high earners get a double exemption and benefit most — and munis are unsuitable inside an IRA, which is already tax-deferred." },
  { id: "sie-trd-156", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Painting the tape refers to:",
    choices: ["Recording customer orders in the wrong sequence", "Marking confirmations after the close", "Trading among parties to create the appearance of activity", "Delaying a trade report to the tape"],
    answerIndex: 2,
    explanation: "Painting the tape manufactures the illusion of volume and interest by trading among cooperating parties. It is one of the manipulation family alongside matched orders, wash trades and marking the close — all of which create a false picture of the market." },
  { id: "sie-trd-157", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Matched orders are prohibited because they:",
    choices: ["Execute faster than the customer expects", "Are entered without principal approval", "Involve more than one broker-dealer", "Are prearranged to offset, creating fictitious activity"],
    answerIndex: 3,
    explanation: "In a matched order the buy and the sell are arranged in advance to cancel out, so the reported activity is fictitious. The wrong is the deception about market interest, not the speed, the approval chain, or the number of firms involved." },
  { id: "sie-trd-158", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A firm may lend a customer's securities to short sellers only with:",
    choices: ["A signed loan consent agreement", "The hypothecation agreement alone", "A verbal instruction", "Principal approval only"],
    answerIndex: 0,
    explanation: "The loan consent is a SEPARATE and optional part of the margin agreement. The hypothecation agreement covers pledging the securities as collateral for the firm's own financing, which is a different act. Neither can be substituted with a verbal instruction." },
  { id: "sie-trd-159", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which statement about a 401(k) is correct?",
    choices: ["It has no contribution limit", "It is an employer-sponsored salary deferral plan, often with a match", "It is available to any individual regardless of employment", "Withdrawals are always tax-free"],
    answerIndex: 1,
    explanation: "A 401(k) is offered by an employer, funded by salary deferral, and frequently matched — capturing that match is the highest-priority contribution because it is an immediate guaranteed return. Contributions are capped annually, and traditional 401(k) withdrawals are taxed as ordinary income." },
  { id: "sie-mkt-115", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "An investment adviser is compensated by:",
    choices: ["A commission on each trade", "The bid-ask spread", "A fee, typically a percentage of assets managed", "An underwriting concession"],
    answerIndex: 2,
    explanation: "Advisers charge fees for advice and ongoing management, which is what creates a fiduciary relationship rather than a transactional one. Commissions belong to agency brokers, the spread to market makers, and concessions to selling-group members distributing a new issue." },
  { id: "sie-mkt-116", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "A municipal advisor owes a fiduciary duty to:",
    choices: ["The investors who buy the bonds", "The underwriting syndicate", "The MSRB", "The municipal issuer it advises"],
    answerIndex: 3,
    explanation: "The municipal advisor represents the ISSUER and owes it a fiduciary duty — that relationship is precisely why the role was regulated after the financial crisis. Underwriters sit on the other side of the transaction, buying from the issuer to resell." },
  { id: "sie-mkt-117", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "The clearing corporation's role is to:",
    choices: ["Net the day's obligations so firms settle differences", "Set the price of each security", "Approve new securities for listing", "Insure customers against firm failure"],
    answerIndex: 0,
    explanation: "The NSCC nets obligations so that firms settle net differences rather than every gross transaction, which dramatically reduces the cash and securities that must move. Pricing is set by the market, listing by the exchange, and customer protection on firm failure by SIPC." },
  { id: "sie-mkt-118", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Which of these is an EXEMPT security under the Securities Act of 1933?",
    choices: ["An initial public offering of common stock", "A U.S. government security", "A corporate bond sold to the public", "A newly registered ETF"],
    answerIndex: 1,
    explanation: "U.S. government and municipal securities are exempt SECURITIES — exempt because of what they are. A private placement is an exempt TRANSACTION, exempt because of how it is sold. Public offerings of corporate stock, bonds and funds all require registration." },
  { id: "sie-reg-113", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "A preliminary prospectus is commonly called a:",
    choices: ["Tombstone", "Blue sky filing", "Red herring", "Green shoe"],
    answerIndex: 2,
    explanation: "The red herring is named for the red legend on its cover and contains no final price, since pricing happens on the eve of effectiveness. A tombstone is a strictly limited advertisement, blue sky refers to state registration, and a green shoe is an over-allotment option." },
  { id: "sie-reg-114", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "During the cooling-off period, a representative may:",
    choices: ["Accept an order and hold the funds", "Confirm an allocation at an agreed price", "Deliver the final prospectus", "Accept a non-binding indication of interest"],
    answerIndex: 3,
    explanation: "Indications of interest are permitted and bind neither party. Accepting orders or money, or confirming allocations, all constitute SELLING before effectiveness and are prohibited. The final prospectus does not yet exist — it is produced once the registration becomes effective." },
  { id: "sie-reg-115", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "The minimum cooling-off period between filing and effectiveness is:",
    choices: ["20 days", "10 days", "30 days", "90 days"],
    answerIndex: 0,
    explanation: "Twenty days is the statutory minimum, though in practice the period usually runs longer while the SEC comments on the filing. During it the underwriter may circulate a red herring, publish a tombstone, and gather indications of interest — but may not sell." },
  { id: "sie-reg-116", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Under FINRA Rule 5130, restricted persons may not purchase:",
    choices: ["Any security in the secondary market", "New EQUITY issues at the public offering price", "Municipal bonds in any offering", "Mutual fund shares"],
    answerIndex: 1,
    explanation: "The rule bars industry insiders — member firms, their associated persons, and materially supported immediate family — from capturing first-day gains on hot IPOs that belong to public customers. Note the boundary: it covers new EQUITY issues, not new debt offerings and not secondary trading." },
  { id: "sie-reg-117", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which statement about the SEC and a registered security is TRUE?",
    choices: ["SEC registration means the SEC judged the offering sound", "SEC approval guarantees the issuer's solvency", "The SEC never approves or endorses a security", "The SEC sets the offering price"],
    answerIndex: 2,
    explanation: "Registration is a DISCLOSURE regime, not a merit review — the SEC checks that required facts were disclosed, never that the investment is good. Claiming or implying SEC approval of a security is itself a violation. The price is set by the issuer and underwriter at pricing." },
  { id: "sie-reg-118", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "The Regulatory Element of continuing education must be completed:",
    choices: ["Every three years", "Every two years", "Only upon changing firms", "Annually by December 31"],
    answerIndex: 3,
    explanation: "FINRA Rule 1240 requires the Regulatory Element annually by December 31 for each registration category held; missing it makes the person CE inactive. The FIRM Element is separate — designed and delivered by the member firm from its own annual needs analysis." },
  { id: "sie-trd-160", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer buys 1,000 shares at $40 in a margin account. Under Reg T, the required deposit and the resulting debit balance are:",
    choices: ["$20,000 deposit, $20,000 debit", "$40,000 deposit, no debit", "$10,000 deposit, $30,000 debit", "$20,000 deposit, $40,000 debit"],
    answerIndex: 0,
    explanation: "The purchase costs $40,000. Reg T requires a 50% deposit, so the customer puts up $20,000 and the firm lends the remaining $20,000 — that loan IS the debit balance. The debit then stays fixed as the market moves, which is what makes every later equity calculation straightforward." },
  { id: "sie-trd-161", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "That customer's stock falls to $30. Their equity and margin status are:",
    choices: ["$10,000 equity, a maintenance call is issued", "$10,000 equity, no maintenance call", "$30,000 equity, no call", "$20,000 equity, a call is issued"],
    answerIndex: 1,
    explanation: "Equity is market value less the unchanged debit: $30,000 − $20,000 = $10,000. FINRA's 25% maintenance minimum on a $30,000 position is $7,500, and $10,000 clears it, so no call. The call would come only once market value fell to debit ÷ 0.75, about $26.67 per share — knowing the trigger turns a guess into arithmetic." },
  { id: "sie-trd-162", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which securities may NOT be purchased on margin?",
    choices: ["Listed common stock", "Corporate bonds", "New issues during the first 30 days", "Exchange-traded funds"],
    answerIndex: 2,
    explanation: "New issues generally must be held roughly 30 days before becoming marginable, and mutual fund shares and options must be paid for in full. Listed stock, corporate bonds and ETFs are all marginable once the standard requirements are met." },
  { id: "sie-trd-163", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "The minimum equity required to OPEN a margin account is generally:",
    choices: ["$5,000 regardless of the purchase", "$25,000 for any margin activity", "$10,000 for a retail customer", "$2,000, but never more than the purchase price in cash"],
    answerIndex: 3,
    explanation: "The $2,000 minimum applies, with the sensible caveat that a customer buying $1,500 of stock cannot be required to deposit more than the full price. The $25,000 figure belongs to the PATTERN DAY TRADER rule, a different requirement entirely." },
  { id: "sie-trd-164", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer sells short 100 shares at $50. The credit balance in the account is:",
    choices: ["$7,500", "$5,000", "$2,500", "$10,000"],
    answerIndex: 0,
    explanation: "Short sale proceeds of $5,000 plus the Reg T deposit of 50% ($2,500) form a credit balance of $7,500, and that figure stays fixed. Equity is then credit less the current market value of the stock owed — the mirror image of the long account, where equity is market value less a fixed debit." },
  { id: "sie-trd-165", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "For that short position, a maintenance call is triggered when the stock rises to approximately:",
    choices: ["$50.00", "$57.69", "$65.00", "$43.50"],
    answerIndex: 1,
    explanation: "Short maintenance is 30% of market value, so the trigger is credit ÷ 1.30 = $7,500 ÷ 1.30 = $5,769, or $57.69 per share. Note the direction: for a short, the DANGER is the price going up, the opposite of everything in the long account. The 30% requirement exceeds the long side's 25% because short losses are unbounded." },
  { id: "sie-trd-166", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Excess equity in a long margin account is credited to:",
    choices: ["The debit balance, reducing it automatically", "A segregated cash account", "SMA, a line of credit the customer may draw on", "The firm's own capital"],
    answerIndex: 2,
    explanation: "Appreciation above the Reg T requirement creates excess equity, credited to the special memorandum account. SMA can be borrowed against or used to buy more securities with roughly twice its value in buying power. It does not decrease when the market falls, though using it still requires staying above maintenance." },
  { id: "sie-trd-167", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE about a stop order versus a stop-limit order?",
    choices: ["Both become market orders when triggered", "A stop guarantees the trigger price", "A stop-limit always executes", "A stop becomes a market order; a stop-limit becomes a limit order"],
    answerIndex: 3,
    explanation: "That single difference drives everything. A plain stop guarantees a sale but not a price, which is why it can fill far below the stop after a gap. A stop-limit protects the price but may never execute — reintroducing exactly the exposure the stop was meant to remove." },
  { id: "sie-trd-168", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A representative places a customer in Class C fund shares for a $200,000 investment intended to be held 20 years. This most likely violates:",
    choices: ["Regulation Best Interest, by ignoring cost and available alternatives", "Nothing, since Class C has no front-end load", "The AML rules on large transactions", "The prohibition on discretionary trading"],
    answerIndex: 0,
    explanation: "Class C carries permanently higher annual expenses and receives no breakpoints. On a large, long-horizon investment, Class A with a breakpoint is dramatically cheaper — so choosing C serves the representative's ongoing compensation rather than the client. Reg BI's care obligation requires weighing cost and reasonably available alternatives among suitable options." },
  { id: "sie-trd-169", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer's investment objective is capital preservation and they may need funds within a year. The least suitable recommendation is:",
    choices: ["A money market fund", "A direct participation program", "A short-term Treasury bill", "A bank certificate of deposit"],
    answerIndex: 1,
    explanation: "A DPP is illiquid for years with no meaningful secondary market and carries substantial risk to principal — it fails on both stated constraints simultaneously. The other three are all short, high-quality and liquid, which is exactly what preservation with a near-term need requires." },
  { id: "sie-trd-170", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which action by a registered representative is permitted?",
    choices: ["Guaranteeing the customer against loss", "Sharing in the account's profits without a written agreement", "Recommending a suitable product after gathering the customer profile", "Exercising discretion based on a verbal instruction to pick a stock"],
    answerIndex: 2,
    explanation: "Gathering the profile then recommending suitably is the job. Guaranteeing against loss is prohibited outright; profit sharing requires a written agreement and proportionality to capital contributed; and choosing the SECURITY always requires written discretionary authority." },
  { id: "sie-trd-171", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer emails a written complaint alleging unauthorized trading. The firm must:",
    choices: ["Resolve it within 24 hours or escalate to the SEC", "Refer the customer directly to arbitration", "Take no action unless the customer files formally", "Record it, retain it, and report it to FINRA quarterly"],
    answerIndex: 3,
    explanation: "Any written grievance concerning the firm's securities business is a complaint requiring a record, retention, and quarterly reporting to FINRA. That record-keeping is what makes patterns visible across representatives and over time. Arbitration is available but is the customer's choice, not a required first step." },
  { id: "sie-prd-263", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A fund's NAV is $9.30 and its maximum sales charge is 5%. The public offering price is:",
    choices: ["$9.79", "$9.77", "$8.84", "$9.30"],
    answerIndex: 0,
    explanation: "POP = NAV ÷ (1 − load) = $9.30 ÷ 0.95 = $9.79. The charge is a percentage OF THE POP, not of the NAV, so you divide rather than multiply. Multiplying $9.30 by 1.05 gives $9.77 — close enough to look right, and wrong for exactly the reason the question exists." },
  { id: "sie-prd-264", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A bond with a 5% coupon and $1,000 par trades at $950. Its current yield is:",
    choices: ["5.00%", "5.26%", "4.75%", "5.50%"],
    answerIndex: 1,
    explanation: "Current yield = annual coupon ÷ market price = $50 ÷ $950 = 5.26%. Because the bond trades at a DISCOUNT the current yield exceeds the 5% nominal, and yield to maturity exceeds both, since the holder also gains as the price pulls to par." },
  { id: "sie-prd-265", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor in the 35% bracket compares a 4% municipal with taxable bonds. The taxable yield needed to match is:",
    choices: ["5.40%", "4.00%", "6.15%", "2.60%"],
    answerIndex: 2,
    explanation: "Taxable-equivalent yield = muni yield ÷ (1 − rate) = 4.0% ÷ 0.65 = 6.15%. Multiplying instead gives 2.60%, which is the AFTER-TAX yield of a 4% taxable bond — the reverse computation. In a lower bracket the required yield falls, which is why muni suitability is entirely a function of the client's rate." },
  { id: "sie-prd-266", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor buys an XYZ 60 call for a premium of 4. Breakeven at expiration is:",
    choices: ["$56", "$60", "$4", "$64"],
    answerIndex: 3,
    explanation: "A long call breaks even when the stock exceeds the strike by the premium: 60 + 4 = $64. Subtracting instead gives $56, which is the breakeven for a long PUT — the direction the 'call up, put down' mnemonic exists to fix." },
  { id: "sie-prd-267", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor buys stock at $48 and writes a 50 call for 3. Maximum gain and breakeven are:",
    choices: ["$500 and $45", "$300 and $48", "$200 and $50", "Unlimited and $45"],
    answerIndex: 0,
    explanation: "Maximum gain occurs at or above the strike where the stock is called away: ($50 − $48) + $3 = $5 per share, or $500. Breakeven is cost less premium received: $48 − $3 = $45. The gain is capped — writing the call surrendered everything above $50 in exchange for $3 of downside cushion." },
  { id: "sie-prd-268", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A $1,000 par convertible bond has a conversion price of $25. It converts into:",
    choices: ["25 shares", "40 shares", "250 shares", "4 shares"],
    answerIndex: 1,
    explanation: "Conversion ratio = par ÷ conversion price = $1,000 ÷ $25 = 40 shares. If the stock trades at $30, parity is 40 × $30 = $1,200, meaning the bond is worth at least that on conversion grounds alone. Confusing price with ratio produces the distractors." },
  { id: "sie-prd-269", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A customer holds a $500,000 negotiable CD at a single bank. The uninsured amount is:",
    choices: ["$500,000", "Nothing", "$250,000", "$100,000"],
    answerIndex: 2,
    explanation: "FDIC covers $250,000 per depositor per insured bank, leaving $250,000 exposed to that bank's credit. That uninsured portion is exactly why jumbo CDs yield more than small insured ones — the holder is being paid to take real bank risk." },
  { id: "sie-prd-270", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor wants income, cannot tolerate principal loss, and needs access within six months. The best fit is:",
    choices: ["A 20-year Treasury bond", "A high-yield corporate bond fund", "A variable annuity", "A Treasury bill"],
    answerIndex: 3,
    explanation: "The T-bill satisfies all three constraints: government-backed, matures inside the window, and highly liquid. A 20-year Treasury has no credit risk but substantial interest rate risk if sold early. High-yield carries real default risk, and a variable annuity is illiquid with surrender charges and market exposure." },
  { id: "sie-prd-271", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which best explains why a long-maturity bond falls more than a short one when rates rise?",
    choices: ["More of its value sits further in the future", "Its credit quality deteriorates with time", "Its coupon is automatically reduced", "It has a higher default probability"],
    answerIndex: 0,
    explanation: "Price is the present value of future cash flows, and the further out those flows sit, the more a change in the discount rate moves them. Lower coupons amplify this for the same reason — more of the value is in the final principal payment. Credit quality and coupon do not change because rates moved." },
  { id: "sie-prd-272", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor holds a 20-year bond and expects rates to fall sharply. The greatest risk to their expected outcome is:",
    choices: ["Default by the issuer", "The bond being called, forcing reinvestment at lower rates", "Inflation eroding the coupon", "Illiquidity in the secondary market"],
    answerIndex: 1,
    explanation: "Falling rates are exactly when issuers call, refinancing cheaply and handing back principal at the worst possible moment for reinvestment. That is why call risk and reinvestment risk are two faces of one event, and why call protection matters most to an investor positioned for a rate decline." },
  { id: "sie-mkt-119", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Liquidity in a market refers to the ability to:",
    choices: ["Borrow against a position on margin", "Receive dividends on schedule", "Convert a holding to cash quickly at a predictable price", "Defer taxes on a gain"],
    answerIndex: 2,
    explanation: "Liquidity is about exit: converting to cash fast without moving the price against you. Along with price discovery it is one of the two properties a market exists to produce, and most market-structure regulation is ultimately defending one of the two." },
  { id: "sie-mkt-120", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Price discovery is the process by which:",
    choices: ["The SEC sets a fair value for each security", "Issuers announce the price they will accept", "Market makers agree on a common quote", "Many buyers and sellers acting on their own information produce a price"],
    answerIndex: 3,
    explanation: "Price discovery is emergent — no one sets the price, it results from many participants acting on their own information. The SEC never sets prices, an issuer's asking price is only an offer, and market makers agreeing on a quote would be collusion, not discovery." },
  { id: "sie-mkt-121", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "A corporation raises capital by selling newly issued bonds to investors. This occurs in the:",
    choices: ["Primary market", "Secondary market", "Third market", "Fourth market"],
    answerIndex: 0,
    explanation: "The bonds are newly created and the corporation receives the proceeds, which makes it primary regardless of who buys or how. Third and fourth markets describe secondary trading venues, so neither can apply to a security being sold for the first time." },
  { id: "sie-mkt-122", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which participant takes ownership risk by holding securities in inventory?",
    choices: ["A broker", "A dealer", "An investment adviser", "A transfer agent"],
    answerIndex: 1,
    explanation: "A dealer trades as PRINCIPAL from its own inventory, so it bears the risk that the position moves against it before resale — that risk is what the markup compensates. A broker is an agent and never owns the security. Advisers and transfer agents hold nothing." },
  { id: "sie-mkt-123", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "A custodian's role is to:",
    choices: ["Recommend securities to buy", "Make a market in a security", "Hold client assets for safekeeping", "Underwrite new issues"],
    answerIndex: 2,
    explanation: "Custody is safekeeping — holding assets so they are secure and properly recorded. Recommending is advisory work, quoting two-sided markets is what a market maker does, and buying an issue for resale is underwriting. Each is a distinct role the exam expects you to separate." },
  { id: "sie-mkt-124", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Two securities firms settle their day's obligations net rather than trade by trade. This is the work of:",
    choices: ["The transfer agent", "The registrar", "The custodian", "The clearing corporation"],
    answerIndex: 3,
    explanation: "The NSCC nets obligations so firms move only the net difference, dramatically reducing the cash and securities that must change hands. The transfer agent and registrar maintain and audit ownership records; a custodian safeguards assets." },
  { id: "sie-mkt-125", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 3,
    stem: "Why does shortening the settlement cycle from T+2 to T+1 reduce systemic risk?",
    choices: ["It shortens the window in which a counterparty can fail before value is exchanged", "It eliminates the need for a clearing corporation", "It removes market risk from the transaction entirely", "It guarantees every trade will settle"],
    answerIndex: 0,
    explanation: "Between trade and settlement each side is exposed to the other failing, and to the market moving. Halving that window halves the exposure — which is exactly why regulators pushed for T+1 after episodes of extreme volatility strained the system. Clearing is still required, and no cycle length guarantees settlement." },
  { id: "sie-mkt-126", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "The Securities Investor Protection Corporation is:",
    choices: ["A division of the SEC", "A nonprofit membership corporation, not a government agency", "A federal insurance agency like the FDIC", "A self-regulatory organisation with rulemaking power"],
    answerIndex: 1,
    explanation: "SIPC is a nonprofit membership corporation created by the Securities Investor Protection Act of 1970. It is neither a government agency nor an SRO — it writes no conduct rules and disciplines no one. Its single function is restoring customer assets when a member broker-dealer fails." },
  { id: "sie-mkt-127", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "An issuer's cost of capital is LOWERED by a liquid secondary market because:",
    choices: ["The issuer earns fees on secondary trades", "Regulators reduce registration costs", "Investors accept a lower return when they know they can exit", "Underwriters charge a smaller spread"],
    answerIndex: 2,
    explanation: "Liquidity reduces the risk of being trapped in a position, and investors price that: they demand less yield when exit is easy. That directly lowers what the issuer must pay at issuance. The issuer collects nothing from secondary trading itself — the benefit is entirely in the pricing of the primary offering." },
  { id: "sie-mkt-128", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Which is a self-regulatory organisation?",
    choices: ["The SEC", "The Federal Reserve", "The Treasury Department", "FINRA"],
    answerIndex: 3,
    explanation: "FINRA is an SRO — industry-funded, writing and enforcing conduct rules subject to SEC oversight. The SEC is the federal regulator above it. The Federal Reserve conducts monetary policy and sets Reg T margin requirements; Treasury issues government debt." },
  { id: "sie-mkt-129", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 3,
    stem: "An institutional investor executes a large block directly with another institution to avoid moving the public market. This describes:",
    choices: ["Fourth market trading", "Third market trading", "A primary offering", "A registered secondary"],
    answerIndex: 0,
    explanation: "Fourth market trading is institution to institution, bypassing exchanges entirely — which is precisely how a large holder avoids signalling its intentions and moving the price against itself. The third market is listed stock traded OTC, and both sit within the secondary market." },
  { id: "sie-prd-273", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor wants exposure to a broad index with the lowest ongoing cost. The best fit is:",
    choices: ["An actively managed equity fund", "An index ETF", "A closed-end fund at a premium", "A variable annuity subaccount"],
    answerIndex: 1,
    explanation: "Index ETFs carry the lowest expense ratios because there is no research team to fund and turnover is minimal. Active management costs more and must beat the benchmark net of that cost. A closed-end fund at a premium means paying more than the assets are worth, and variable annuity subaccounts add insurance charges on top of fund fees." },
  { id: "sie-prd-274", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "A client holds a bond portfolio and expects rates to RISE. To reduce price sensitivity they should:",
    choices: ["Lengthen maturities and favour lower coupons", "Buy zero-coupon bonds", "Shorten maturities and favour higher coupons", "Extend into 30-year issues"],
    answerIndex: 2,
    explanation: "Price sensitivity grows with maturity and shrinks with coupon size, because a bigger coupon returns more value sooner. Shortening and raising coupons reduces exposure to a rate rise. Zeros and long maturities do the opposite — they are the most rate-sensitive instruments there are." },
  { id: "sie-prd-275", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A UIT differs from a closed-end fund because a UIT:",
    choices: ["Trades on an exchange at a premium or discount", "Is actively managed by an adviser", "Issues new shares continuously", "Has a fixed portfolio and a set termination date"],
    answerIndex: 3,
    explanation: "A UIT buys a portfolio, holds it unchanged, and terminates on a preset date — no board, no adviser, no ongoing decisions. Closed-end funds are actively managed and exchange-traded. Continuous issuance describes an open-end fund." },
  { id: "sie-prd-276", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which describes the tax treatment of a non-qualified annuity withdrawal?",
    choices: ["Earnings come out first and are taxed as ordinary income", "Principal comes out first, tax-free", "The entire withdrawal is tax-free", "Withdrawals are taxed at capital gains rates"],
    answerIndex: 0,
    explanation: "Non-qualified annuity withdrawals are LIFO — earnings first, taxed as ordinary income, plus a 10% penalty before 59½. Contributions were already after-tax so they return untaxed, but only after the earnings are exhausted. Annuity gains never receive capital gains treatment." },
  { id: "sie-prd-277", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor buys a 45 put for $2 while holding stock purchased at $48. Their maximum loss is:",
    choices: ["$300", "$500", "$200", "Unlimited"],
    answerIndex: 1,
    explanation: "The put guarantees a sale at $45 however far the stock falls, so the loss on the stock caps at $48 − $45 = $3 per share. Adding the $2 premium gives $5 per share, or $500 per 100 shares. Breakeven is $50 — the stock must recover the insurance cost before the position profits." },
  { id: "sie-prd-278", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is TRUE of a naked call writer?",
    choices: ["Maximum gain is unlimited; maximum loss is the premium", "Both gain and loss are capped by the strike", "Maximum gain is the premium; maximum loss is unlimited", "The position profits when the stock rises"],
    answerIndex: 2,
    explanation: "The writer collects the premium and that is the entire upside. Because a stock has no ceiling, the obligation to deliver it is unbounded — the only genuinely unlimited loss on the exam. It profits when the stock stays flat or falls, not when it rises." },
  { id: "sie-prd-279", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A GNMA pass-through returns principal to the holder earlier than expected. The most likely cause is:",
    choices: ["Rising rates slowing prepayments", "An issuer default", "A call provision exercised by GNMA", "Falling rates prompting homeowners to refinance"],
    answerIndex: 3,
    explanation: "Homeowners refinance when rates fall, and that principal flows straight through to the certificate holder — at the worst possible moment for reinvestment. Rising rates cause the opposite, extension risk. GNMA carries an explicit government guarantee so default is not the explanation, and these are not callable in the corporate sense." },
  { id: "sie-prd-280", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which risk does a diversified portfolio of 40 domestic stocks still fully carry?",
    choices: ["Market risk", "Business risk", "Credit risk", "Liquidity risk"],
    answerIndex: 0,
    explanation: "Market risk is systematic and survives any amount of diversification within an asset class — a broad decline takes all 40 names with it. Business, credit and liquidity risk are company-specific and largely offset across that many holdings, which is why the market pays nothing extra for carrying them." },
  { id: "sie-reg-119", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "A firm distributes a piece to 20 retail investors over 30 days. This is:",
    choices: ["A retail communication requiring prior principal approval", "Correspondence, reviewed under firm procedures", "An institutional communication", "Exempt from any review"],
    answerIndex: 1,
    explanation: "Twenty-five or fewer retail investors within 30 calendar days makes it CORRESPONDENCE, reviewed per the firm's procedures without pre-approval. Cross 25 and it becomes a RETAIL communication needing principal approval before first use. Nothing in the scheme escapes review entirely." },
  { id: "sie-reg-120", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which claim in an advertisement would violate FINRA rules?",
    choices: ["Past performance with a disclosure that it does not guarantee future results", "A description of the fund's investment objective", "A prediction that the fund will return 8% next year", "The fund's expense ratio"],
    answerIndex: 2,
    explanation: "Predicting future performance is prohibited outright — no disclosure cures it. Past performance may be shown with the standard disclaimer, and objectives and costs are exactly the factual material an investor needs. The standard is whether the piece is fair, balanced and not misleading." },
  { id: "sie-reg-121", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 3,
    stem: "An individual is convicted of a securities-related misdemeanour four years ago. Regarding association with a member firm they are:",
    choices: ["Free to associate with no restriction", "Barred permanently from the industry", "Required only to disclose it on Form U4", "Statutorily disqualified"],
    answerIndex: 3,
    explanation: "A securities-related misdemeanour within the past ten years triggers statutory disqualification, as does any felony in that window, an SEC or SRO bar, or a false statement on a registration application. Disqualification is not automatically permanent — a firm may seek eligibility relief — but it is far more than a disclosure item." },
  { id: "sie-trd-172", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A GTC order remains in effect until:",
    choices: ["It executes or the customer cancels it", "The end of the trading day", "The end of the calendar quarter", "The next dividend payment"],
    answerIndex: 0,
    explanation: "Good til cancelled carries over day to day indefinitely, though firms typically require periodic reconfirmation. A DAY order is the one that dies at the close, and it is the default when no duration is specified." },
  { id: "sie-trd-173", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A buy LIMIT order is placed below the current market. It will execute:",
    choices: ["Immediately at the current market price", "Only if the price falls to the limit or lower", "Only if the price rises to the limit", "At the close regardless of price"],
    answerIndex: 1,
    explanation: "A buy limit sets a ceiling — the customer will pay that price or better, and better means lower. Placed below the market it simply waits for the price to come down. If the market never reaches it, the order never fills, which is the trade-off for controlling price." },
  { id: "sie-trd-174", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A sell STOP order is placed below the current market in order to:",
    choices: ["Guarantee a minimum sale price", "Enter a new long position cheaply", "Limit a loss on a long position", "Collect a dividend before the ex-date"],
    answerIndex: 2,
    explanation: "A sell stop protects a long position by triggering a sale if the price falls to the stop. It guarantees that a sale occurs, NOT the price — once triggered it becomes a market order, so a gap can fill it far below the stop." },
  { id: "sie-trd-175", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer wants to protect a long position but refuses to sell below $52. The correct order is:",
    choices: ["A sell stop at $52", "A sell limit at $52", "A market order", "A sell stop-limit at $52"],
    answerIndex: 3,
    explanation: "A stop-limit becomes a LIMIT order when triggered, so it will not execute below $52 — which is exactly the customer's constraint. A plain stop becomes a market order and can fill far lower. The trade-off is real: if the price gaps through $52 the stop-limit may never execute and the position keeps falling." },
  { id: "sie-trd-176", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is the correct sequence of dividend dates?",
    choices: ["Declaration, ex-dividend, record, payable", "Record, declaration, ex-dividend, payable", "Declaration, record, ex-dividend, payable", "Ex-dividend, declaration, record, payable"],
    answerIndex: 0,
    explanation: "The board DECLARES, the stock goes EX (first day trading without the dividend), the issuer checks its books on the RECORD date, and cash arrives on the PAYABLE date weeks later. Under T+1 settlement the ex-date and record date now coincide, which is a change from older material." },
  { id: "sie-trd-177", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "An IRA may NOT invest in:",
    choices: ["Common stock", "Collectibles such as art and antiques", "Mutual funds", "Corporate bonds"],
    answerIndex: 1,
    explanation: "Collectibles — art, antiques, most precious metals, rugs, gems — are prohibited IRA investments, as is life insurance. Ordinary securities are all permissible. The restriction exists because the account is meant for retirement saving, not for holding assets whose value is hard to verify." },
  { id: "sie-trd-178", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A SEP IRA differs from a traditional IRA because a SEP is:",
    choices: ["Available only to government employees", "Exempt from required minimum distributions", "Funded by employer contributions", "Funded exclusively with after-tax dollars"],
    answerIndex: 2,
    explanation: "A SEP is a simplified employer plan funded by EMPLOYER contributions, which is why small businesses use it — low administrative cost with higher limits than a personal IRA. It is still a traditional-style tax-deferred account, so RMDs apply and contributions are pre-tax." },
  { id: "sie-trd-179", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is a prohibited practice?",
    choices: ["Recommending a suitable mutual fund", "Explaining the risks of an investment", "Disclosing a conflict of interest", "Guaranteeing a customer against loss"],
    answerIndex: 3,
    explanation: "Guaranteeing against loss is prohibited outright — no disclosure or documentation cures it, because it misrepresents the fundamental nature of investing. The other three are exactly what a representative is supposed to do." },
  { id: "sie-trd-180", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Sharing in a customer's account profits and losses is permitted only if:",
    choices: ["There is a written agreement and sharing is proportional to capital contributed", "The customer verbally consents", "The representative discloses it to FINRA", "The account is discretionary"],
    answerIndex: 0,
    explanation: "Both conditions must hold: written firm approval and proportionality to the representative's own capital contribution. A narrow exception exists for immediate family. Verbal consent, disclosure alone, or discretionary status do not authorise profit sharing." },
  { id: "sie-trd-181", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which requires a principal's approval BEFORE the transaction?",
    choices: ["Every unsolicited order", "Opening a new customer account", "Sending a customer statement", "Delivering a prospectus"],
    answerIndex: 1,
    explanation: "Every new account requires principal approval, and an options account additionally requires a registered options principal. Orders are reviewed but generally not pre-approved individually, and statements and prospectuses are routine deliveries." },
  { id: "sie-trd-182", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A representative learns from a friend at a law firm that a merger will be announced tomorrow, and buys the stock. This is:",
    choices: ["Permissible, since the representative is not a company insider", "Permissible if the trade is under $10,000", "Insider trading, and the friend may also be liable", "Only a violation if the merger actually closes"],
    answerIndex: 2,
    explanation: "Liability extends to anyone who receives material nonpublic information and trades on it, and the tipper can be liable too. Not being a corporate insider is no defence, there is no dollar threshold, and the violation is complete at the trade — whether the merger closes is irrelevant." },
  { id: "sie-trd-183", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Penalties under the Insider Trading and Securities Fraud Enforcement Act of 1988 can reach:",
    choices: ["The exact amount of the profit", "Ten percent of the trade value", "A fixed $10,000 per violation", "Three times the profit gained or loss avoided"],
    answerIndex: 3,
    explanation: "Civil penalties reach three times the profit gained or loss avoided, and they apply to controlling persons — the firm — as well as the individual. Criminal penalties are separate and additional. The treble structure exists to make the expected value of the trade negative." },
  { id: "sie-trd-184", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer wants to transfer their account to another firm. The transfer is processed through:",
    choices: ["ACATS", "The DTC directly", "FINRA arbitration", "The transfer agent"],
    answerIndex: 0,
    explanation: "The Automated Customer Account Transfer Service moves accounts between firms on a standard timetable. DTC holds securities in book-entry form but does not run customer account transfers, and the transfer agent maintains the issuer's ownership records." },
  { id: "sie-trd-185", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which statement about a numbered or nominee account is correct?",
    choices: ["The owner's identity may remain unknown to the firm", "The firm must have written attestation of the true owner's identity", "Such accounts are prohibited entirely", "Only institutional customers may open them"],
    answerIndex: 1,
    explanation: "The account may be identified by a number for privacy on statements, but the firm must hold a written statement attesting to ownership. An account whose beneficial owner the firm does not know would defeat the customer identification program outright." },
  { id: "sie-trd-186", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A registered representative accepts a $150 gift from a mutual fund wholesaler for directing business. This is:",
    choices: ["Permitted, since gifts are unregulated", "Permitted if reported to FINRA", "A violation, exceeding the $100 annual limit", "Permitted if the representative discloses it to customers"],
    answerIndex: 2,
    explanation: "The limit is $100 per person per year in connection with business, deliberately low enough to prevent influence rather than to price it. Reporting or disclosing does not raise the cap. Ordinary business entertainment where both parties attend is treated separately." },
  { id: "sie-trd-187", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Under FINRA rules, mediation differs from arbitration because mediation is:",
    choices: ["Binding with no appeal", "Decided by a three-person panel", "Required before arbitration", "Voluntary and non-binding"],
    answerIndex: 3,
    explanation: "Mediation is voluntary and non-binding, and either party may walk away at any point. ARBITRATION is binding with essentially no right of appeal — that contrast is the tested distinction. Mediation is available but never a mandatory first step." },
  { id: "sie-trd-188", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Trade confirmations must be sent:",
    choices: ["At or before completion of the transaction", "Within 30 days of the trade", "Quarterly with the account statement", "Only on customer request"],
    answerIndex: 0,
    explanation: "The confirmation is due at or before completion of the transaction and must disclose the firm's capacity — agent or principal — along with price and commission. Statements are the quarterly document; confirmations are per-trade." },
  { id: "sie-trd-189", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer's account shows 40 trades in a month with an objective of long-term growth and modest resources. The concern is:",
    choices: ["Nothing, if each trade was individually suitable", "Churning, judged against the customer's objectives and resources", "Front-running", "Structuring"],
    answerIndex: 1,
    explanation: "Churning is measured against the customer's stated objectives and means, not by any fixed trade count — the same activity could be fine for an active trader and abusive here. Crucially, each trade being individually suitable does not cure it; the pattern itself is the violation." },
  { id: "sie-trd-190", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "The Firm Element of continuing education is:",
    choices: ["A computer-based module written by FINRA", "Required only of principals", "Designed by the member firm from its own annual needs analysis", "Completed once at registration"],
    answerIndex: 2,
    explanation: "The firm conducts an annual needs analysis, writes a training plan, and delivers it to covered registered persons. The REGULATORY Element is the FINRA-written piece, completed annually by December 31 for each registration category held." },
  { id: "sie-trd-191", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer instructs a representative to 'buy 500 shares of ABC whenever you think the price is right today.' This is:",
    choices: ["Full discretion, requiring prior written authority", "Prohibited in all circumstances", "Acceptable only in a margin account", "Acceptable — discretion as to time and price only, good for that day"],
    answerIndex: 3,
    explanation: "The customer specified the security and the quantity, leaving only TIME and PRICE to the representative — the narrow exception that may be accepted verbally and expires that day. Had the customer left the security or amount open, written discretionary authority would be required first." },
  { id: "sie-prd-281", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A bond's nominal yield is another name for its:",
    choices: ["Coupon rate", "Current yield", "Yield to maturity", "Yield to call"],
    answerIndex: 0,
    explanation: "Nominal yield is the coupon rate, fixed at issuance and printed on the bond. Current yield divides the coupon by the market PRICE, and yield to maturity adds the gain or loss as the price pulls to par. Only the nominal never changes." },
  { id: "sie-prd-282", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which bond has the greatest price sensitivity to a change in interest rates?",
    choices: ["A 2-year 8% bond", "A 30-year zero-coupon bond", "A 5-year 6% bond", "A 1-year Treasury bill"],
    answerIndex: 1,
    explanation: "Sensitivity rises with maturity and falls with coupon size, so the longest maturity paired with no coupon at all is the most sensitive instrument there is. A zero returns everything at the end, so its entire value is discounted across the full 30 years." },
  { id: "sie-prd-283", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which entity guarantees the payment of principal and interest on a Treasury bond?",
    choices: ["The Federal Reserve", "SIPC", "The U.S. government", "The issuing underwriter"],
    answerIndex: 2,
    explanation: "Treasury obligations carry the full faith and credit of the United States, which is why they are treated as free of credit risk. The Fed conducts monetary policy and does not guarantee Treasuries; SIPC protects brokerage customers against firm failure, not issuer default." },
  { id: "sie-prd-284", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Interest on U.S. Treasury securities is:",
    choices: ["Exempt from all taxation", "Taxable at every level", "Exempt federally, taxable at the state level", "Taxable federally, exempt from state and local tax"],
    answerIndex: 3,
    explanation: "Treasury interest is federally taxable but exempt from state and local tax. Municipal interest runs the OPPOSITE way — federally exempt and usually exempt in the issuer's own state. Keeping the two directions straight is a reliable exam point." },
  { id: "sie-prd-285", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A STRIPS security is best suited to an investor who:",
    choices: ["Needs a known lump sum on a specific future date", "Requires regular current income", "Wants protection against inflation", "Seeks to minimise annual tax"],
    answerIndex: 0,
    explanation: "STRIPS are zero-coupon Treasuries: bought at a discount, maturing at a known face value, with no coupons to reinvest. That makes them ideal for a dated funding need. They provide NO current income, and holders owe annual tax on phantom accreted interest, so they suit tax-deferred accounts." },
  { id: "sie-prd-286", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor seeking protection from rising consumer prices should consider:",
    choices: ["Long-term fixed-rate corporate bonds", "TIPS", "Zero-coupon bonds", "Fixed annuities"],
    answerIndex: 1,
    explanation: "TIPS adjust principal with the CPI, so both coupon payments and final principal rise with inflation. The other three all deliver fixed nominal amounts, which is exactly what inflation erodes — long fixed-rate bonds and zeros are the most exposed of all." },
  { id: "sie-prd-287", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which describes a revenue bond's security?",
    choices: ["The issuer's full taxing power", "A federal guarantee", "The receipts of the financed facility only", "A pledge of the state's general fund"],
    answerIndex: 2,
    explanation: "A revenue bond is repaid solely from the project's receipts, which is why analysis centres on the feasibility study and debt service coverage. If revenues disappoint, holders have NO recourse to the issuer's taxing power — that backing belongs to general obligation bonds." },
  { id: "sie-prd-288", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Municipal bonds are exempt from:",
    choices: ["All state regulation", "FINRA conduct rules for dealers", "Antifraud provisions", "Securities Act of 1933 registration"],
    answerIndex: 3,
    explanation: "Municipal and U.S. government securities are exempt SECURITIES under the 1933 Act, so no registration statement is filed — the disclosure document is an official statement instead. Dealers remain subject to MSRB rules enforced by FINRA, and antifraud provisions apply to everything." },
  { id: "sie-prd-289", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A private activity municipal bond may create a tax issue because its interest:",
    choices: ["May be subject to the alternative minimum tax", "Is fully taxable at ordinary rates", "Is taxed as a capital gain", "Loses its exemption after ten years"],
    answerIndex: 0,
    explanation: "Certain private activity bonds are AMT preference items, so a high-income holder may owe alternative minimum tax on interest that is otherwise federally exempt. The exemption does not expire, and municipal interest is never recharacterised as a capital gain — though GAINS on selling a muni are fully taxable." },
  { id: "sie-prd-290", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An open-end fund's redemption proceeds must be sent to the investor within:",
    choices: ["One day", "Seven days", "Thirty days", "Ninety days"],
    answerIndex: 1,
    explanation: "The Investment Company Act of 1940 requires redemption proceeds within seven days, which is part of what makes an open-end fund a liquid investment. The redemption price itself is the next computed NAV under forward pricing, less any contingent deferred sales charge." },
  { id: "sie-prd-291", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which investment company type does NOT continuously offer new shares?",
    choices: ["An open-end fund", "A money market fund", "A closed-end fund", "A no-load fund"],
    answerIndex: 2,
    explanation: "A closed-end fund raises capital once in a public offering, then its fixed share count trades among investors on an exchange. Open-end funds — including money market and no-load funds, which are just varieties of open-end — issue and redeem shares continuously at NAV." },
  { id: "sie-prd-292", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor holds a mutual fund with a 1% 12b-1 fee and a 0.6% management fee. Over a long holding period the 12b-1 fee:",
    choices: ["Is charged only once at purchase", "Applies only if shares are sold early", "Is refunded at redemption", "Compounds against the investor and can exceed a front-end load"],
    answerIndex: 3,
    explanation: "A 12b-1 fee is deducted annually from assets, so over a long horizon it compounds and can cost more than a one-time front-end load would have. That is precisely why Class C shares are the most expensive choice for a long holding period despite having no visible upfront charge." },
  { id: "sie-prd-293", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An ETF's market price stays close to its NAV because:",
    choices: ["Authorized participants create and redeem shares to arbitrage the gap", "The sponsor guarantees the price", "The SEC caps the permitted deviation", "Trading halts if it diverges"],
    answerIndex: 0,
    explanation: "The creation and redemption mechanism lets authorized participants profit from any meaningful gap, and their trading closes it. Closed-end funds lack that mechanism, which is why they can sit at persistent premiums or discounts. No regulator caps the deviation." },
  { id: "sie-prd-294", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A hedge fund typically differs from a mutual fund because the hedge fund:",
    choices: ["Must publish daily NAV", "Is illiquid and sold only to accredited investors", "Is registered under the Investment Company Act", "Has lower fees"],
    answerIndex: 1,
    explanation: "Hedge funds are sold through private placements to accredited investors, carry lock-ups, and are not registered investment companies — which is what permits leverage, short selling and concentrated positions. Fees are typically HIGHER, often a management fee plus a performance share." },
  { id: "sie-prd-295", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "The intrinsic value of a put with a $60 strike when the stock trades at $53 is:",
    choices: ["$0", "$53", "$7", "$60"],
    answerIndex: 2,
    explanation: "Put intrinsic value is strike minus stock: $60 − $53 = $7, and it is in-the-money. Intrinsic value is never negative — an out-of-the-money option simply has zero. Whether the position PROFITS depends on the premium paid, which intrinsic value ignores entirely." },
  { id: "sie-prd-296", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Time value of an option is greatest when:",
    choices: ["The option is deep in-the-money", "Expiration is one day away", "The stock has stopped moving", "There is substantial time remaining until expiration"],
    answerIndex: 3,
    explanation: "Time value pays for the chance that the position improves, so it is largest when there is the most time for that to happen and it erodes as expiration approaches — accelerating in the final weeks. That decay works against the buyer and for the writer." },
  { id: "sie-prd-297", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Equity options are AMERICAN style, which means they may be exercised:",
    choices: ["Any time before expiration", "Only at expiration", "Only on the third Friday", "Only after 30 days"],
    answerIndex: 0,
    explanation: "American-style options may be exercised at any point up to expiration, which is the standard for listed equity options. EUROPEAN style permits exercise only at expiration and is common for index options. The distinction matters because early assignment is a real risk for a writer." },
  { id: "sie-prd-298", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "A writer of a covered call is assigned. The result is that they:",
    choices: ["Must buy stock in the market at any price", "Deliver the stock they already own at the strike price", "Receive the stock at the strike price", "Pay the intrinsic value in cash"],
    answerIndex: 1,
    explanation: "Covered means the writer already holds the shares, so assignment simply delivers them at the strike — the position closes with the gain capped. A NAKED writer would have to buy in the market at whatever the price has become, which is the unlimited exposure covered writing avoids." },
  { id: "sie-prd-299", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which best describes reinvestment risk?",
    choices: ["The risk the issuer defaults", "The risk of not finding a buyer", "The risk of redeploying cash flows at lower rates", "The risk of currency movements"],
    answerIndex: 2,
    explanation: "Reinvestment risk arises whenever money comes back and must be put to work again at whatever rates then prevail. It is greatest for high-coupon and callable bonds, and essentially absent for a zero held to maturity, which returns nothing until the end." },
  { id: "sie-prd-300", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Political risk is classified as:",
    choices: ["Unsystematic, because it affects one issuer", "Not a real investment risk", "Only relevant to municipal bonds", "Systematic, because it affects entire markets"],
    answerIndex: 3,
    explanation: "Political risk — expropriation, capital controls, abrupt regulatory change — affects whole markets or countries at once and cannot be diversified away within them, which makes it systematic. Alongside market, interest rate, inflation and currency risk it is one of the risks investors are compensated for bearing." },
  { id: "sie-prd-301", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor holding foreign securities is exposed to currency risk, meaning:",
    choices: ["Returns fall if the foreign currency weakens against the dollar", "The foreign issuer may default", "The securities cannot be sold quickly", "Foreign dividends are always taxed twice"],
    answerIndex: 0,
    explanation: "Even a foreign holding that rises in local terms can lose value once converted back if that currency has weakened. This exposure survives an ADR structure, which removes the settlement mechanics but not the underlying currency denomination. Default is credit risk; illiquidity is a separate concern." },
  { id: "sie-prd-302", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "A client aged 68 seeks maximum current income and can accept moderate risk. The least appropriate recommendation is:",
    choices: ["An investment-grade corporate bond fund", "A zero-coupon bond maturing in 20 years", "A preferred stock portfolio", "A diversified REIT"],
    answerIndex: 1,
    explanation: "A zero pays nothing until maturity, so it fails the stated need for CURRENT income outright, and a 20-year horizon is a poor fit at 68. The other three all generate regular distributions at risk levels consistent with a moderate tolerance." },
  { id: "sie-prd-303", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A debenture is backed by:",
    choices: ["Specific real property", "Rolling stock", "The issuer's general credit", "Securities held in trust"],
    answerIndex: 2,
    explanation: "A debenture pledges nothing specific and rests entirely on the issuer's creditworthiness. Mortgage bonds pledge real property, equipment trust certificates pledge rolling stock, and collateral trust bonds pledge securities the issuer owns." },
  { id: "sie-prd-304", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An income bond (adjustment bond) pays interest:",
    choices: ["On a fixed semiannual schedule", "At maturity in a lump sum", "Monthly regardless of earnings", "Only if the issuer earns sufficient income"],
    answerIndex: 3,
    explanation: "Because payment is contingent on earnings rather than promised, an income bond trades FLAT — without accrued interest — like a bond in default. It typically arises from a reorganisation, which is why it appears alongside distressed situations." },
  { id: "sie-prd-305", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which security trades FLAT, without accrued interest?",
    choices: ["A zero-coupon bond", "A corporate debenture", "A Treasury note", "A municipal revenue bond"],
    answerIndex: 0,
    explanation: "Zeros pay no periodic interest, so there is nothing to accrue between dates. Bonds in default and income bonds also trade flat. Every coupon-paying bond in good standing trades 'and interest', with the buyer compensating the seller for interest earned since the last payment." },
  { id: "sie-prd-306", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Preferred stock's price behaves most like:",
    choices: ["A short-term T-bill", "A long-term bond", "A growth stock", "A commodity"],
    answerIndex: 1,
    explanation: "The fixed dividend makes preferred sensitive to interest rates the way a long bond is — rates up, price down. Its dominant risk is therefore interest rate risk rather than business risk, which surprises investors who file it mentally under 'stock'." },
  { id: "sie-prd-307", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor wants voting control of a company. They should buy:",
    choices: ["Preferred stock", "Corporate bonds", "Common stock", "Warrants"],
    answerIndex: 2,
    explanation: "Only common stock carries the vote. Preferred normally has none, bondholders are creditors with no ownership rights, and a warrant is merely a right to purchase shares later — it confers nothing until exercised." },
  { id: "sie-prd-308", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "A company declares a 5% stock dividend. An investor holding 200 shares with a $50 cost basis will hold:",
    choices: ["200 shares at the same basis", "210 shares at the same basis", "190 shares at a higher basis", "210 shares at a reduced basis per share"],
    answerIndex: 3,
    explanation: "A 5% stock dividend adds 10 shares to 200. Total cost basis is unchanged, so basis PER SHARE falls to spread across 210. Nothing is received in cash, so there is no taxable event — the tax arrives later, when the shares are sold at the adjusted basis." },
  { id: "sie-trd-192", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is required before a customer may trade options?",
    choices: ["Approval by a registered options principal", "Approval by the SEC", "A minimum $25,000 balance", "A margin agreement in all cases"],
    answerIndex: 0,
    explanation: "An ROP must approve the account, and the options disclosure document must be delivered at or before approval. The signed options agreement follows within 15 days. There is no regulatory minimum balance, and buying options can be done in a cash account with full payment." },
  { id: "sie-trd-193", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "If a customer does not return the signed options agreement within 15 days, the account may:",
    choices: ["Continue trading normally", "Only close existing positions", "Be liquidated immediately", "Open new positions with principal approval"],
    answerIndex: 1,
    explanation: "The account goes closing-only until the agreement arrives — it is not frozen or liquidated, but no new positions may be opened. The 15-day clock runs from account approval, and it is one of the few hard deadlines in the account-opening process." },
  { id: "sie-trd-194", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "The Federal Reserve sets which margin requirement?",
    choices: ["The 25% long maintenance requirement", "The 30% short maintenance requirement", "The initial requirement under Regulation T", "The $2,000 minimum equity"],
    answerIndex: 2,
    explanation: "Reg T's 50% initial deposit is the Fed's. The 25% long and 30% short MAINTENANCE minimums are FINRA's, as is the $2,000 minimum to open. Firms may impose stricter house requirements on top of any of these." },
  { id: "sie-trd-195", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer buys $60,000 of stock in a margin account and deposits $30,000. Two months later the position is worth $50,000. Their equity is:",
    choices: ["$30,000", "$50,000", "$10,000", "$20,000"],
    answerIndex: 3,
    explanation: "The $30,000 deposit satisfied Reg T's 50%, so the firm lent $30,000 and that debit stays fixed. Equity is market value less debit: $50,000 − $30,000 = $20,000. FINRA's 25% maintenance on $50,000 is $12,500, so no call — the position has room before one is triggered." },
  { id: "sie-trd-196", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE about an unsolicited trade?",
    choices: ["It must be marked unsolicited on the order ticket", "It requires no record at all", "It cannot be executed if unsuitable", "It must be approved by FINRA"],
    answerIndex: 0,
    explanation: "The order ticket must be marked unsolicited, because that marking is what removes the trade from the suitability analysis. Mismarking a solicited trade to escape that analysis is a serious violation and a recurring exam fact pattern." },
  { id: "sie-mkt-130", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which pair correctly describes the two roles a broker-dealer can play?",
    choices: ["Agent earning a markup; principal earning a commission", "Agent earning a commission; principal earning a markup", "Both roles earn commissions", "Both roles earn the bid-ask spread"],
    answerIndex: 1,
    explanation: "As AGENT the firm matches buyer and seller and charges a commission; as PRINCIPAL it trades from inventory and earns the markup embedded in the price. The confirmation must disclose which capacity applied, because the conflict differs entirely between them." },
  { id: "sie-mkt-131", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "An underwriter that buys an entire issue from the issuer and resells it has entered a:",
    choices: ["Best efforts arrangement", "All-or-none arrangement", "Firm commitment", "Standby agreement"],
    answerIndex: 2,
    explanation: "Firm commitment means the underwriter acts as PRINCIPAL, taking the full risk of unsold shares while the issuer is paid regardless. Best efforts makes the underwriter an AGENT, returning what it cannot sell. That principal-versus-agent split is what every commitment question turns on." },
  { id: "sie-mkt-132", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "In a best efforts underwriting, the risk of an unsold issue falls on:",
    choices: ["The underwriter", "The selling group", "The clearing corporation", "The issuer"],
    answerIndex: 3,
    explanation: "In best efforts the underwriter is an agent, selling what it can and returning the rest — so the ISSUER bears the shortfall. Only a firm commitment transfers that risk to the underwriter. A selling group never takes underwriting risk at all." },
  { id: "sie-reg-122", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "A tombstone advertisement may include:",
    choices: ["The name of the issuer and the underwriters", "A recommendation to buy", "A projection of the return", "An endorsement by the SEC"],
    answerIndex: 0,
    explanation: "A tombstone is deliberately limited to factual identifying details — issuer, security, size, underwriters, and where to get a prospectus. It may not recommend, project, or imply SEC endorsement, since the SEC never approves a security." },
  { id: "sie-reg-123", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Who may sell a new issue during the cooling-off period?",
    choices: ["Only the lead underwriter", "Nobody — no sales may occur before the effective date", "Only to accredited investors", "Only institutional buyers"],
    answerIndex: 1,
    explanation: "No sales to anyone before effectiveness. Indications of interest may be gathered and a red herring circulated, but accepting orders or money is prohibited regardless of who the buyer is. Investor sophistication changes nothing about the timing rule." },
  { id: "sie-reg-124", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "The document delivered to a purchaser at or before confirmation of a new issue is the:",
    choices: ["Preliminary prospectus", "Official statement", "Final prospectus", "Registration statement"],
    answerIndex: 2,
    explanation: "The final prospectus, which includes the price set at pricing, must reach the buyer at or before confirmation. The preliminary prospectus (red herring) circulates earlier and has no final price. An official statement is the municipal equivalent, and the registration statement is filed with the SEC." },
  { id: "sie-reg-125", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which offering is exempt from registration because of HOW it is sold rather than what it is?",
    choices: ["A U.S. Treasury bond", "A municipal bond", "A bank-issued security", "A Regulation D private placement"],
    answerIndex: 3,
    explanation: "A private placement is an exempt TRANSACTION — the exemption comes from the manner of sale, principally to accredited investors without a public offering. Treasuries, municipals and bank securities are exempt SECURITIES, exempt because of what they inherently are." },
  { id: "sie-reg-126", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "An accredited investor may qualify by:",
    choices: ["Income, net worth excluding primary residence, or professional credentials", "Age and citizenship", "Having a brokerage account for five years", "Holding a college degree in finance"],
    answerIndex: 0,
    explanation: "The tests are income, net worth with the primary residence excluded, or certain professional certifications and licences. The exclusion of the home is deliberate — it prevents house-price appreciation alone from qualifying someone for unregistered offerings." },
  { id: "sie-reg-127", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 3,
    stem: "A firm's registered representative is also the spouse of a portfolio manager at a fund. Under Rule 5130, the representative:",
    choices: ["May buy freely with disclosure", "May not buy a new equity issue at the public offering price", "Is barred from the securities industry", "May buy only new DEBT issues at the offering price"],
    answerIndex: 1,
    explanation: "Restricted persons — member firms, their associated persons, and immediate family they materially support — may not purchase new EQUITY issues at the offering price, so that first-day gains go to public customers. Note the boundary the last option gets right in substance: new DEBT offerings are outside the rule." },
  { id: "sie-mkt-133", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Who receives the proceeds of a secondary market trade?",
    choices: ["The issuer", "The exchange", "The selling investor", "The underwriter"],
    answerIndex: 2,
    explanation: "In the secondary market one investor sells to another, so the money goes to the seller and the issuer receives nothing. Only a PRIMARY transaction sends proceeds to the issuer. Exchanges and underwriters take fees, not the sale proceeds." },
  { id: "sie-mkt-134", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "What does an exchange primarily provide?",
    choices: ["Investment advice", "Credit to investors", "Insurance on trades", "A centralised marketplace"],
    answerIndex: 3,
    explanation: "An exchange concentrates buyers and sellers in one venue, which produces liquidity and price discovery. It gives no advice, extends no credit — that is the broker-dealer's margin function — and insures nothing. SIPC covers firm failure separately." },
  { id: "sie-mkt-135", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which best describes an ATS or dark pool?",
    choices: ["A non-exchange venue matching orders", "A government bond auction", "A retail brokerage platform", "A clearing corporation"],
    answerIndex: 0,
    explanation: "Alternative trading systems match buyers and sellers away from a public exchange, and dark pools do so without displaying quotes — useful to institutions moving size without signalling. They are trading venues, not clearing or retail systems." },
  { id: "sie-mkt-136", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "An issuer's first sale of stock to the public is called:",
    choices: ["A secondary distribution", "An initial public offering", "A private placement", "A tender offer"],
    answerIndex: 1,
    explanation: "An IPO is the first public sale, and it is a primary transaction — the issuer receives the proceeds. A secondary distribution resells existing shares, a private placement avoids a public offering entirely, and a tender offer is a bid to buy shares from holders." },
  { id: "sie-mkt-137", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which risk does a market maker take?",
    choices: ["Credit risk on the issuer", "Currency risk", "Inventory price risk", "Prepayment risk"],
    answerIndex: 2,
    explanation: "A market maker holds securities in inventory to quote both sides, so it loses if the position moves against it before resale. That risk is what the bid-ask spread compensates. The other three attach to what is being held, not to the act of making a market." },
  { id: "sie-prd-309", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "What is the par value of most corporate bonds?",
    choices: ["$100", "$500", "$5,000", "$1,000"],
    answerIndex: 3,
    explanation: "Corporate bonds use $1,000 par and quotes are a percentage of it, so 98 means $980. Preferred stock conventionally uses $100 par, which is why a 6% preferred pays $6. Mixing the two conventions causes most arithmetic errors in this area." },
  { id: "sie-prd-310", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which pays a fixed dividend?",
    choices: ["Preferred stock", "Common stock", "A warrant", "A right"],
    answerIndex: 0,
    explanation: "Preferred carries a fixed stated dividend as a percentage of par. Common dividends are declared at the board's discretion and can change or stop. Rights and warrants are instruments for buying stock and pay nothing at all." },
  { id: "sie-prd-311", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which has the SHORTEST typical life?",
    choices: ["A warrant", "A right", "A convertible bond", "A preferred share"],
    answerIndex: 1,
    explanation: "Rights expire in roughly 30 to 45 days, which is why they must be exercised or sold quickly. Warrants run for years, convertible bonds to maturity, and preferred stock is generally perpetual unless called." },
  { id: "sie-prd-312", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor wants tax-deferred growth with no annual contribution limit. Consider:",
    choices: ["A Roth IRA", "A 401(k)", "A non-qualified annuity", "A Coverdell account"],
    answerIndex: 2,
    explanation: "Non-qualified annuities have no annual cap, and earnings grow tax-deferred until withdrawal. Every listed retirement account is capped. The trade-off is that annuity withdrawals are LIFO — earnings first, taxed as ordinary income, with a penalty before 59½." },
  { id: "sie-prd-313", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is TRUE of a fixed annuity?",
    choices: ["It is a security", "The holder picks subaccounts", "Payments vary monthly", "The insurer bears investment risk"],
    answerIndex: 3,
    explanation: "A fixed annuity pays a guaranteed amount from the insurer's general account, so the insurer carries the investment risk and no securities registration is needed to sell it. Subaccounts and varying payments belong to VARIABLE contracts." },
  { id: "sie-prd-314", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "What happens to a bond's price as it approaches maturity?",
    choices: ["It converges toward par", "It moves further from par", "It becomes more rate-sensitive", "It is unaffected"],
    answerIndex: 0,
    explanation: "Regardless of whether it trades at a discount or premium, a bond pulls to par as maturity nears, because par is what will be paid. Rate sensitivity FALLS as the remaining life shortens — the opposite of the third option." },
  { id: "sie-prd-315", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which investor benefits most from a call provision?",
    choices: ["The bondholder", "The issuer", "The trustee", "The underwriter"],
    answerIndex: 1,
    explanation: "The issuer holds the option and exercises it when rates fall, refinancing cheaply. The holder loses an above-market coupon and must reinvest at lower rates. A PUT provision is the mirror feature that benefits the holder." },
  { id: "sie-trd-197", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "What must a firm do on learning of a customer's death?",
    choices: ["Liquidate the positions", "Transfer assets to the spouse", "Freeze the account", "Continue trading"],
    answerIndex: 2,
    explanation: "The firm cancels open orders and freezes the account, then awaits a death certificate, letters testamentary, and any tax waivers. Any prior authority — including discretion — ends at death, so acting on it would be trading without authorisation." },
  { id: "sie-trd-198", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which account type is owned by one person?",
    choices: ["JTWROS", "Tenants in common", "Partnership", "Individual"],
    answerIndex: 3,
    explanation: "An individual account has a single owner with sole authority. JTWROS and tenants in common both have multiple owners differing in what happens on death, and a partnership account belongs to the entity under its partnership agreement." },
  { id: "sie-trd-199", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A pattern day trader must maintain minimum equity of:",
    choices: ["$25,000", "$2,000", "$5,000", "$10,000"],
    answerIndex: 0,
    explanation: "The pattern day trader rule requires $25,000 in the account on any day the customer day trades. That is distinct from the $2,000 minimum to open a margin account and from Reg T's 50% initial deposit." },
  { id: "sie-trd-200", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is NOT a permitted IRA investment?",
    choices: ["Common stock", "Collectibles", "Mutual funds", "Corporate bonds"],
    answerIndex: 1,
    explanation: "Collectibles — art, antiques, gems, most precious metals — and life insurance are prohibited in an IRA, because the account exists for retirement saving rather than for assets whose value is hard to verify. Ordinary securities are all permitted." },
  { id: "sie-trd-201", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "What triggers a maintenance call in a LONG margin account?",
    choices: ["Equity falling below 50%", "The debit balance rising", "Equity falling below 25% of market value", "A dividend being paid"],
    answerIndex: 2,
    explanation: "FINRA's long maintenance minimum is 25% of current market value. The 50% figure is Reg T's INITIAL deposit, a separate and earlier requirement. The debit balance is fixed and does not rise on its own." },
  { id: "sie-trd-202", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is a red flag requiring AML review?",
    choices: ["A single large wire from a known employer", "Regular monthly contributions", "A rollover from a 401(k)", "Deposits just under $10,000 repeatedly"],
    answerIndex: 3,
    explanation: "Repeated deposits just below the CTR threshold is STRUCTURING, a federal crime and a reportable red flag. A documented employer wire, routine contributions and a plan rollover are all ordinary activity with an evident source." },
  { id: "sie-trd-203", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "How long must a firm retain most books and records?",
    choices: ["Three years", "One year", "Six months", "Ten years"],
    answerIndex: 0,
    explanation: "Three years is the general rule, with the first two easily accessible. Certain records — customer account records, articles of incorporation, partnership agreements — run six years or the life of the firm." },
  { id: "sie-trd-204", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is required to open a discretionary account?",
    choices: ["A verbal instruction", "Written customer authorization", "A $25,000 balance", "SEC registration"],
    answerIndex: 1,
    explanation: "Written authorization must be in place BEFORE discretion is exercised, and each discretionary order must be marked and reviewed. The only verbal exception covers time and price on a specified trade for that day." },
  { id: "sie-mkt-138", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Who regulates broker-dealers at the federal level?",
    choices: ["The Federal Reserve", "The FDIC", "The SEC", "The Treasury"],
    answerIndex: 2,
    explanation: "The SEC has statutory authority over securities markets and broker-dealers, delegating day-to-day conduct supervision to SROs like FINRA. The Fed handles monetary policy and Reg T; the FDIC insures bank deposits; Treasury issues government debt." },
  { id: "sie-mkt-139", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "What is the primary purpose of the Securities Act of 1933?",
    choices: ["Regulating exchanges", "Licensing representatives", "Setting margin rules", "Disclosure on new issues"],
    answerIndex: 3,
    explanation: "The 1933 Act governs the primary market through forced disclosure — a registration statement and a prospectus. Exchange regulation and representative licensing flow from the 1934 Act; margin rules come from the Federal Reserve." },
  { id: "sie-mkt-140", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "An economic expansion is typically characterised by:",
    choices: ["Rising GDP and falling unemployment", "Falling GDP and rising unemployment", "Flat GDP and stable prices", "Rising unemployment and falling prices"],
    answerIndex: 0,
    explanation: "Expansion means output grows and hiring follows, though unemployment lags the turn. Falling GDP with rising unemployment describes a contraction, and the last option describes a deflationary recession." },
  { id: "sie-mkt-141", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which Federal Reserve action is EXPANSIONARY?",
    choices: ["Selling government securities", "Buying government securities", "Raising the discount rate", "Raising reserve requirements"],
    answerIndex: 1,
    explanation: "Buying securities injects reserves into the banking system, increasing the money supply and easing credit. The other three all drain reserves or raise the cost of credit, making them contractionary." },
  { id: "sie-mkt-142", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "An INVERTED yield curve occurs when:",
    choices: ["Long-term rates exceed short-term rates", "All maturities yield the same", "Short-term rates exceed long-term rates", "Rates are at historic lows"],
    answerIndex: 2,
    explanation: "Inversion means the market demands more to lend short than long, which is unusual and has historically preceded recessions. A NORMAL curve slopes upward because lenders want more for committing money longer; a FLAT curve shows little difference." },
  { id: "sie-mkt-143", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "What does GDP measure?",
    choices: ["The money supply", "The unemployment rate", "Corporate profits only", "Total output of goods and services"],
    answerIndex: 3,
    explanation: "GDP is the total value of goods and services produced. Two consecutive quarters of declining REAL GDP is the conventional shorthand for a recession. Money supply, unemployment and profits are separate indicators, and the last two lag the cycle." },
  { id: "sie-mkt-144", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Fiscal policy is controlled by:",
    choices: ["Congress, through taxing and spending", "The Federal Reserve", "The SEC", "The Treasury alone"],
    answerIndex: 0,
    explanation: "Taxing and spending are legislative tools, so fiscal policy belongs to Congress. MONETARY policy — the money supply and the cost of credit — belongs to the Fed. Exam questions often pair one of each running in opposite directions." },
  { id: "sie-mkt-145", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which is a COINCIDENT economic indicator?",
    choices: ["Building permits", "Industrial production", "The unemployment rate", "Corporate profits"],
    answerIndex: 1,
    explanation: "Industrial production moves with the cycle in real time. Building permits LEAD, turning before the economy does, while unemployment and corporate profits both LAG, confirming a turn after it has happened." },
  { id: "sie-mkt-146", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 3,
    stem: "A dealer quotes a stock 24.50 bid / 24.75 ask. A customer selling at the market receives:",
    choices: ["$24.75", "$24.625", "$24.50", "$25.00"],
    answerIndex: 2,
    explanation: "The customer sells INTO the bid of $24.50, which is what the dealer is willing to pay. The ask is what a buyer pays. The $0.25 spread is the market maker's compensation for standing ready on both sides and carrying inventory risk." },
  { id: "sie-mkt-147", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "The bid-ask spread widens most when a security is:",
    choices: ["Heavily traded", "Recently listed on a major exchange", "Included in a broad index", "Thinly traded"],
    answerIndex: 3,
    explanation: "A market maker widens the spread when it is harder to offload inventory, which is exactly the situation in a thin market. Heavy volume, major listing and index inclusion all improve liquidity and narrow spreads." },
  { id: "sie-mkt-148", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which best describes the role of the SEC in a registered offering?",
    choices: ["It reviews disclosure, not investment merit", "It approves the investment as sound", "It sets the offering price", "It guarantees the issuer's solvency"],
    answerIndex: 0,
    explanation: "Registration is a disclosure regime — the SEC checks that required facts are disclosed and never judges whether the investment is good. Claiming or implying SEC approval of a security is itself a violation." },
  { id: "sie-trd-205", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE of a cash account?",
    choices: ["Reg T requires a 50% deposit", "No borrowing is permitted", "Short selling is allowed", "Securities may be lent out"],
    answerIndex: 1,
    explanation: "A cash account requires payment in full — no credit is extended, which is what distinguishes it from a margin account. Reg T's 50%, short selling and securities lending all require a margin account and a signed margin agreement." },
  { id: "sie-trd-206", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer fails to pay for a cash account purchase by the Reg T deadline. The firm will:",
    choices: ["Extend credit automatically", "Convert it to a margin account", "Sell out the position and may freeze the account", "Take no action"],
    answerIndex: 2,
    explanation: "The firm sells out the unpaid position and may freeze the account for 90 days, during which the customer must pay in advance of any purchase. Converting to margin without a signed agreement is not permitted." },
  { id: "sie-trd-207", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which of these does NOT require the customer's signature?",
    choices: ["Opening a margin account", "Granting discretion", "Granting a power of attorney", "Opening a cash account"],
    answerIndex: 3,
    explanation: "A cash account needs no customer signature, though a principal must still approve it. Margin agreements, discretionary authority and powers of attorney all require the customer's written signature because each grants someone else a right." },
  { id: "sie-trd-208", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "The purpose of Regulation T is to:",
    choices: ["Limit the credit a broker-dealer extends for securities purchases", "Set minimum maintenance margin", "Govern short sale disclosure", "Require prospectus delivery"],
    answerIndex: 0,
    explanation: "Reg T is a Federal Reserve rule controlling the INITIAL extension of credit — currently 50%. FINRA sets the ongoing maintenance minimums of 25% long and 30% short. Prospectus delivery comes from the 1933 Act." },
  { id: "sie-trd-209", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer wants to sell short. This requires:",
    choices: ["Only a cash account", "A margin account and locating borrowable shares", "Written SEC approval", "A $25,000 minimum in all cases"],
    answerIndex: 1,
    explanation: "Short selling requires a margin account, and the firm must reasonably believe the shares can be borrowed before executing — the locate requirement. The $25,000 figure applies to pattern day traders, a separate rule." },
  { id: "sie-trd-210", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which best describes the AML customer identification requirement?",
    choices: ["Verify identity within 90 days", "Verify only for accounts over $10,000", "Verify identity before the account trades", "Rely on the customer's statement alone"],
    answerIndex: 2,
    explanation: "CIP requires collecting and verifying name, date of birth, address and taxpayer identification number before trading begins. There is no dollar threshold and no grace period, and self-attestation alone is insufficient." },
  { id: "sie-prd-316", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which product would be LEAST liquid?",
    choices: ["A listed common stock", "A Treasury bill", "An exchange-traded fund", "A limited partnership interest"],
    answerIndex: 3,
    explanation: "Limited partnership interests generally have no secondary market and are held for years, which is the defining constraint of a DPP. Listed stock, T-bills and ETFs are all readily saleable at transparent prices." },
  { id: "sie-prd-317", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor needs money in three months. The most suitable holding is:",
    choices: ["A money market fund", "A 30-year bond", "A small-cap stock fund", "A variable annuity"],
    answerIndex: 0,
    explanation: "A three-month horizon rules out anything with meaningful price risk or surrender charges. Money market funds are short, high-quality and liquid. The other three all risk principal or impose exit costs over that window." },
  { id: "sie-prd-318", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is TRUE of a variable annuity's separate account?",
    choices: ["It is guaranteed by the insurer", "It is segregated from the insurer's general assets", "It is FDIC insured", "It holds only fixed-income securities"],
    answerIndex: 1,
    explanation: "The separate account is legally segregated and holds subaccounts the contract holder selects, which is why the HOLDER bears investment risk and the product is a security. Guarantees come from the general account; insurance products are never FDIC insured." },
  { id: "sie-prd-319", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "What does a REIT primarily invest in?",
    choices: ["Government bonds", "Foreign currency", "Real estate or real-estate debt", "Commodities futures"],
    answerIndex: 2,
    explanation: "Equity REITs own properties, mortgage REITs hold real-estate debt, and hybrids do both. A REIT must distribute at least 90% of taxable income, which is why it is held for income, and it passes through income but NOT losses." },
  { id: "sie-reg-128", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "Who administers the SIE exam?",
    choices: ["The SEC", "The MSRB", "NASAA", "FINRA"],
    answerIndex: 3,
    explanation: "FINRA licenses representatives and administers the SIE, which is unusual in that it needs no firm sponsorship. The SEC oversees FINRA; the MSRB writes municipal rules without enforcing them; NASAA coordinates state regulators." },
  { id: "sie-reg-129", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "A registered representative must report a felony charge on Form U4:",
    choices: ["Within 30 days", "Only upon conviction", "Annually", "Only if it relates to securities"],
    answerIndex: 0,
    explanation: "Material changes to a U4 must be reported within 30 days, and certain disclosure events within 10 business days — a CHARGE is reportable, not just a conviction, and it need not be securities-related. The U4 feeds BrokerCheck, which is why accuracy matters so much." },
  { id: "sie-reg-130", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Statutory disqualification can result from:",
    choices: ["Any customer complaint", "A felony conviction within the past ten years", "Failing an exam twice", "Changing firms frequently"],
    answerIndex: 1,
    explanation: "Disqualifying events include a felony or securities-related misdemeanour within ten years, an SEC or SRO expulsion or bar, and a false statement on a registration application. Complaints, exam results and job changes are disclosed but are not themselves disqualifying." },
  { id: "sie-reg-131", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which communication requires principal approval before first use?",
    choices: ["Correspondence", "An institutional communication", "A retail communication", "An internal memo"],
    answerIndex: 2,
    explanation: "Retail communications — more than 25 retail investors in 30 days — need pre-approval. Correspondence (25 or fewer) is reviewed under firm procedures, and institutional material requires review procedures but no pre-approval." },
  { id: "sie-reg-132", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Performance advertising by a firm must:",
    choices: ["Show gross returns for comparability", "Present only the best-performing period", "Project expected future returns", "Be net of fees with appropriate disclosure"],
    answerIndex: 3,
    explanation: "Net-of-fee presentation with context is required, because gross figures overstate what an investor actually received. Cherry-picking favourable periods and projecting future performance are both prohibited outright." },
  { id: "sie-reg-133", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Form CRS is:",
    choices: ["A brief relationship summary for retail investors", "A registration application for representatives", "A quarterly complaint report", "A margin disclosure document"],
    answerIndex: 0,
    explanation: "Form CRS summarises services, fees, conflicts and disciplinary history in a short document for retail investors, introduced alongside Regulation Best Interest. Form U4 is the individual registration application." },
  { id: "sie-reg-134", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 3,
    stem: "Under Reg BI, the CARE obligation requires a representative to:",
    choices: ["Guarantee the recommendation performs", "Understand costs and evaluate reasonable alternatives", "Disclose only material conflicts", "Obtain written customer consent"],
    answerIndex: 1,
    explanation: "Care means understanding the product's risks and COSTS and weighing reasonably available alternatives — that cost-and-alternatives test is what distinguishes Reg BI from the old suitability standard. Disclosure and conflict management are separate obligations, and nothing may be guaranteed." },
  { id: "sie-trd-211", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is a permitted use of customer funds?",
    choices: ["Financing the firm's operations", "Lending them to another customer", "Holding them in a segregated customer account", "Investing them for the firm's account"],
    answerIndex: 2,
    explanation: "Customer funds and securities must be segregated and identifiable so they are protected if the firm fails. Using them for firm operations or proprietary investment is COMMINGLING, one of the most serious violations in the rulebook." },
  { id: "sie-trd-212", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A firm must send account statements to a customer:",
    choices: ["Annually", "Only on request", "Weekly", "At least quarterly, monthly with activity"],
    answerIndex: 3,
    explanation: "Statements go out at least quarterly, and monthly in any month with activity. CONFIRMATIONS are the separate per-trade document, due at or before completion of each transaction." },
  { id: "sie-trd-213", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer with $40,000 income and $15,000 net worth asks to invest $12,000 in a speculative private placement. The representative should:",
    choices: ["Decline, as the customer likely fails accreditation and suitability", "Execute it as unsolicited", "Obtain principal approval and proceed", "Reduce it to $5,000 and proceed"],
    answerIndex: 0,
    explanation: "Private placements are sold to ACCREDITED investors, and this customer meets neither the income nor the net worth test. Beyond accreditation, committing 80% of net worth to an illiquid speculative holding fails suitability outright. Reducing the size does not cure a failed accreditation test." },
  { id: "sie-trd-214", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is the correct treatment of a customer's verbal complaint?",
    choices: ["It must be reported to FINRA immediately", "Firms generally record it, but only WRITTEN complaints are reportable", "It requires no response", "It converts automatically to arbitration"],
    answerIndex: 1,
    explanation: "FINRA's quarterly reporting requirement attaches to WRITTEN complaints, which is why the definition specifies written grievances. Firms typically log verbal complaints under their own procedures, but the regulatory reporting trigger is the written form." },
  { id: "sie-prd-320", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor holds a bond fund. Rising rates will most likely:",
    choices: ["Increase the fund's NAV", "Have no effect on NAV", "Reduce the fund's net asset value", "Increase the fund's credit quality"],
    answerIndex: 2,
    explanation: "A bond fund holds bonds, so its NAV falls when rates rise and existing holdings become less competitive. Longer average maturity means a larger decline. Credit quality is a separate characteristic unaffected by rate moves." },
  { id: "sie-prd-321", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which fund type would suit an investor seeking maximum diversification at lowest cost?",
    choices: ["A sector fund", "A single-country fund", "A concentrated growth fund", "A broad-market index fund"],
    answerIndex: 3,
    explanation: "A broad index fund holds the whole market at minimal expense, since there is no research team to fund and turnover is low. Sector, single-country and concentrated funds all deliberately narrow exposure, which raises unsystematic risk." },
  { id: "sie-prd-322", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A municipal bond fund's dividends are generally:",
    choices: ["Exempt from federal income tax", "Fully taxable", "Taxed as capital gains", "Subject to a flat 15% rate"],
    answerIndex: 0,
    explanation: "The federal exemption on municipal interest passes through the fund to shareholders. Note two limits: capital gains distributions from the fund remain taxable, and private activity holdings can create AMT exposure." },
  { id: "sie-prd-323", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor buys a 50 call for 5 and the stock finishes at 52. The result is:",
    choices: ["A $200 gain", "A $300 loss", "A $500 gain", "Break-even"],
    answerIndex: 1,
    explanation: "Intrinsic value is $52 − $50 = $2, so exercising recovers $200 of the $500 premium — a net loss of $300 per contract. Breakeven was $55. The option is in-the-money and still loses money, which is the distinction the question tests." },
  { id: "sie-prd-324", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which best describes a UIT's termination?",
    choices: ["It continues indefinitely", "It terminates when the sponsor chooses", "It terminates on a preset date", "It terminates only if investors vote"],
    answerIndex: 2,
    explanation: "A unit investment trust holds a fixed portfolio and dissolves on a date set at formation, distributing proceeds to holders. It has no board and no adviser, which is exactly what distinguishes it from a managed fund." },
  { id: "sie-prd-325", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which security has the highest claim in a corporate liquidation?",
    choices: ["Debentures", "Preferred stock", "Common stock", "Secured bonds"],
    answerIndex: 3,
    explanation: "The waterfall runs secured creditors, then unsecured creditors including debentures, then preferred, then common last. Each step down carries more risk, which is why each must offer more expected return." },
  { id: "sie-reg-135", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "An SRO derives its authority from:",
    choices: ["SEC oversight and approval", "Congress directly", "State legislatures", "Member firm votes alone"],
    answerIndex: 0,
    explanation: "Self-regulatory organisations write and enforce rules subject to SEC approval and oversight. They are industry-funded rather than governmental, which is what makes them 'self' regulatory, but every rule they adopt must clear the SEC." },
  { id: "sie-reg-136", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "The Investment Company Act of 1940 governs:",
    choices: ["Broker-dealer conduct", "Mutual funds, closed-end funds, and UITs", "New issue registration", "Bond indentures"],
    answerIndex: 1,
    explanation: "The 1940 Act classifies and regulates investment companies into three types: face-amount certificate companies, unit investment trusts, and management companies. Broker-dealer conduct comes from the 1934 Act, new issues from 1933, and indentures from the Trust Indenture Act of 1939." },
  { id: "sie-reg-137", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "The Investment Advisers Act of 1940 primarily addresses:",
    choices: ["Exchange listing standards", "Margin requirements", "Registration and conduct of advisers", "Municipal disclosure"],
    answerIndex: 2,
    explanation: "The Advisers Act covers who must register as an investment adviser and the fiduciary conduct standards that follow. Listing standards belong to exchanges, margin to the Federal Reserve, and municipal disclosure to the MSRB." },
  { id: "sie-reg-138", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Sarbanes-Oxley primarily addressed:",
    choices: ["Margin lending", "Options clearing", "Municipal underwriting", "Corporate governance and financial reporting"],
    answerIndex: 3,
    explanation: "SOX responded to accounting scandals with officer certification of financial statements, internal control reporting, and auditor independence requirements. It targets issuers and their auditors rather than trading mechanics." },
  { id: "sie-reg-139", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Dodd-Frank was enacted in response to:",
    choices: ["The 2008 financial crisis", "The 1929 crash", "The dot-com collapse", "The 1987 crash"],
    answerIndex: 0,
    explanation: "Dodd-Frank followed the 2008 crisis, adding systemic risk oversight, derivatives regulation, and the municipal advisor registration regime. The 1929 crash produced the 1933 and 1934 Acts." },
  { id: "sie-reg-140", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "A firm must deliver Form CRS to a retail investor:",
    choices: ["Annually only", "At or before the earliest of a recommendation or account opening", "Only on request", "Within 30 days after the first trade"],
    answerIndex: 1,
    explanation: "Form CRS goes out at the beginning of the relationship — at or before a recommendation, an account opening, or placing an order. It is a relationship summary, so delivering it after the fact would defeat its purpose." },
  { id: "sie-reg-141", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 3,
    stem: "A representative posts about a specific security on a public social media account. This is most likely:",
    choices: ["Correspondence", "An institutional communication", "A retail communication requiring principal approval", "Exempt from FINRA rules"],
    answerIndex: 2,
    explanation: "A public post reaches an unlimited retail audience, so it exceeds the 25-investor correspondence threshold and is a retail communication requiring pre-approval. Static social content is generally treated as advertising; nothing about the medium exempts it from the content standards." },
  { id: "sie-reg-142", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Records of communications with the public must generally be retained for:",
    choices: ["One year", "Six years", "Ten years", "Three years"],
    answerIndex: 3,
    explanation: "Three years, with the first two easily accessible — the same general standard as most books and records. Certain records such as customer account records and articles of incorporation run six years or the life of the firm." },
  { id: "sie-reg-143", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which is TRUE of the Firm Element of continuing education?",
    choices: ["The firm designs it from an annual needs analysis", "FINRA writes and delivers it", "It applies only to principals", "It is completed once at hire"],
    answerIndex: 0,
    explanation: "The firm conducts an annual needs analysis and builds training around the products and risks its own people actually handle. The REGULATORY Element is the FINRA-written computer-based piece, due annually by December 31." },
  { id: "sie-reg-144", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which activity requires written notice to the firm BEFORE engaging in it?",
    choices: ["Voting personal shares", "An outside business activity", "Opening a personal bank account", "Attending an industry conference"],
    answerIndex: 1,
    explanation: "Outside business activities must be disclosed in writing beforehand, whether or not they involve securities — the firm decides whether a conflict exists. Private securities transactions additionally require firm approval where compensation is involved." },
  { id: "sie-reg-145", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 3,
    stem: "A representative sells a private investment to a client outside the firm and receives a commission, without telling the firm. This is:",
    choices: ["Permitted as an outside business activity", "Permitted if the client signs a waiver", "Selling away, a serious violation", "Only a violation if the investment loses money"],
    answerIndex: 2,
    explanation: "Executing securities business away from the firm with compensation requires written notice AND firm approval; doing it without either is selling away. It defeats supervision entirely. No client waiver cures it, and the violation is complete regardless of how the investment performs." },
  { id: "sie-reg-146", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which best describes SIPC coverage limits?",
    choices: ["$250,000 total including cash", "$500,000 cash only", "Unlimited for securities", "$500,000 total, of which $250,000 may be cash"],
    answerIndex: 3,
    explanation: "The ceiling is $500,000 per separate customer, with cash capped at $250,000 inside that. Apply the cash sublimit first, then the overall ceiling — and remember it covers firm failure, never investment losses." },
  { id: "sie-reg-147", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "An investor loses money because a stock declined. SIPC will:",
    choices: ["Provide no coverage", "Cover up to $500,000", "Cover up to $250,000", "Cover the full loss"],
    answerIndex: 0,
    explanation: "Market losses are the risk the investor knowingly accepted, and no SIPC coverage applies. SIPC exists for the failure of the INTERMEDIARY holding the assets — the distinction between a failed firm and a failed investment." },
  { id: "sie-trd-215", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE about opening a joint account?",
    choices: ["Only one owner need sign", "All owners must sign the account agreement", "A principal signature substitutes", "No signatures are required"],
    answerIndex: 1,
    explanation: "Every owner signs, because each is granting authority over jointly held property. Either owner may then typically trade, but checks are normally issued in all owners' names — a control that prevents one party quietly extracting the assets." },
  { id: "sie-trd-216", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "An UGMA account's assets are reported under whose tax identification number?",
    choices: ["The custodian's", "The donor's", "The minor's", "The firm's"],
    answerIndex: 2,
    explanation: "The assets belong to the minor from the moment of the irrevocable gift, so the minor's Social Security number is used and the income is taxed to the minor. The custodian merely manages the property." },
  { id: "sie-trd-217", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer's account has an objective of speculation and they request a covered call strategy. This is:",
    choices: ["Prohibited for speculative accounts", "Only permitted with a margin agreement", "Unsuitable and must be refused", "Conservative relative to their stated objective, and generally acceptable"],
    answerIndex: 3,
    explanation: "A covered call is an income strategy more conservative than pure speculation, so it sits well inside what the account permits. Suitability guards against recommendations that are too AGGRESSIVE for the profile; a more conservative request is not a violation. It can be done in a cash account since the stock is owned." },
  { id: "sie-trd-218", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which order would a customer use to buy a stock only if it breaks above resistance?",
    choices: ["A buy stop above the market", "A buy limit below the market", "A market order", "A sell stop"],
    answerIndex: 0,
    explanation: "A buy stop placed above the market triggers once the price reaches it, which is how a momentum buyer enters on a breakout. A buy LIMIT below the market does the opposite — it waits for a decline." },
  { id: "sie-prd-326", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor's primary objective is preservation of capital. The most suitable is:",
    choices: ["A high-yield bond fund", "A Treasury money market fund", "An emerging markets fund", "A leveraged ETF"],
    answerIndex: 1,
    explanation: "Preservation demands minimal credit and price risk, which a Treasury money market fund provides. High-yield carries default risk, emerging markets adds currency and political risk, and leveraged products amplify losses daily." },
  { id: "sie-prd-327", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which describes the risk of a leveraged ETF held long term?",
    choices: ["It cannot lose more than the index", "It tracks the index exactly over any period", "Daily rebalancing causes returns to diverge from the index multiple", "It carries no market risk"],
    answerIndex: 2,
    explanation: "Leveraged ETFs reset daily, so compounding over multiple periods causes the return to drift from a simple multiple of the index — sometimes badly in volatile markets. They are designed as short-term trading tools, which is why long holding periods are the trap." },
  { id: "sie-prd-328", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which security represents a loan to a corporation?",
    choices: ["Common stock", "Preferred stock", "A warrant", "A corporate bond"],
    answerIndex: 3,
    explanation: "A bondholder is a creditor with a contractual claim on interest and principal, ranking ahead of all equity in liquidation. Common and preferred are ownership; a warrant is a right to buy shares later." },
  { id: "sie-prd-329", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A call option gives the buyer the right to:",
    choices: ["Buy", "Sell", "Vote", "Lend"],
    answerIndex: 0,
    explanation: "A call is the right to BUY at the strike price; a put is the right to sell. Options confer no voting rights and involve no lending." },
  { id: "sie-prd-330", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A put option gives the buyer the right to:",
    choices: ["Buy", "Sell", "Convert", "Redeem"],
    answerIndex: 1,
    explanation: "A put is the right to SELL at the strike price. Calls are the right to buy. Conversion belongs to convertible securities, redemption to the issuer." },
  { id: "sie-prd-331", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which stock class normally carries voting rights?",
    choices: ["Preferred", "Treasury", "Common", "Restricted"],
    answerIndex: 2,
    explanation: "Common stock carries the vote. Preferred normally has none, and treasury shares held by the company itself have no vote and receive no dividend." },
  { id: "sie-prd-332", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "T-bills are sold at a:",
    choices: ["Premium", "Par", "Markup", "Discount"],
    answerIndex: 3,
    explanation: "T-bills are issued at a discount and mature at face value, with the difference being the entire return. They pay no coupon, so nothing accrues between dates." },
  { id: "sie-prd-333", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Bond prices and interest rates move:",
    choices: ["Inversely", "Together", "Independently", "Proportionally"],
    answerIndex: 0,
    explanation: "When rates rise an existing fixed coupon becomes less competitive, so price must fall until the yield matches new issues. This inverse relationship is the most heavily tested fact in fixed income." },
  { id: "sie-prd-334", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which risk cannot be diversified away?",
    choices: ["Business", "Systematic", "Credit", "Liquidity"],
    answerIndex: 1,
    explanation: "Systematic risk moves the whole market at once, so more holdings do not escape it — which is exactly why it is the only risk investors are compensated for bearing. The other three are company-specific." },
  { id: "sie-prd-335", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A REIT must distribute at least:",
    choices: ["50%", "75%", "90%", "100%"],
    answerIndex: 2,
    explanation: "At least 90% of taxable income must be distributed to retain REIT tax treatment, which is why REITs are held for income. They pass through income but not losses." },
  { id: "sie-prd-336", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is a money market instrument?",
    choices: ["A 10-year note", "A convertible bond", "Preferred stock", "Commercial paper"],
    answerIndex: 3,
    explanation: "Money market means one year or less. Commercial paper caps at 270 days. A 10-year note, a convertible bond and preferred stock are all long-dated or perpetual." },
  { id: "sie-prd-337", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Ginnie Mae securities are backed by:",
    choices: ["The U.S. government", "A state guarantee", "Private insurance", "Nothing"],
    answerIndex: 0,
    explanation: "Ginnie Mae is a government corporation and its pass-throughs carry the EXPLICIT full faith and credit of the United States. Fannie Mae and Freddie Mac are GSEs with only implied backing." },
  { id: "sie-prd-338", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Municipal bond interest is generally exempt from:",
    choices: ["All tax", "Federal tax", "State tax only", "Capital gains tax"],
    answerIndex: 1,
    explanation: "Interest is federally exempt, and usually exempt in the issuer's own state too. Capital GAINS on selling a muni remain fully taxable, which candidates routinely over-generalise." },
  { id: "sie-trd-219", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Regular-way settlement is:",
    choices: ["T+2", "T+3", "T+1", "Same-day"],
    answerIndex: 2,
    explanation: "T+1 since May 2024 for stocks, corporate and municipal bonds, government securities and listed options. T+2 was the prior standard and still appears in outdated material." },
  { id: "sie-trd-220", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Reg T initial margin is:",
    choices: ["25%", "30%", "100%", "50%"],
    answerIndex: 3,
    explanation: "The Federal Reserve sets 50% as the initial deposit. FINRA's maintenance minimums are 25% long and 30% short, and full payment applies in a cash account." },
  { id: "sie-trd-221", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A CTR is filed for cash over:",
    choices: ["$10,000", "$5,000", "$25,000", "$3,000"],
    answerIndex: 0,
    explanation: "The currency transaction report threshold is $10,000 in a day and filing is mechanical. The $5,000 figure belongs to the suspicious activity report, which requires judgement and is never disclosed to the customer." },
  { id: "sie-trd-222", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Discretion requires authorization that is:",
    choices: ["Verbal", "Written", "Implied", "Notarized"],
    answerIndex: 1,
    explanation: "Written authorization must be in place before discretion is exercised. The one narrow exception covers time and price on a specified trade, good only for that day." },
  { id: "sie-trd-223", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Excessive trading for commissions is called:",
    choices: ["Structuring", "Commingling", "Churning", "Hypothecation"],
    answerIndex: 2,
    explanation: "Churning is judged against the customer's objectives and resources rather than any fixed trade count. Structuring evades cash reporting; commingling mixes assets; hypothecation is legitimate pledging of collateral." },
  { id: "sie-trd-224", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Gifts in connection with business are capped at:",
    choices: ["$250", "$500", "$50", "$100"],
    answerIndex: 3,
    explanation: "$100 per person per year — low enough to prevent influence rather than price it. Ordinary business entertainment where both parties attend is treated separately." },
  { id: "sie-trd-225", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "FINRA arbitration decisions are:",
    choices: ["Binding", "Advisory", "Appealable", "Voluntary"],
    answerIndex: 0,
    explanation: "Arbitration is binding with essentially no right of appeal. MEDIATION is the voluntary, non-binding alternative either party may abandon — that contrast is the tested distinction." },
  { id: "sie-mkt-149", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "An IPO occurs in which market?",
    choices: ["Secondary", "Primary", "Third", "Fourth"],
    answerIndex: 1,
    explanation: "An IPO sells newly created shares and the issuer receives the proceeds, which defines a primary transaction. Third and fourth markets are secondary trading venues." },
  { id: "sie-mkt-150", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "A broker is compensated by a:",
    choices: ["Markup", "Spread", "Commission", "Concession"],
    answerIndex: 2,
    explanation: "A broker acts as agent and charges a commission. A DEALER acts as principal and earns a markup. The confirmation must disclose which capacity applied." },
  { id: "sie-mkt-151", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Which agency oversees FINRA?",
    choices: ["FDIC", "Treasury", "MSRB", "SEC"],
    answerIndex: 3,
    explanation: "The SEC oversees FINRA as a self-regulatory organisation and must approve its rules. The MSRB writes municipal rules without enforcement power of its own." },
  { id: "sie-mkt-152", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Unemployment is which type of indicator?",
    choices: ["Lagging", "Leading", "Coincident", "Neutral"],
    answerIndex: 0,
    explanation: "Firms cut and hire only after conditions have clearly changed, so unemployment confirms a turn rather than predicting it. Building permits and stock prices LEAD; industrial production is coincident." },
  { id: "sie-trd-226", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which account permits borrowing to buy securities?",
    choices: ["Cash", "Margin", "Custodial", "Trust"],
    answerIndex: 1,
    explanation: "Only a margin account extends credit, and it requires a signed margin agreement. Cash accounts require payment in full, and custodial accounts are barred from margin because the standard is prudent management of a minor's property." },
  { id: "sie-trd-227", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "An order good only for the current session is a:",
    choices: ["GTC order", "Open order", "Day order", "Standing order"],
    answerIndex: 2,
    explanation: "A day order expires at the close and is the default when no duration is given. GTC, open and standing all describe the same thing — an order carried forward until executed or cancelled." },
  { id: "sie-trd-228", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is required to open ANY new customer account?",
    choices: ["A margin agreement", "An options agreement", "A power of attorney", "Principal approval"],
    answerIndex: 3,
    explanation: "Every new account requires a principal's approval. The other three attach only to specific account types or arrangements — margin borrowing, options trading, and third-party authority respectively." },
  { id: "sie-trd-229", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Under CIP, verification must occur:",
    choices: ["Before the account trades", "Within 90 days", "At the first withdrawal", "Annually"],
    answerIndex: 0,
    explanation: "Identity must be collected and verified before trading begins — there is no grace period and no dollar threshold. That timing is what makes CIP an effective anti-money-laundering control rather than a formality." },
  { id: "sie-trd-230", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A SAR must be filed for suspicious activity of at least:",
    choices: ["$10,000", "$5,000", "$25,000", "$1,000"],
    answerIndex: 1,
    explanation: "The SAR threshold is $5,000 and filing requires judgement. The $10,000 figure is the CTR, a mechanical cash filing. Reversing the two is the most common AML error, and the customer is never told a SAR was filed." },
  { id: "sie-trd-231", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE of a fiduciary account?",
    choices: ["It permits unlimited speculation", "It requires no documentation", "It is governed by the controlling document", "It may always trade on margin"],
    answerIndex: 2,
    explanation: "A trust, estate or guardianship account is bound by its governing document and the prudent investor standard. Speculation and margin are typically restricted precisely because the assets belong to someone else." },
  { id: "sie-trd-232", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "An account holder wants their spouse to be able to trade. This requires:",
    choices: ["A verbal instruction", "Marriage documentation", "Nothing, spouses are automatic", "A written power of attorney"],
    answerIndex: 3,
    explanation: "Third-party trading authority requires a written power of attorney — limited for trading only, full to also withdraw assets. Marriage confers no automatic authority over a separately titled account." },
  { id: "sie-trd-233", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer places a market order at 3:59 p.m. and the price moves sharply before the fill. The customer:",
    choices: ["Is bound by the execution price", "May cancel after the fact", "Receives the price quoted at entry", "May demand the closing price"],
    answerIndex: 0,
    explanation: "A market order guarantees execution, not price — the customer accepted that trade-off by choosing it. Once executed the trade stands. A LIMIT order is the instrument for controlling price, at the cost of possibly not filling at all." },
  { id: "sie-trd-234", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is a legitimate reason to freeze an account?",
    choices: ["A single unprofitable trade", "Notice of the customer's death", "A customer complaint", "High trading volume"],
    answerIndex: 1,
    explanation: "Death requires immediate cancellation of open orders and a freeze pending documentation, because all prior authority ends. Losses, complaints and volume trigger review or reporting but not a freeze." },
  { id: "sie-trd-235", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Reinvesting a customer's dividends without authorization is:",
    choices: ["Permitted if beneficial", "Standard practice", "Unauthorized trading", "Discretionary authority"],
    answerIndex: 2,
    explanation: "Any transaction the customer did not authorise is unauthorized trading, and being profitable is no defence — the violation is acting without consent. Automatic reinvestment must be elected by the customer in advance." },
  { id: "sie-trd-236", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A representative splits a large order across two days to keep each below a reporting threshold. This resembles:",
    choices: ["Best execution", "Order splitting for price improvement", "Averaging in", "Structuring"],
    answerIndex: 3,
    explanation: "Deliberately arranging transactions to stay under a reporting threshold is structuring, and the intent to evade is the offence itself. Working an order over time for genuine execution quality is legitimate — the difference is entirely the purpose." },
  { id: "sie-prd-339", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which has the highest priority in liquidation?",
    choices: ["Secured creditors", "Preferred stock", "Common stock", "Warrants"],
    answerIndex: 0,
    explanation: "Secured creditors are paid first, then unsecured creditors including bondholders, then preferred, then common last. Warrants are rights to buy shares and rank below even common." },
  { id: "sie-prd-340", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A bond selling above par is trading at a:",
    choices: ["Discount", "Premium", "Par value", "Basis"],
    answerIndex: 1,
    explanation: "Above par is a premium, which usually means the coupon exceeds current market rates. At a premium the yield ordering inverts: nominal > current > YTM > YTC, because the buyer loses the premium as the price pulls to par." },
  { id: "sie-prd-341", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which measure ignores any gain or loss at maturity?",
    choices: ["Yield to maturity", "Yield to call", "Current yield", "Yield to worst"],
    answerIndex: 2,
    explanation: "Current yield divides the coupon by the market price and stops there. YTM, YTC and yield to worst all incorporate the pull to par or to the call price, which is why they differ from current yield on any bond not trading at par." },
  { id: "sie-prd-342", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor wants the highest current income and accepts credit risk. Consider:",
    choices: ["Treasury bills", "Growth stocks", "Zero-coupon bonds", "High-yield corporate bonds"],
    answerIndex: 3,
    explanation: "High-yield bonds pay more precisely because they carry default risk. T-bills are the safest and lowest-yielding, growth stocks pay little income, and zeros pay nothing until maturity." },
  { id: "sie-prd-343", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which fund charges a contingent deferred sales charge?",
    choices: ["Class B", "Class A", "A no-load fund", "An index ETF"],
    answerIndex: 0,
    explanation: "Class B shares carry a CDSC that declines each year and eventually disappears, at which point they typically convert to Class A. Class A charges a front-end load; no-load funds and ETFs charge neither." },
  { id: "sie-prd-344", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An annuity's accumulation phase ends at:",
    choices: ["The first withdrawal", "Annuitization", "Age 59½", "Death of the contract holder"],
    answerIndex: 1,
    explanation: "Annuitization converts accumulation units to annuity units and starts the income phase — and the decision is generally irrevocable, which is why many holders take withdrawals instead. Age 59½ concerns the early-withdrawal penalty, not the phase change." },
  { id: "sie-mkt-153", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "An issuer's securities are sold to institutional buyers without a public offering. This is a:",
    choices: ["Public offering", "Secondary distribution", "Private placement", "Tender offer"],
    answerIndex: 2,
    explanation: "A private placement relies on an exempt TRANSACTION under Regulation D — the exemption comes from how it is sold, principally to accredited investors, rather than from what the security is." },
  { id: "sie-mkt-154", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which describes the role of a syndicate in an underwriting?",
    choices: ["A single firm buys the entire issue", "The issuer sells directly to the public", "Investors bid competitively", "Multiple underwriters share the distribution and risk"],
    answerIndex: 3,
    explanation: "A syndicate spreads a large deal across several underwriters under a syndicate manager, reducing any one firm's exposure. A selling group may help distribute but takes no underwriting commitment and bears no risk." },
  { id: "sie-mkt-155", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "The selling concession is paid to:",
    choices: ["Whoever places the shares with investors", "The issuer", "The clearing corporation", "The transfer agent"],
    answerIndex: 0,
    explanation: "The concession is the largest slice of the underwriting spread and goes to the firm that actually finds the buyer. The spread also contains the manager's fee and the underwriting fee, which compensate different functions." },
  { id: "sie-prd-345", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is an equity security?",
    choices: ["A debenture", "Common stock", "A T-bill", "Commercial paper"],
    answerIndex: 1,
    explanation: "Common stock is ownership with a residual claim. Debentures, T-bills and commercial paper are all debt — the holder is a creditor ranking ahead of owners in liquidation." },
  { id: "sie-prd-346", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Warrants are usually issued:",
    choices: ["To all shareholders", "By the Treasury", "Attached to a bond", "At a discount to market"],
    answerIndex: 2,
    explanation: "Warrants sweeten a debt offering and are struck ABOVE market, so they carry no intrinsic value at issue. RIGHTS go to existing shareholders and are struck BELOW market, giving them immediate value." },
  { id: "sie-prd-347", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A stock split affects a shareholder's total position value by:",
    choices: ["Doubling it", "Halving it", "An amount set by the board", "Nothing"],
    answerIndex: 3,
    explanation: "Share count and price change proportionally, so total value is unchanged and no taxable event occurs. Cost basis per share adjusts along with the price — a detail that matters when the shares are eventually sold." },
  { id: "sie-prd-348", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which preferred feature lets the holder exchange shares for common?",
    choices: ["Convertible", "Cumulative", "Participating", "Callable"],
    answerIndex: 0,
    explanation: "Conversion is a right belonging to the HOLDER. Cumulative accrues missed dividends, participating allows more than the stated rate, and callable is the issuer's right to redeem — the only one on the list favouring the issuer." },
  { id: "sie-prd-349", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An ADR holder typically does NOT receive:",
    choices: ["Dividends", "Voting rights", "Price appreciation", "A tradeable security"],
    answerIndex: 1,
    explanation: "ADR holders usually have no vote, though they do receive dividends converted to dollars and full price exposure. They also retain CURRENCY risk, since the underlying remains foreign-denominated." },
  { id: "sie-prd-350", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which bond would an issuer most likely call?",
    choices: ["A low-coupon bond after rates rise", "A bond trading at a deep discount", "A high-coupon bond after rates fall", "A bond near maturity"],
    answerIndex: 2,
    explanation: "Issuers call to refinance cheaply, so the target is an expensive high coupon once rates have dropped. That is exactly the worst moment for the holder, who must reinvest at the new lower rates." },
  { id: "sie-prd-351", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which yield does a callable premium bond quote to investors?",
    choices: ["Nominal yield", "Current yield", "Yield to maturity only", "Yield to worst"],
    answerIndex: 3,
    explanation: "Yield to worst is the lower of yield to maturity and yield to call, so the investor sees the least favourable realistic outcome rather than the most flattering. On a premium bond the call yield is typically the lower figure." },
  { id: "sie-prd-352", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is a mortgage-backed security?",
    choices: ["A Ginnie Mae pass-through", "A Treasury bill", "A municipal GO bond", "Commercial paper"],
    answerIndex: 0,
    explanation: "Ginnie Mae pass-throughs distribute homeowners' mortgage payments to certificate holders, which introduces prepayment and extension risk absent from ordinary bonds. Only Ginnie Mae carries an explicit federal guarantee." },
  { id: "sie-prd-353", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Extension risk on a mortgage security occurs when rates:",
    choices: ["Fall", "Rise", "Stay flat", "Become negative"],
    answerIndex: 1,
    explanation: "Rising rates slow refinancing, so principal comes back more slowly and the holder is locked into a below-market yield for longer. FALLING rates cause the mirror problem, prepayment risk." },
  { id: "sie-prd-354", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A closed-end fund trading below NAV is at a:",
    choices: ["Premium", "Par", "Discount", "Spread"],
    answerIndex: 2,
    explanation: "Below NAV is a discount, which can persist for long periods because closed-end funds lack the creation-and-redemption mechanism that keeps ETFs near NAV. Above NAV is a premium." },
  { id: "sie-prd-355", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is TRUE about a no-load fund?",
    choices: ["It charges no fees at all", "It cannot pay 12b-1 fees", "It has no expense ratio", "It charges no sales charge"],
    answerIndex: 3,
    explanation: "No-load means no sales charge, not no cost — every fund has an expense ratio. A fund charging a 12b-1 fee above 0.25% may not call itself no-load, but a smaller 12b-1 is compatible with the label." },
  { id: "sie-prd-356", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which investor is best suited to a variable annuity?",
    choices: ["A long-horizon investor with other liquid assets", "Someone needing funds next year", "A client with no retirement savings", "An investor seeking guaranteed principal"],
    answerIndex: 0,
    explanation: "Variable annuities carry surrender charges, higher fees and market risk, so they suit a long horizon where liquidity needs are met elsewhere. A guaranteed principal objective points to a FIXED annuity instead." },
  { id: "sie-prd-357", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which product passes losses through to investors?",
    choices: ["A REIT", "A direct participation program", "A mutual fund", "An ETF"],
    answerIndex: 1,
    explanation: "A DPP passes through both income and losses. A REIT passes through income only — that is the distinction the exam tests. Funds and ETFs distribute income and gains but not operating losses." },
  { id: "sie-prd-358", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Passive losses from a DPP may generally offset:",
    choices: ["Wages", "Interest income", "Passive income", "Dividend income"],
    answerIndex: 2,
    explanation: "Passive losses offset passive income only — not wages and not portfolio income like interest or dividends. That limitation is what makes DPPs far weaker tax shelters than investors often assume." },
  { id: "sie-prd-359", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which risk is greatest for a single-stock portfolio?",
    choices: ["Systematic", "Inflation", "Interest rate", "Unsystematic"],
    answerIndex: 3,
    explanation: "Concentration maximises company-specific risk, and because that risk could be removed for free through diversification, the market pays nothing extra for carrying it. That is what makes concentration imprudent rather than merely risky." },
  { id: "sie-prd-360", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which best hedges purchasing power risk?",
    choices: ["TIPS", "Long-term fixed-rate bonds", "Zero-coupon bonds", "Fixed annuities"],
    answerIndex: 0,
    explanation: "TIPS adjust principal with the CPI so both coupon and final principal keep pace with inflation. The other three all deliver fixed nominal amounts, which is precisely what inflation erodes." },
  { id: "sie-trd-237", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE about a customer's mailing instructions?",
    choices: ["Mail may be held indefinitely", "Statements may be held only under limited conditions", "Mail may be sent to the representative", "No records are required"],
    answerIndex: 1,
    explanation: "Holding mail is permitted only for limited periods with a written customer instruction and a stated reason such as travel. Sending customer mail to the representative's own address is a classic red flag for concealment." },
  { id: "sie-trd-238", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A representative may borrow money from a customer only if:",
    choices: ["The customer agrees verbally", "The amount is under $10,000", "The firm permits it and the relationship qualifies", "It is repaid within a year"],
    answerIndex: 2,
    explanation: "Borrowing is prohibited unless the firm has written procedures allowing it and the relationship fits a narrow permitted category — such as an immediate family member or a customer in the lending business. Amount and repayment terms do not create an exception." },
  { id: "sie-mkt-156", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which best describes 'best execution'?",
    choices: ["Always routing to the primary exchange", "Guaranteeing the best price available", "Executing at the closing price", "Using reasonable diligence to get the most favourable terms"],
    answerIndex: 3,
    explanation: "Best execution is a diligence standard weighing price, speed, likelihood of execution and cost — it is not a guarantee of the single best price, which no firm could promise. Routing decisions must serve the customer rather than the firm's economics." },
  { id: "sie-mkt-157", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Payment for order flow must be:",
    choices: ["Disclosed to customers", "Prohibited entirely", "Approved by the SEC per trade", "Shared with the customer"],
    answerIndex: 0,
    explanation: "Payment for order flow is permitted but must be disclosed, because it creates a conflict between the firm's routing economics and the customer's execution quality. The best execution obligation still applies regardless of who pays for the flow." },
  { id: "sie-prd-361", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which security has no maturity date?",
    choices: ["A T-note", "Common stock", "A debenture", "Commercial paper"],
    answerIndex: 1,
    explanation: "Equity is perpetual — there is no date on which the company must repay a shareholder. All debt instruments carry a stated maturity at which principal is due." },
  { id: "sie-prd-362", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A bond's coupon is expressed as a percentage of:",
    choices: ["Market price", "Current yield", "Par value", "Book value"],
    answerIndex: 2,
    explanation: "The coupon applies to par, conventionally $1,000, so a 5% coupon pays $50 a year regardless of what the bond trades for. Dividing that $50 by the market PRICE gives current yield instead." },
  { id: "sie-prd-363", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which describes a serial bond issue?",
    choices: ["All bonds mature on one date", "Interest is paid at maturity only", "The issuer may call at any time", "Portions mature on staggered dates"],
    answerIndex: 3,
    explanation: "Serial maturities retire the debt in stages, which is common in municipal issues and why serials are often quoted on a yield basis. A TERM issue matures all at once and is quoted as a dollar price." },
  { id: "sie-prd-364", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor holding a bond to maturity avoids:",
    choices: ["Price risk from interim rate moves", "Credit risk", "Inflation risk", "Reinvestment risk on coupons"],
    answerIndex: 0,
    explanation: "Holding to maturity means receiving par regardless of what the price did along the way, so interim price swings never crystallise. Credit and inflation risk persist, and coupons still have to be reinvested at prevailing rates." },
  { id: "sie-prd-365", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which fund would hold the most concentrated risk?",
    choices: ["A total market index fund", "A single-sector fund", "A balanced fund", "A global equity fund"],
    answerIndex: 1,
    explanation: "Concentrating in one sector means the whole holding rises and falls with that industry's fortunes — unsystematic risk the market does not pay extra for. Broad, balanced and global funds all spread that exposure." },
  { id: "sie-prd-366", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Dollar cost averaging involves:",
    choices: ["Buying a fixed number of shares monthly", "Timing purchases to market lows", "Investing a fixed dollar amount at regular intervals", "Selling to rebalance quarterly"],
    answerIndex: 2,
    explanation: "A fixed dollar amount buys more shares when prices are low and fewer when high, lowering the average cost per share over time. Buying a fixed SHARE count does the opposite and is the common distractor." },
  { id: "sie-prd-367", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which product typically imposes a surrender charge?",
    choices: ["A money market fund", "A listed stock", "A Treasury bill", "An annuity"],
    answerIndex: 3,
    explanation: "Annuities recover their upfront costs through surrender charges that decline over several years, which is why they suit long horizons and fail a client who may need the money soon." },
  { id: "sie-prd-368", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is a derivative?",
    choices: ["An option", "A common share", "A Treasury bond", "A CD"],
    answerIndex: 0,
    explanation: "An option derives its value from an underlying security rather than representing ownership or a loan. Shares are equity, bonds and CDs are debt." },
  { id: "sie-prd-369", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An option's premium consists of:",
    choices: ["Strike price plus commission", "Intrinsic value plus time value", "Par value plus accrued interest", "Bid plus ask"],
    answerIndex: 1,
    explanation: "Intrinsic value is what exercising is worth now; time value pays for the chance the position improves before expiry. Time value decays as expiration approaches, working against the buyer." },
  { id: "sie-prd-370", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which investor benefits from rising interest rates?",
    choices: ["A holder of long-term fixed-rate bonds", "A holder of zero-coupon bonds", "Someone reinvesting maturing short-term bonds", "A preferred stockholder"],
    answerIndex: 2,
    explanation: "Rising rates let a reinvestor redeploy at better yields — short maturities recycle quickly enough to capture that. Long bonds, zeros and preferred all fall in price when rates rise, with zeros falling most." },
  { id: "sie-trd-239", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is needed to sell securities short?",
    choices: ["A cash account", "An options agreement", "A trust document", "A margin account"],
    answerIndex: 3,
    explanation: "Short selling requires a margin account, and the firm must reasonably believe the shares can be borrowed before executing — the locate requirement. Short maintenance margin is 30%, higher than the 25% long side because losses are unbounded." },
  { id: "sie-trd-240", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A representative must report an outside brokerage account to:",
    choices: ["Their employing firm", "The SEC", "FINRA directly", "No one"],
    answerIndex: 0,
    explanation: "Employees must disclose outside accounts so the firm can supervise their personal trading and detect front-running or conflicts. The executing firm typically must also send duplicate confirmations to the employer." },
  { id: "sie-trd-241", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is the correct handling of a customer's stock certificate delivered in good order?",
    choices: ["Return it to the customer", "Credit it to the account and forward for transfer", "Hold it uncredited", "Sell it immediately"],
    answerIndex: 1,
    explanation: "Securities in good deliverable form are credited and sent to the transfer agent to be re-registered. Most holdings today are book-entry at DTC, so physical certificates are increasingly rare." },
  { id: "sie-trd-242", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer with a $30,000 income wants to invest their entire $8,000 emergency fund in a volatile growth fund. The representative should:",
    choices: ["Execute it as instructed", "Recommend a larger position", "Advise against it given liquidity needs", "Require a margin agreement"],
    answerIndex: 2,
    explanation: "An emergency fund exists to be available on short notice, so exposing all of it to volatility fails the liquidity constraint regardless of the client's risk appetite. The representative should surface that conflict rather than execute silently." },
  { id: "sie-trd-243", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE of a joint account with right of survivorship on the death of one owner?",
    choices: ["The estate takes it", "The account is closed", "It converts to tenants in common", "The survivor takes the deceased's interest"],
    answerIndex: 3,
    explanation: "JTWROS passes the interest to the survivor automatically, outside probate. TENANTS IN COMMON is the registration that routes the share to the deceased's estate under their will." },
  { id: "sie-trd-244", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Continuing education Regulatory Element is due:",
    choices: ["Annually by December 31", "Every two years", "Every three years", "On changing firms"],
    answerIndex: 0,
    explanation: "FINRA Rule 1240 requires it annually by December 31 for each registration category held, and missing the deadline makes the person CE inactive. The FIRM Element is separate and designed by the employer." },
  { id: "sie-mkt-158", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which describes a tender offer?",
    choices: ["A new issue sold to the public", "An offer to buy shares from existing holders", "A dividend paid in stock", "An exchange listing application"],
    answerIndex: 1,
    explanation: "A tender offer bids for outstanding shares, typically at a premium, and is common in takeovers. It is a secondary market event — the issuer receives nothing and no new securities are created." },
  { id: "sie-mkt-159", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which is TRUE of the money supply and interest rates?",
    choices: ["Increasing it raises rates", "They are unrelated", "Increasing the money supply generally lowers rates", "Only Congress affects both"],
    answerIndex: 2,
    explanation: "More money available to lend pushes the cost of borrowing down, which is why Fed purchases of securities are expansionary. Congress controls FISCAL policy — taxing and spending — not the money supply." },
  { id: "sie-reg-148", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which body writes rules for municipal securities dealers?",
    choices: ["FINRA", "The SEC", "NASAA", "The MSRB"],
    answerIndex: 3,
    explanation: "The MSRB writes them but has NO enforcement power — FINRA enforces against broker-dealers, bank regulators against bank dealers, and the SEC over all of them. That split is unusual and reliably tested." },
  { id: "sie-reg-149", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "A firm's written supervisory procedures must:",
    choices: ["Be reasonably designed to achieve compliance", "Guarantee no violations occur", "Be approved by the SEC annually", "Cover only registered representatives"],
    answerIndex: 0,
    explanation: "The standard is reasonable design, not perfection — no procedure can guarantee compliance. They must cover all supervised activities and be reviewed and updated as the business and the rules change." },
  { id: "sie-prd-371", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "A 6% bond with 10 years remaining trades at 92. Which statement is correct?",
    choices: ["YTM is below 6% because of the discount", "YTM exceeds 6% because the bond pulls up to par", "Current yield equals 6%", "Nominal yield rises as the price falls"],
    answerIndex: 1,
    explanation: "At a discount the buyer collects the coupon AND gains as price rises toward par, so YTM exceeds current yield, which exceeds the 6% nominal. Nominal is fixed at issuance and never moves with price." },
  { id: "sie-prd-372", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "Two bonds are identical except one is callable. The callable bond will generally offer:",
    choices: ["A lower yield because of the added feature", "The same yield", "A higher yield to compensate for the call risk", "No yield difference until rates change"],
    answerIndex: 2,
    explanation: "The call belongs to the ISSUER and hurts the holder precisely when rates fall, so buyers demand extra yield to accept it. The gap between a callable bond's Z-spread and its option-adjusted spread is that compensation made explicit." },
  { id: "sie-prd-373", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor holds a 3% muni and is in the 12% bracket. Compared with a 3.6% corporate, the muni's taxable-equivalent yield is:",
    choices: ["About 3.41%, so the muni is better", "About 2.64%, so the corporate is better", "Equal to the corporate", "About 3.41%, so the corporate is better"],
    answerIndex: 3,
    explanation: "TEY = 3.0% / (1 - 0.12) = 3.41%, which falls short of the corporate's 3.6%. In a LOW bracket the exemption is worth little, so the muni's lower pre-tax yield is not recovered — the same comparison flips in a high bracket." },
  { id: "sie-prd-374", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "A client wants inflation protection and current income. The weakest fit is:",
    choices: ["A 30-year zero-coupon Treasury", "TIPS", "A dividend-growth equity fund", "A short-duration bond ladder"],
    answerIndex: 0,
    explanation: "A zero pays no current income at all, and its fixed nominal payout 30 years out is maximally exposed to inflation — it fails both objectives simultaneously. TIPS index principal, dividend growers raise payouts, and short ladders reprice quickly." },
  { id: "sie-prd-375", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor writes an uncovered put with a $40 strike for $3. Their maximum loss is:",
    choices: ["$4,000", "$3,700", "$300", "Unlimited"],
    answerIndex: 1,
    explanation: "A put writer must buy at $40 however far the stock falls; the floor is zero, so the worst case is $40 minus the $3 premium = $37 per share, or $3,700 per contract. Unlimited loss belongs only to the naked CALL writer, since a stock has no ceiling." },
  { id: "sie-prd-376", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "Which pair of risks moves in opposite directions as rates change?",
    choices: ["Credit and liquidity risk", "Market and business risk", "Prepayment and extension risk", "Political and currency risk"],
    answerIndex: 2,
    explanation: "Falling rates trigger refinancing and early principal return (prepayment); rising rates slow it and lengthen the security's life (extension). They are two faces of the same uncertainty about timing, and both are unique to mortgage securities." },
  { id: "sie-prd-377", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "A fund reports a large capital gain distribution in a year its NAV fell. This can happen because:",
    choices: ["Distributions always equal NAV change", "The fund borrowed to pay it", "It indicates fraud", "The manager realised gains on appreciated holdings sold during the year"],
    answerIndex: 3,
    explanation: "Realised gains on individual sales are distributed even if the portfolio overall declined — which is why an investor can owe tax on a fund that lost money. That mismatch is a common and legitimate source of complaints." },
  { id: "sie-trd-245", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer buys 200 shares at $60 in a margin account, then the stock falls to $38. Equity is:",
    choices: ["$1,600", "$6,000", "$7,600", "$12,000"],
    answerIndex: 0,
    explanation: "Purchase is $12,000; Reg T's 50% deposit is $6,000 and the debit is $6,000 fixed. At $38 the market value is $7,600, so equity = $7,600 - $6,000 = $1,600. Maintenance at 25% of $7,600 is $1,900, so equity is BELOW it and a call is issued." },
  { id: "sie-trd-246", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "For that position, the maintenance call arises because equity fell below:",
    choices: ["50% of market value", "25% of market value", "30% of market value", "The original deposit"],
    answerIndex: 1,
    explanation: "FINRA's long maintenance minimum is 25% of current market value — here $1,900 against $1,600 of equity. The 50% figure is Reg T's INITIAL requirement, and 30% applies to short positions where losses are unbounded." },
  { id: "sie-trd-247", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A representative recommends switching a client from one mutual fund family to another with a similar objective, incurring a new front-end load. This is:",
    choices: ["Always permitted", "Required annually for diversification", "Potentially an unsuitable switch requiring justification", "Only a concern in retirement accounts"],
    answerIndex: 2,
    explanation: "Switching between comparable funds imposes a fresh sales charge with no evident benefit, which is the classic churning-adjacent violation in packaged products. It requires documented justification that the new fund genuinely serves the client better." },
  { id: "sie-trd-248", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A firm receives a customer's written complaint alleging unsuitable recommendations. The correct sequence is:",
    choices: ["Report to the SEC within 24 hours", "Refer immediately to arbitration", "Close the account", "Record it, investigate, retain the file, report quarterly"],
    answerIndex: 3,
    explanation: "Written complaints are logged, investigated under the firm's procedures, retained, and reported to FINRA quarterly. Arbitration is available but is the customer's election, and there is no 24-hour SEC reporting duty for an ordinary complaint." },
  { id: "sie-trd-249", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "An employee of a broker-dealer wants to buy shares in a hot IPO at the offering price. Under Rule 5130 they:",
    choices: ["May not, as a restricted person", "May, with firm approval", "May, up to 100 shares", "May only in a retirement account"],
    answerIndex: 0,
    explanation: "Member firm employees are restricted persons and cannot buy new EQUITY issues at the offering price, so first-day gains flow to public customers. No approval, size limit or account type creates an exception — though new DEBT offerings fall outside the rule." },
  { id: "sie-mkt-160", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 3,
    stem: "During a period of rising inflation and rising rates, which position suffers most?",
    choices: ["A floating-rate note", "A 30-year fixed-coupon bond", "A short-term T-bill", "A TIPS holding"],
    answerIndex: 1,
    explanation: "Long maturity plus a fixed coupon is maximally exposed on both counts: the fixed payment loses purchasing power and the long duration magnifies the price decline. Floaters reset, bills mature quickly, and TIPS index principal." },
  { id: "sie-mkt-161", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 3,
    stem: "The Fed sells government securities in the open market. The likely effect is:",
    choices: ["Reserves rise, rates fall", "No effect on rates", "Reserves fall, rates rise", "Only long-term rates fall"],
    answerIndex: 2,
    explanation: "Selling drains reserves from the banking system, tightening credit and pushing rates up — a contractionary action. BUYING securities does the reverse, which is the Fed's principal expansionary tool." },
  { id: "sie-mkt-162", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 3,
    stem: "A candidate sees an inverted yield curve and rising unemployment. The economy is most likely:",
    choices: ["In early expansion", "At a trough", "Experiencing a supply shock only", "Entering or in a contraction"],
    answerIndex: 3,
    explanation: "Inversion has historically preceded recessions, and rising unemployment is a LAGGING confirmation that a downturn is under way. A trough is the bottom that precedes recovery, and early expansion would show falling unemployment." },
  { id: "sie-prd-378", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "A closed-end fund persistently trades at a 15% discount to NAV. This is possible because:",
    choices: ["It lacks a creation and redemption mechanism", "The SEC caps its price", "Its holdings are illiquid by law", "It pays no distributions"],
    answerIndex: 0,
    explanation: "Without authorized participants arbitraging the gap, a closed-end fund's price is set purely by supply and demand and can drift far from NAV for long periods. ETFs avoid this precisely because creation and redemption closes the gap." },
  { id: "sie-prd-379", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor holds a variable annuity and the separate account falls 20% after annuitization. Their monthly payment:",
    choices: ["Stays fixed, because unit count is fixed", "Falls, because annuity unit VALUE varies", "Rises to offset the loss", "Is guaranteed by the insurer"],
    answerIndex: 1,
    explanation: "At annuitization the NUMBER of annuity units is fixed for life, but their VALUE continues to track the separate account — so payments move with performance. A guaranteed payment would make it a FIXED annuity." },
  { id: "sie-prd-380", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "Which best explains why unsystematic risk carries no risk premium?",
    choices: ["Regulators prohibit charging for it", "It rarely materialises", "It can be eliminated at no cost through diversification", "It is offset by systematic risk"],
    answerIndex: 2,
    explanation: "Investors cannot be paid for bearing a risk they could remove for free, so the market prices only what diversification cannot eliminate. That single principle explains why concentration is imprudent rather than merely risky." },
  { id: "sie-prd-381", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Preferred dividends are paid before:",
    choices: ["Bond interest", "Secured debt", "Taxes", "Common dividends"],
    answerIndex: 3,
    explanation: "Preferred ranks ahead of common for dividends and in liquidation, but behind ALL debt. Bondholders are creditors and are paid before any equity." },
  { id: "sie-prd-382", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A UIT's portfolio is:",
    choices: ["Fixed", "Actively traded", "Rebalanced monthly", "Manager-selected weekly"],
    answerIndex: 0,
    explanation: "A unit investment trust buys a portfolio, holds it unchanged, and terminates on a preset date. It has no board and no adviser, which is what distinguishes it from a managed fund." },
  { id: "sie-prd-383", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is the safest from credit risk?",
    choices: ["Corporate bonds", "Treasury bonds", "Municipal bonds", "High-yield bonds"],
    answerIndex: 1,
    explanation: "Treasuries carry the full faith and credit of the United States and are treated as free of credit risk. They still carry interest rate risk, which is what actually moves their prices." },
  { id: "sie-prd-384", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A zero-coupon bond pays interest:",
    choices: ["Semiannually", "Quarterly", "At maturity", "Monthly"],
    answerIndex: 2,
    explanation: "A zero pays nothing until maturity — it is bought at a discount and redeemed at par. Holders still owe annual tax on the phantom accretion, which is why zeros suit tax-deferred accounts." },
  { id: "sie-prd-385", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which option position is bullish?",
    choices: ["Long put", "Short call", "Protective put", "Long call"],
    answerIndex: 3,
    explanation: "A long call profits as the stock rises. Long puts and short calls are bearish or neutral, and a protective put is a hedge on stock already owned." },
  { id: "sie-prd-386", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Diversification reduces:",
    choices: ["Unsystematic risk", "Systematic risk", "Market risk", "Inflation risk"],
    answerIndex: 0,
    explanation: "Only company-specific risk offsets across holdings. Market and inflation risk are systematic — they move everything at once, which is exactly why they carry a risk premium." },
  { id: "sie-prd-387", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "An ETF trades:",
    choices: ["Once daily", "Intraday", "Weekly", "At NAV only"],
    answerIndex: 1,
    explanation: "ETFs trade on an exchange throughout the session, so the price is known at execution. Open-end mutual funds use forward pricing and fill at the next computed NAV." },
  { id: "sie-prd-388", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is an exempt security?",
    choices: ["An IPO of common stock", "A corporate debenture", "A Treasury bond", "A new ETF"],
    answerIndex: 2,
    explanation: "Government and municipal securities are exempt SECURITIES under the 1933 Act — exempt for what they are. A private placement is an exempt TRANSACTION, exempt for how it is sold." },
  { id: "sie-trd-250", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Choosing a market order over a limit order trades away control of:",
    choices: ["Execution", "Timing", "Quantity", "Price"],
    answerIndex: 3,
    explanation: "A market order buys certainty of EXECUTION by surrendering control of price - it fills at whatever is available. A limit order makes the opposite trade. Quantity and timing are specified by the customer either way." },
  { id: "sie-trd-251", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Churning is measured against the customer's:",
    choices: ["Objectives", "Account size only", "Trade count", "Zip code"],
    answerIndex: 0,
    explanation: "It is judged against stated objectives and resources, not any fixed number of trades — the same activity can be fine for an active trader and abusive for a retiree seeking income." },
  { id: "sie-trd-252", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "UTMA assets belong to:",
    choices: ["The custodian", "The minor", "The donor", "The firm"],
    answerIndex: 1,
    explanation: "The gift is irrevocable and the assets are the minor's from the moment of transfer. The custodian only manages them, and control passes to the minor outright at majority." },
  { id: "sie-trd-253", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is prohibited?",
    choices: ["Explaining risks", "Disclosing conflicts", "Guaranteeing against loss", "Gathering a profile"],
    answerIndex: 2,
    explanation: "Guaranteeing a customer against loss misrepresents the nature of investing and is prohibited outright — no disclosure cures it. The other three are exactly the job." },
  { id: "sie-trd-254", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A firm files a SAR. The customer may be told:",
    choices: ["After filing", "On request", "At year end", "Never"],
    answerIndex: 3,
    explanation: "Anyone who receives material nonpublic information and trades on it can be liable, and the tipper can be too. There is no dollar threshold and no insider-title requirement." },
  { id: "sie-trd-255", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A SAR is disclosed to the customer:",
    choices: ["Never", "On request", "After 30 days", "At account closing"],
    answerIndex: 0,
    explanation: "Telling a customer a suspicious activity report was filed is 'tipping off' and is itself a violation, because it defeats the report's purpose. Contrast the CTR, a routine mechanical cash filing." },
  { id: "sie-mkt-163", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "FINRA is overseen by:",
    choices: ["Congress", "The SEC", "The Fed", "The FDIC"],
    answerIndex: 1,
    explanation: "FINRA is a self-regulatory organisation whose rules require SEC approval. It is industry-funded rather than governmental, which is what 'self' regulatory means." },
  { id: "sie-mkt-164", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "The 1934 Act created:",
    choices: ["FINRA", "SIPC", "The SEC", "The MSRB"],
    answerIndex: 2,
    explanation: "The Securities Exchange Act of 1934 created the SEC and governs secondary trading. SIPC came from the 1970 Act, FINRA from a 2007 consolidation, and the MSRB from 1975." },
  { id: "sie-mkt-165", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Proceeds of an IPO go to:",
    choices: ["The selling shareholder", "The exchange", "The underwriter", "The issuer"],
    answerIndex: 3,
    explanation: "An IPO is a primary transaction — newly created shares, proceeds to the issuer to fund the business. In the SECONDARY market the selling investor receives the money instead." },
  { id: "sie-mkt-166", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Building permits are which indicator?",
    choices: ["Leading", "Lagging", "Coincident", "Neutral"],
    answerIndex: 0,
    explanation: "Permits are issued before construction begins, so they anticipate activity. Unemployment and corporate profits LAG; industrial production is coincident." },
  { id: "sie-trd-256", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A firm holding a customer's securities must keep them:",
    choices: ["Commingled", "Segregated", "In the firm's name", "Unrecorded"],
    answerIndex: 1,
    explanation: "Customer property must remain identifiable and separate from firm assets so it is protected if the firm fails. Mixing the two is COMMINGLING, one of the most serious violations in the rulebook." },
  { id: "sie-trd-257", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which requires an options principal's approval?",
    choices: ["A cash account", "A UTMA account", "An options account", "A joint account"],
    answerIndex: 2,
    explanation: "Options accounts require approval by a registered options principal specifically, plus delivery of the options disclosure document at or before approval. Other account types need only a general principal." },
  { id: "sie-trd-258", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer wants securities registered in their own name rather than the firm's. This is:",
    choices: ["Street name", "Book entry at the firm", "Prohibited", "Registered form, delivered to the customer"],
    answerIndex: 3,
    explanation: "Holding in the customer's own name is permitted; STREET NAME registers them in the firm's name for easier transfer and margin use. Most positions today are book-entry at DTC regardless of the name." },
  { id: "sie-trd-259", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Why do most customers hold securities in street name?",
    choices: ["It simplifies transfer and permits margin", "It avoids all taxes", "It guarantees the position", "It removes market risk"],
    answerIndex: 0,
    explanation: "Street name lets the firm transfer and pledge positions without moving certificates, which is what makes margin lending and fast settlement practical. It changes nothing about taxes, guarantees or market risk." },
  { id: "sie-trd-260", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer's account is frozen for 90 days. During that period they must:",
    choices: ["Close the account", "Pay in advance of any purchase", "Trade only on margin", "Use a different firm"],
    answerIndex: 1,
    explanation: "A freeze follows a Reg T payment failure and requires cash in the account before an order is entered. It lasts 90 days and is a control against repeated non-payment rather than a penalty." },
  { id: "sie-trd-261", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which best describes hypothecation?",
    choices: ["Lending securities to short sellers", "Selling customer securities", "Pledging customer securities as loan collateral", "Transferring an account"],
    answerIndex: 2,
    explanation: "Hypothecation pledges the customer's securities to finance the margin loan and is covered by the margin agreement. LENDING them out requires the separate and optional loan consent." },
  { id: "sie-prd-389", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which best describes a balanced fund?",
    choices: ["It holds only investment-grade bonds", "It matches an index exactly", "It uses leverage", "It holds both stocks and bonds"],
    answerIndex: 3,
    explanation: "A balanced fund blends equity and fixed income in stated proportions, moderating volatility relative to pure equity. Index matching describes an index fund; leverage describes a leveraged product." },
  { id: "sie-prd-390", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which describes a growth fund's objective?",
    choices: ["Capital appreciation over current income", "Maximum current income", "Principal preservation", "Tax-free income"],
    answerIndex: 0,
    explanation: "Growth funds hold companies reinvesting earnings rather than paying them out, so returns come from appreciation. Income, preservation and tax-exemption each point to a different fund category." },
  { id: "sie-prd-391", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor buying a bond between coupon dates pays:",
    choices: ["The price only", "The price plus accrued interest", "Accrued interest only", "A reduced price"],
    answerIndex: 1,
    explanation: "The seller earned interest since the last coupon but will not receive it, so the buyer compensates them and is made whole at the next payment. Zeros and defaulted bonds trade FLAT, without accrued interest." },
  { id: "sie-prd-392", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is TRUE about a bond quoted 'and interest'?",
    choices: ["The price includes accrued interest", "No interest has accrued", "Accrued interest is added to the price", "It is in default"],
    answerIndex: 2,
    explanation: "'And interest' means accrued interest is added on top of the quoted price at settlement. A bond trading FLAT — a zero, an income bond, or one in default — has no accrued interest to add." },
  { id: "sie-prd-393", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which pays the highest yield for a given maturity, all else equal?",
    choices: ["An investment-grade corporate", "A Treasury", "An insured municipal", "A speculative-grade corporate"],
    answerIndex: 3,
    explanation: "Yield compensates for risk, and speculative grade carries the highest default probability of the four. Treasuries carry no credit risk and yield least; insurance on a municipal reduces its credit risk and its yield." },
  { id: "sie-prd-394", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor concerned about a single issuer defaulting should:",
    choices: ["Diversify across issuers", "Extend maturities", "Concentrate in one name", "Buy zero-coupon bonds"],
    answerIndex: 0,
    explanation: "Default risk is issuer-specific and therefore unsystematic, so spreading across issuers removes it. Extending maturity and buying zeros both increase interest rate exposure without touching credit risk." },
  { id: "sie-mkt-167", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which best describes the role of an underwriter?",
    choices: ["Making a secondary market", "Bringing a new issue to market", "Custodying assets", "Clearing trades"],
    answerIndex: 1,
    explanation: "Underwriters help an issuer structure, price and distribute a new issue — a primary market function. Market makers provide secondary liquidity; custodians safeguard assets; clearing corporations net obligations." },
  { id: "sie-mkt-168", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "A due diligence meeting occurs:",
    choices: ["After the effective date", "Before the registration is filed", "Near the end of the cooling-off period", "At the first anniversary"],
    answerIndex: 2,
    explanation: "It is held late in the cooling-off period so underwriters can verify the disclosure before effectiveness. Selling still may not occur until the registration is effective and the final prospectus exists." },
  { id: "sie-mkt-169", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which is TRUE of the effective date?",
    choices: ["The red herring is issued", "The registration is filed", "The syndicate forms", "Sales may begin"],
    answerIndex: 3,
    explanation: "Effectiveness is when selling becomes lawful and the final prospectus, with its price, must accompany or precede confirmation. Filing, the red herring and syndicate formation all precede it." },
  { id: "sie-reg-150", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which is TRUE about state regulation of securities?",
    choices: ["States retain antifraud authority over federal covered securities", "States may not regulate at all", "States set federal registration standards", "States approve all offerings"],
    answerIndex: 0,
    explanation: "NSMIA preempted state REGISTRATION for federal covered securities, but states kept antifraud jurisdiction and may require notice filings and fees. Preemption covers registration, never fraud." },
  { id: "sie-reg-151", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Blue sky laws refer to:",
    choices: ["Federal disclosure rules", "State securities laws", "Exchange listing standards", "Margin regulations"],
    answerIndex: 1,
    explanation: "Blue sky laws are the state-level securities statutes, named for offerings backed by nothing more than blue sky. They operate alongside federal law rather than replacing it." },
  { id: "sie-reg-152", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 3,
    stem: "A firm discovers a representative made an unsuitable recommendation. The firm should first:",
    choices: ["Immediately terminate the representative", "Refund the customer without inquiry", "Investigate and document under its supervisory procedures", "Report to the SEC within 24 hours"],
    answerIndex: 2,
    explanation: "Written supervisory procedures require investigation and documentation before any conclusion. Termination, remediation and any regulatory reporting follow from what the inquiry establishes — acting before is neither fair nor procedurally sound." },
  { id: "sie-prd-395", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Rights are issued to:",
    choices: ["Bondholders", "New investors", "Underwriters", "Existing shareholders"],
    answerIndex: 3,
    explanation: "A rights offering lets current holders maintain their proportional stake before new shares reach the public. That preemptive purpose is why rights are priced below market and expire quickly." },
  { id: "sie-prd-396", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is a packaged product?",
    choices: ["A mutual fund", "A common share", "A T-bond", "Commercial paper"],
    answerIndex: 0,
    explanation: "Packaged products pool investor money into a managed portfolio. Individual stocks, bonds and money market instruments are single securities bought directly." },
  { id: "sie-prd-397", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Interest rate risk affects which most?",
    choices: ["Money market funds", "Long-term bonds", "T-bills", "Floating-rate notes"],
    answerIndex: 1,
    explanation: "Price sensitivity rises with maturity, so a long bond moves most for a given rate change. Short instruments mature before much can happen, and floaters reset their coupon to match the market." },
  { id: "sie-prd-398", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is TRUE of a callable bond's yield to call?",
    choices: ["It always exceeds YTM", "It ignores the call price", "On a premium bond it is typically the lowest yield", "It applies only at maturity"],
    answerIndex: 2,
    explanation: "On a premium bond the loss of premium is compressed into fewer years, so YTC falls below YTM. That is why callable premium bonds are quoted at yield to WORST — the lower of the two." },
  { id: "sie-prd-399", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A investor holding a 5% bond when new issues yield 7% will find their bond:",
    choices: ["Trading above par", "Trading at par", "Unaffected", "Trading below par"],
    answerIndex: 3,
    explanation: "A 5% coupon is uncompetitive against 7%, so the price must fall until the yield matches. That inverse relationship between rates and prices is the most heavily tested fact in fixed income." },
  { id: "sie-prd-400", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which pair is correctly matched?",
    choices: ["Ginnie Mae — explicit federal guarantee", "Fannie Mae — explicit federal guarantee", "Freddie Mac — Treasury obligation", "Ginnie Mae — private insurance"],
    answerIndex: 0,
    explanation: "Ginnie Mae is a government corporation whose pass-throughs carry explicit full faith and credit. Fannie Mae and Freddie Mac are GSEs with only assumed, implied support — a distinction the exam tests directly." },
  { id: "sie-trd-262", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is required before recommending a security?",
    choices: ["A margin agreement", "Knowing the customer's profile", "SEC approval", "A signed waiver"],
    answerIndex: 1,
    explanation: "Know your customer precedes any recommendation — financial situation, objectives, time horizon, liquidity needs and risk tolerance. Without those facts there is no basis on which to judge suitability." },
  { id: "sie-trd-263", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Front-running involves trading ahead of:",
    choices: ["An earnings release", "A dividend date", "A known customer order", "A market close"],
    answerIndex: 2,
    explanation: "Front-running exploits knowledge of a pending customer order whose size will likely move the price. Trading ahead of an earnings release on inside information is INSIDER trading, a different violation." },
  { id: "sie-trd-264", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE of Reg T payment timing?",
    choices: ["Payment is due on trade date", "Payment is due at settlement", "There is no deadline", "Payment is due two business days after settlement"],
    answerIndex: 3,
    explanation: "Settlement (T+1) is when securities and money move between firms; Reg T is when the CUSTOMER must pay their firm, two business days later. The exam pairs these deliberately." },
  { id: "sie-trd-265", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer's objective is speculation. Which is most consistent?",
    choices: ["Buying out-of-the-money options", "Buying Treasury bills", "Buying a money market fund", "Buying insured municipals"],
    answerIndex: 0,
    explanation: "Out-of-the-money options are high-risk, high-reward positions that expire worthless if wrong — squarely speculative. The other three are capital-preservation instruments." },
  { id: "sie-trd-266", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which record must be kept for the life of the firm?",
    choices: ["Order tickets", "Articles of incorporation", "Trade confirmations", "Daily blotters"],
    answerIndex: 1,
    explanation: "Formation documents such as articles of incorporation and partnership agreements are retained for the life of the firm. Most operational records run three years, with the first two easily accessible." },
  { id: "sie-trd-267", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer instructs 'sell my whole position whenever you think best this week.' This requires:",
    choices: ["Nothing, since the security is specified", "Only a principal's approval", "Written discretionary authority", "A margin agreement"],
    answerIndex: 2,
    explanation: "The verbal exception covers time and price for THAT DAY only. Extending the judgement across a week makes it ongoing discretion, which requires prior written authorization even though the security and quantity are specified." },
  { id: "sie-mkt-170", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Which is a secondary market venue?",
    choices: ["An IPO", "A private placement", "A rights offering", "An exchange"],
    answerIndex: 3,
    explanation: "Exchanges host trading in already-issued securities. IPOs, private placements and rights offerings all create or distribute new securities, making them primary transactions." },
  { id: "sie-mkt-171", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "A recession is conventionally defined as:",
    choices: ["Two consecutive quarters of falling real GDP", "One quarter of falling GDP", "Rising unemployment alone", "A stock market decline of 20%"],
    answerIndex: 0,
    explanation: "Two consecutive quarters of declining REAL GDP is the shorthand. Rising unemployment typically accompanies it but lags, and a 20% equity decline is a bear market, which is a different thing." },
  { id: "sie-mkt-172", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which Fed tool is used most frequently?",
    choices: ["The discount rate", "Open market operations", "Reserve requirements", "Margin requirements"],
    answerIndex: 1,
    explanation: "Open market operations run continuously and are the principal tool. Discount rate changes are largely signalling, reserve requirements are the bluntest instrument and change rarely, and margin rules serve a different purpose entirely." },
  { id: "sie-mkt-173", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Stock prices are considered which type of indicator?",
    choices: ["Lagging", "Coincident", "Leading", "Unrelated to the cycle"],
    answerIndex: 2,
    explanation: "Markets price expectations, so equities often turn before the economy does — which is why they frequently bottom while the news is still bad. Unemployment and corporate profits lag." },
  { id: "sie-reg-153", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 1,
    stem: "An exempt transaction is exempt because of:",
    choices: ["What the security is", "Who issued it", "Its maturity", "How the security is sold"],
    answerIndex: 3,
    explanation: "A private placement is exempt for the MANNER of sale — principally to accredited investors without a public offering. Treasuries and municipals are exempt SECURITIES, exempt for what they inherently are." },
  { id: "sie-reg-154", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which must accompany or precede a confirmation on a new issue?",
    choices: ["The final prospectus", "The red herring", "The registration statement", "A tombstone ad"],
    answerIndex: 0,
    explanation: "The final prospectus, containing the price set at pricing, is required at or before confirmation. The red herring circulates earlier with no price, and the registration statement is filed with the SEC rather than delivered to buyers." },
  { id: "sie-reg-155", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "A firm's AML program must include:",
    choices: ["Only customer identification", "A designated compliance officer and independent testing", "Annual SEC filings", "A minimum capital reserve"],
    answerIndex: 1,
    explanation: "The required pillars are a designated AML compliance officer, written policies, ongoing training, independent testing, and a customer identification program. CIP alone is one component, not the whole program." },
  { id: "sie-prd-401", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Bond interest is paid:",
    choices: ["Monthly", "Weekly", "Semiannually", "At issuance"],
    answerIndex: 2,
    explanation: "Most bonds pay semiannual coupons, which is why accrued interest is calculated between those dates. Zeros are the exception, paying everything at maturity." },
  { id: "sie-prd-402", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is a debt security?",
    choices: ["Common stock", "A warrant", "A right", "A debenture"],
    answerIndex: 3,
    explanation: "A debenture is unsecured corporate debt backed by the issuer's general credit. Stock is ownership; warrants and rights are instruments for buying stock." },
  { id: "sie-prd-403", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Cumulative preferred accrues:",
    choices: ["Missed dividends", "Extra votes", "Interest", "Principal"],
    answerIndex: 0,
    explanation: "Missed dividends build up as arrears and must all be paid before common receives anything. On NON-cumulative preferred a skipped dividend is simply gone." },
  { id: "sie-prd-404", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "An option contract covers:",
    choices: ["1 share", "100 shares", "10 shares", "1,000 shares"],
    answerIndex: 1,
    explanation: "The standard equity contract is 100 shares, so a premium quoted as 5 costs $500. Forgetting the multiplier is the most common arithmetic error in options questions." },
  { id: "sie-prd-405", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A T-note matures in:",
    choices: ["Under 1 year", "Over 10 years", "2 to 10 years", "30 years only"],
    answerIndex: 2,
    explanation: "Notes run 2 to 10 years with semiannual coupons. Bills are one year or less and pay no coupon; bonds run beyond 10 years." },
  { id: "sie-prd-406", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "REIT distributions are primarily:",
    choices: ["Capital gains", "Tax-free", "Guaranteed", "Income"],
    answerIndex: 3,
    explanation: "A REIT must distribute at least 90% of taxable income, which is why it is held for income. It passes through income but NOT losses — the distinction from a DPP." },
  { id: "sie-prd-407", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is systematic risk?",
    choices: ["Inflation risk", "Business risk", "Credit risk", "Liquidity risk"],
    answerIndex: 0,
    explanation: "Inflation erodes all fixed payments at once and cannot be diversified away. Business, credit and liquidity risk are issuer-specific and offset across a portfolio." },
  { id: "sie-prd-408", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A mutual fund is redeemed at:",
    choices: ["Market price", "NAV", "Par", "Cost"],
    answerIndex: 1,
    explanation: "Open-end funds redeem at the next computed NAV, less any contingent deferred sales charge. Only exchange-traded products have a market price that can diverge from NAV." },
  { id: "sie-trd-268", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A limit order to sell executes at:",
    choices: ["The limit or lower", "Any price", "The limit or higher", "The open"],
    answerIndex: 2,
    explanation: "A sell limit sets a FLOOR — that price or better, and better means higher. A buy limit sets a ceiling. Either way the order may never fill." },
  { id: "sie-trd-269", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Discretionary orders must be:",
    choices: ["Executed at the open", "Limited to $5,000", "Approved by FINRA", "Marked and reviewed"],
    answerIndex: 3,
    explanation: "Every discretionary order is identified as such and reviewed, which is how the firm supervises an authority that bypasses the customer on each trade." },
  { id: "sie-trd-270", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is the AML placement stage?",
    choices: ["Introducing illicit cash into the system", "Moving funds to obscure origin", "Returning funds as legitimate", "Reporting to FinCEN"],
    answerIndex: 0,
    explanation: "Placement is the entry point, which is why customer identification catches it. Layering obscures the trail and integration returns the money looking clean." },
  { id: "sie-trd-271", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Selling away means conducting business:",
    choices: ["On margin", "Outside the firm", "After hours", "In a cash account"],
    answerIndex: 1,
    explanation: "Securities business away from the employing firm without written notice and approval defeats supervision entirely. Where compensation is involved, firm approval is required, not just notice." },
  { id: "sie-trd-272", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which account cannot use margin?",
    choices: ["Individual", "Joint", "UTMA", "Corporate"],
    answerIndex: 2,
    explanation: "Custodial accounts are barred from margin and speculation because the standard is prudent management of a minor's property. The other three may open margin accounts with a signed agreement." },
  { id: "sie-trd-273", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Statements are sent at minimum:",
    choices: ["Monthly", "Annually", "Weekly", "Quarterly"],
    answerIndex: 3,
    explanation: "At least quarterly, and monthly in any month with activity. Confirmations are separate and due at or before completion of each trade." },
  { id: "sie-mkt-174", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "A dealer earns:",
    choices: ["A markup", "A commission", "A fee", "A concession"],
    answerIndex: 0,
    explanation: "Dealers act as principal from inventory and earn the markup embedded in the price. Brokers act as agent and charge a commission — the confirmation must disclose which." },
  { id: "sie-mkt-175", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "The 1933 Act governs:",
    choices: ["Exchanges", "New issues", "Advisers", "Margin"],
    answerIndex: 1,
    explanation: "The 1933 Act is the 'paper act' — registration and prospectus delivery for new issues. The 1934 Act is the 'people act', covering exchanges, broker-dealers and secondary trading." },
  { id: "sie-mkt-176", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "SIPC protects against:",
    choices: ["Market losses", "Issuer default", "Broker-dealer failure", "Inflation"],
    answerIndex: 2,
    explanation: "SIPC restores customer assets when the FIRM fails, up to $500,000 with a $250,000 cash sublimit. It never insures investment performance." },
  { id: "sie-mkt-177", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Which lags the business cycle?",
    choices: ["Building permits", "Stock prices", "New orders", "Unemployment"],
    answerIndex: 3,
    explanation: "Firms cut and hire only after conditions have clearly changed, so unemployment confirms a turn rather than predicting one. The other three all lead." },
  { id: "sie-mkt-178", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Price discovery results from:",
    choices: ["Many buyers and sellers", "An SEC ruling", "Issuer announcements", "Dealer agreement"],
    answerIndex: 0,
    explanation: "No one sets the price — it emerges from participants acting on their own information. Dealers agreeing on a quote would be collusion, not discovery." },
  { id: "sie-prd-410", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which term describes a bond priced below par?",
    choices: ["Premium", "Discount", "Parity", "Basis"],
    answerIndex: 1,
    explanation: "Below par is a discount, and every forward yield then exceeds the coupon: nominal < current < YTM. Above par is a premium, where the entire ordering flips." },
  { id: "sie-prd-411", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor seeking monthly income from real estate without illiquidity should choose:",
    choices: ["A real estate DPP", "Raw land", "A listed REIT", "A private fund"],
    answerIndex: 2,
    explanation: "Listed REITs trade on an exchange and distribute at least 90% of taxable income. DPPs, raw land and private funds are all illiquid by design with no meaningful secondary market." },
  { id: "sie-prd-412", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which best describes an equity REIT?",
    choices: ["It holds mortgage debt", "It trades futures", "It is a bond fund", "It owns and operates properties"],
    answerIndex: 3,
    explanation: "Equity REITs own real property and earn rents. MORTGAGE REITs hold real-estate debt and earn interest, and hybrids do both — the three-way split is the tested distinction." },
  { id: "sie-prd-413", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A fund's expense ratio represents:",
    choices: ["Annual operating costs as a share of assets", "The front-end load", "The redemption fee", "The manager's bonus"],
    answerIndex: 0,
    explanation: "The expense ratio is the recurring annual drag on returns, deducted from assets. It is separate from any sales charge and compounds against the investor over time." },
  { id: "sie-prd-414", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which security would an investor buy expecting a stock to FALL?",
    choices: ["A call option", "A put option", "A warrant", "A right"],
    answerIndex: 1,
    explanation: "A put gains value as the stock declines, breaking even at strike minus premium. Calls, warrants and rights all profit from rising prices." },
  { id: "sie-prd-415", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is TRUE of a stock dividend?",
    choices: ["It is taxed as ordinary income", "It increases total basis", "It is not taxable at receipt", "It reduces share count"],
    answerIndex: 2,
    explanation: "No cash changes hands, so nothing is taxable until the shares are sold. Total basis is unchanged while basis PER SHARE falls, since it now spreads across more shares." },
  { id: "sie-prd-416", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "An investor buys a bond at 105 and holds to maturity. Their total return will be:",
    choices: ["Above the coupon rate", "Equal to the coupon rate", "Negative", "Below the coupon rate, due to the premium loss"],
    answerIndex: 3,
    explanation: "The premium paid above par is not returned — only $1,000 comes back — so that loss drags total return below the coupon. This is exactly why YTM falls below nominal on a premium bond." },
  { id: "sie-prd-417", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "Which investor faces the greatest reinvestment risk?",
    choices: ["A holder of high-coupon callable bonds", "A holder of zero-coupon bonds", "A common stockholder", "A money market investor"],
    answerIndex: 0,
    explanation: "Large frequent coupons plus a likely early call means substantial cash returning at unpredictable times, all of which must be redeployed at whatever rates then prevail. A zero returns nothing until maturity and so carries essentially none." },
  { id: "sie-trd-275", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is required in every customer account record?",
    choices: ["A margin balance", "Investment objectives", "An options approval", "A power of attorney"],
    answerIndex: 1,
    explanation: "Objectives are part of the suitability profile required for every account. Margin balances, options approval and third-party authority attach only to specific arrangements." },
  { id: "sie-trd-276", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "A customer holds securities in street name. The registered owner is:",
    choices: ["The customer", "The transfer agent", "The broker-dealer", "DTC's nominee only"],
    answerIndex: 2,
    explanation: "Street name registers the position in the firm's name for easy transfer and margin use, while the customer remains the BENEFICIAL owner and receives all economic rights. Most positions ultimately sit in book-entry form at DTC." },
  { id: "sie-trd-277", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which describes a wash sale for tax purposes?",
    choices: ["Selling at a gain", "Buying on margin", "Trading after hours", "Repurchasing a substantially identical security within 30 days"],
    answerIndex: 3,
    explanation: "The wash sale rule disallows the loss if a substantially identical security is bought within 30 days BEFORE or after the sale — a 61-day window, not 30. It applies only to losses." },
  { id: "sie-trd-278", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Capital losses may offset ordinary income up to:",
    choices: ["$3,000 per year", "$1,000 per year", "Unlimited", "$10,000 per year"],
    answerIndex: 0,
    explanation: "Losses first offset capital gains without limit; beyond that, $3,000 per year may reduce ordinary income and the remainder carries forward indefinitely." },
  { id: "sie-trd-279", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A representative accepts an order from a customer's spouse who is not on the account. This is:",
    choices: ["Permitted for spouses", "Unauthorized without a power of attorney", "Permitted with verbal confirmation", "Permitted if the trade is suitable"],
    answerIndex: 1,
    explanation: "Only the account owner or someone holding written third-party authority may place orders. Marriage confers nothing over a separately titled account, and suitability is irrelevant when the instruction came from someone with no authority." },
  { id: "sie-trd-280", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A customer requests that confirmations be sent to a third party rather than to them. The firm should:",
    choices: ["Comply as instructed", "Refuse all third-party mail", "Send duplicates to the third party but originals to the customer", "Send only to the third party"],
    answerIndex: 2,
    explanation: "The customer must continue to receive their own confirmations and statements; duplicates to a third party are permitted with written instruction. Diverting the originals away from the owner is a recognised concealment red flag." },
  { id: "sie-mkt-179", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which is TRUE of an exempt security?",
    choices: ["It is free of market risk", "It carries a federal guarantee", "It cannot lose value", "It needs no 1933 Act registration"],
    answerIndex: 3,
    explanation: "Exempt means exempt from REGISTRATION, nothing more. A municipal bond can still default and still fluctuates in price — exemption addresses paperwork, not risk." },
  { id: "sie-mkt-180", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "An investor's order is routed to a venue paying the firm for order flow. The firm must still:",
    choices: ["Seek best execution", "Guarantee the best price", "Route to the primary exchange", "Disclose each trade to FINRA"],
    answerIndex: 0,
    explanation: "Best execution is a diligence standard weighing price, speed, and likelihood of execution, and it survives any payment arrangement. Payment for order flow is permitted but must be disclosed because of the conflict it creates." },
  { id: "sie-mkt-181", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 3,
    stem: "Why can a market maker widen its spread during volatility?",
    choices: ["Regulators require it", "Inventory risk rises", "Commissions increase", "Settlement slows"],
    answerIndex: 1,
    explanation: "A wider spread compensates for the greater chance that a position moves against the dealer before it can be offloaded. Nothing requires the widening — it is a pricing response to risk." },
  { id: "sie-mkt-182", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which best describes the fourth market?",
    choices: ["Retail trading on an exchange", "New issues sold privately", "Institution-to-institution trading off-exchange", "Foreign currency dealing"],
    answerIndex: 2,
    explanation: "Fourth market trades run directly between institutions, bypassing exchanges so a large holder avoids signalling and moving the price. The THIRD market is listed stock traded over the counter." },
  { id: "sie-trd-281", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is the default order duration?",
    choices: ["GTC", "Week", "Month", "Day"],
    answerIndex: 3,
    explanation: "An order with no stated duration expires at the close. Carrying it forward requires marking it good til cancelled." },
  { id: "sie-trd-282", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A stop order becomes what when triggered?",
    choices: ["A market order", "A limit order", "A GTC order", "Cancelled"],
    answerIndex: 0,
    explanation: "A plain stop converts to a market order, guaranteeing a sale but not a price — which is why a gap can fill it far below the stop. A stop-LIMIT converts to a limit order instead." },
  { id: "sie-trd-283", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is a systematic AML control?",
    choices: ["Daily blotters", "Independent testing", "Margin calls", "Trade confirmations"],
    answerIndex: 1,
    explanation: "The AML pillars are a designated compliance officer, written policies, ongoing training, independent testing, and a customer identification program. The others are ordinary operational records." },
  { id: "sie-trd-284", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A power of attorney granting only trading authority is:",
    choices: ["Full", "Durable", "Limited", "Springing"],
    answerIndex: 2,
    explanation: "A limited power permits trading only; a FULL power also allows withdrawing cash and securities. Either must be in writing." },
  { id: "sie-trd-285", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE of a trade confirmation?",
    choices: ["It replaces the account statement", "It is optional for small trades", "It is sent annually", "It discloses the firm's capacity"],
    answerIndex: 3,
    explanation: "Capacity disclosure — agent or principal — is required because the compensation and the conflict differ entirely between them. Confirmations are per-trade; statements are quarterly." },
  { id: "sie-trd-286", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which requires the firm to freeze an account for 90 days?",
    choices: ["Failure to pay under Reg T", "A single loss", "A customer complaint", "High volume"],
    answerIndex: 0,
    explanation: "Non-payment triggers a sell-out and a 90-day freeze during which cash must be in the account before an order is entered. It is a control against repeated non-payment rather than a penalty." },
  { id: "sie-trd-287", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "An employee's outside brokerage account requires:",
    choices: ["SEC registration", "Notice to the employing firm", "FINRA pre-approval", "Nothing"],
    answerIndex: 1,
    explanation: "Employees disclose outside accounts so the firm can supervise personal trading and detect front-running. The executing firm typically must send duplicate confirmations to the employer." },
  { id: "sie-trd-288", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is the maintenance requirement for a SHORT position?",
    choices: ["25%", "50%", "30%", "20%"],
    answerIndex: 2,
    explanation: "Short maintenance is 30% of market value, higher than the 25% long requirement because short losses are theoretically unbounded — a stock has no ceiling." },
  { id: "sie-trd-289", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 3,
    stem: "A client aged 72 with a traditional IRA has taken no distribution this year. They face:",
    choices: ["No consequence", "A 10% early withdrawal penalty", "Automatic account closure", "A penalty on the shortfall"],
    answerIndex: 3,
    explanation: "Required minimum distributions begin at 73 under current law, so at 72 nothing is yet due — but once the age is reached, failing to take the RMD triggers a penalty on the amount not withdrawn. The 10% penalty applies to EARLY withdrawals before 59½, the opposite situation." },
  { id: "sie-trd-290", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which best describes a fiduciary's standard?",
    choices: ["Prudent management of another's property", "Maximum return at any risk", "Following customer instructions only", "Matching an index"],
    answerIndex: 0,
    explanation: "Trustees, custodians and guardians manage assets belonging to someone else, which is why speculation and margin are typically restricted in those accounts." },
  { id: "sie-prd-420", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is the safest money market instrument?",
    choices: ["Commercial paper", "A T-bill", "A banker's acceptance", "A negotiable CD"],
    answerIndex: 1,
    explanation: "T-bills carry the full faith and credit of the United States. Commercial paper is unsecured corporate debt, BAs carry a bank guarantee, and jumbo CDs are largely uninsured above $250,000." },
  { id: "sie-prd-421", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "An accumulation unit becomes an annuity unit at:",
    choices: ["Purchase", "Death", "Annuitization", "Age 59½"],
    answerIndex: 2,
    explanation: "At annuitization the contract switches from saving to paying income, and the NUMBER of annuity units is then fixed for life while their value keeps varying." },
  { id: "sie-prd-422", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which describes a mortgage REIT's income source?",
    choices: ["Rents from properties", "Option premiums", "Currency gains", "Interest on real-estate debt"],
    answerIndex: 3,
    explanation: "Mortgage REITs hold real-estate loans and earn interest. EQUITY REITs own properties and earn rents — the distinction the exam tests." },
  { id: "sie-prd-423", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which product has NO secondary market in most cases?",
    choices: ["A direct participation program", "A listed REIT", "An ETF", "A Treasury note"],
    answerIndex: 0,
    explanation: "DPP interests are illiquid by design, which is why liquidity needs rule them out regardless of expected return. The other three all trade readily." },
  { id: "sie-prd-424", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor holding TIPS during deflation would see principal:",
    choices: ["Rise", "Adjust downward, with principal floored at par at maturity", "Stay fixed", "Convert to cash"],
    answerIndex: 1,
    explanation: "TIPS principal indexes both ways, so it falls in deflation — but at maturity the investor receives no less than the original par, which is the floor that makes them a hedge rather than a gamble." },
  { id: "sie-prd-425", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which best describes a convertible bond's advantage to the issuer?",
    choices: ["Higher interest expense", "No repayment obligation", "A lower coupon than straight debt", "Guaranteed conversion"],
    answerIndex: 2,
    explanation: "The conversion privilege has value to the buyer, so investors accept a lower coupon — cheaper financing for the issuer. Conversion is the holder's option, never guaranteed." },
  { id: "sie-prd-426", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 3,
    stem: "A bond's duration is best described as:",
    choices: ["The years until maturity", "The coupon rate", "The credit rating", "A measure of price sensitivity to rate changes"],
    answerIndex: 3,
    explanation: "Duration measures how much price moves for a given rate change, rising with maturity and falling with coupon. It is related to but distinct from maturity — a zero's duration equals its maturity, while a coupon bond's is shorter." },
  { id: "sie-mkt-183", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Which market has the most liquidity?",
    choices: ["U.S. Treasuries", "Private placements", "Raw land partnerships", "Restricted stock"],
    answerIndex: 0,
    explanation: "The Treasury market is the deepest and most liquid in the world, which is part of why Treasuries anchor pricing everywhere else. The other three are illiquid by design or by rule." },
  { id: "sie-mkt-184", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which best describes an issuer's motivation for a rights offering?",
    choices: ["Reducing share count", "Raising capital while limiting dilution for existing holders", "Avoiding registration", "Paying a dividend"],
    answerIndex: 1,
    explanation: "Rights let current holders maintain their proportional stake, which is why the subscription price sits below market. Capital is still raised — the shares are new." },
  { id: "sie-reg-160", examSlug: "sie", topicId: "regulation", topicName: "Regulatory Framework", difficulty: 2,
    stem: "Which is TRUE of an SRO's disciplinary authority?",
    choices: ["It may imprison violators", "It may only issue warnings", "It may fine, suspend, or expel members", "It has no authority"],
    answerIndex: 2,
    explanation: "FINRA can fine, suspend, bar and expel. Criminal penalties come from the courts following a Department of Justice prosecution — an SRO has no power to imprison." },
  { id: "sie-prd-430", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is an ownership security?",
    choices: ["A debenture", "A T-bill", "A BA", "Common stock"],
    answerIndex: 3,
    explanation: "Stock is ownership with a residual claim; the rest are debt where the holder is a creditor ranking ahead of owners." },
  { id: "sie-prd-431", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A bond quote of 101 equals:",
    choices: ["$1,010", "$101", "$10,100", "$1,001"],
    answerIndex: 0,
    explanation: "Corporate quotes are a percentage of $1,000 par, so 101 means 101% = $1,010." },
  { id: "sie-prd-432", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which has the shortest maturity?",
    choices: ["A T-note", "A T-bill", "A T-bond", "A debenture"],
    answerIndex: 1,
    explanation: "Bills mature in one year or less and pay no coupon. Notes run 2-10 years, bonds beyond 10." },
  { id: "sie-prd-433", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Preferred stock usually carries:",
    choices: ["A vote per share", "Two votes", "No vote", "Cumulative voting"],
    answerIndex: 2,
    explanation: "Preferred trades the vote for dividend priority and a fixed payment. Common carries the vote." },
  { id: "sie-prd-434", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is an investment company?",
    choices: ["A REIT", "A DPP", "A hedge fund", "A mutual fund"],
    answerIndex: 3,
    explanation: "Mutual funds are registered investment companies under the 1940 Act. REITs, DPPs and hedge funds are not." },
  { id: "sie-prd-435", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "An open-end fund issues shares:",
    choices: ["Continuously", "Once", "Annually", "By auction"],
    answerIndex: 0,
    explanation: "Open-end funds continuously issue and redeem at NAV. Closed-end funds issue a fixed count once." },
  { id: "sie-prd-436", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which option has no intrinsic value?",
    choices: ["An in-the-money call", "An out-of-the-money option", "An in-the-money put", "A deep in-the-money call"],
    answerIndex: 1,
    explanation: "Intrinsic value is never negative — an out-of-the-money option simply has zero, though it may still carry time value." },
  { id: "sie-prd-437", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Time value decays fastest:",
    choices: ["At issuance", "Mid-life", "Near expiration", "It does not decay"],
    answerIndex: 2,
    explanation: "Decay accelerates in the final weeks, which works against the buyer and for the writer." },
  { id: "sie-prd-438", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which risk is unique to mortgage securities?",
    choices: ["Credit risk", "Market risk", "Inflation risk", "Prepayment risk"],
    answerIndex: 3,
    explanation: "Homeowners refinance when rates fall, returning principal at the worst moment for reinvestment. Extension risk is its mirror." },
  { id: "sie-prd-439", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "A fund's sales charge is measured against:",
    choices: ["The POP", "The NAV", "Net assets", "The expense ratio"],
    answerIndex: 0,
    explanation: "The charge is a percentage OF THE POP, which is why POP = NAV / (1 - load) uses division rather than multiplication." },
  { id: "sie-prd-440", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is TRUE of a no-load fund?",
    choices: ["It has no costs", "It has an expense ratio", "It cannot be redeemed", "It pays no dividends"],
    answerIndex: 1,
    explanation: "No-load means no sales charge, not no cost. Every fund carries an expense ratio deducted annually from assets." },
  { id: "sie-prd-441", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which best hedges a long stock position?",
    choices: ["A covered call", "A naked call", "A protective put", "A long call"],
    answerIndex: 2,
    explanation: "A put sets a floor at the strike — genuine insurance. A covered call only cushions by the premium received." },
  { id: "sie-prd-442", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which product is a security?",
    choices: ["A fixed annuity", "Whole life", "Term life", "A variable annuity"],
    answerIndex: 3,
    explanation: "The separate account puts investment risk on the holder, which makes it a security requiring a securities registration to sell." },
  { id: "sie-prd-443", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is a GSE?",
    choices: ["Fannie Mae", "Ginnie Mae", "The Treasury", "The Federal Reserve"],
    answerIndex: 0,
    explanation: "Fannie Mae and Freddie Mac are government-sponsored enterprises with only implied backing. Ginnie Mae is a government corporation with an explicit guarantee." },
  { id: "sie-prd-444", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which bond feature protects the HOLDER?",
    choices: ["A call provision", "A put provision", "Subordination", "A floating rate"],
    answerIndex: 1,
    explanation: "A put lets the holder sell back to the issuer. A call belongs to the issuer, and subordination lowers the holder's claim." },
  { id: "sie-prd-445", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Municipal bonds are typically bought by:",
    choices: ["IRA holders", "Low-bracket investors", "High-bracket investors", "Tax-exempt entities"],
    answerIndex: 2,
    explanation: "The exemption is worth most at high marginal rates. It is wasted inside an IRA or a tax-exempt entity, which pay no tax anyway." },
  { id: "sie-prd-446", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which measures a bond's return if held to the call date?",
    choices: ["Current yield", "Nominal yield", "Real yield", "Yield to call"],
    answerIndex: 3,
    explanation: "YTC discounts to the call date and price. On a premium bond it is typically the lowest of the yields, which is why yield to worst is quoted." },
  { id: "sie-prd-447", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A commodity pays:",
    choices: ["No income", "A fixed coupon", "A quarterly dividend", "Guaranteed interest"],
    answerIndex: 0,
    explanation: "Commodities generate no cash flow, so the entire return is price movement. That is why they diversify but add volatility." },
  { id: "sie-prd-448", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is TRUE of accrued interest?",
    choices: ["The seller pays the buyer", "The buyer pays the seller", "The issuer pays it", "It is never charged"],
    answerIndex: 1,
    explanation: "The seller earned interest they will not receive, so the buyer compensates them and is made whole at the next coupon." },
  { id: "sie-prd-449", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which security trades flat?",
    choices: ["A current corporate bond", "A Treasury note", "A defaulted bond", "A municipal bond"],
    answerIndex: 2,
    explanation: "Bonds in default, income bonds and zeros trade flat because no interest is accruing to the seller." },
  { id: "sie-prd-450", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Diversification is most effective when holdings are:",
    choices: ["Highly correlated", "Identical", "In one sector", "Weakly correlated"],
    answerIndex: 3,
    explanation: "Low correlation is what reduces portfolio volatility below the weighted average of the parts — it is correlation, not sheer count, that produces the benefit." },
  { id: "sie-prd-451", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "Which is TRUE of an ETF's expense ratio?",
    choices: ["It is usually lower than an active fund's", "It is always zero", "It exceeds mutual funds", "It is charged at purchase"],
    answerIndex: 0,
    explanation: "Index ETFs have no research team to fund and low turnover, so costs are minimal. The ratio is deducted from assets, not charged upfront." },
  { id: "sie-prd-452", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "A warrant's exercise price at issue is typically:",
    choices: ["Below market", "Above market", "At market", "Zero"],
    answerIndex: 1,
    explanation: "Warrants are struck above market and run for years, so they have no intrinsic value at issue. Rights are struck below market and expire quickly." },
  { id: "sie-prd-453", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which describes par value for preferred stock?",
    choices: ["Usually $1,000", "Usually $10", "Usually $100", "There is none"],
    answerIndex: 2,
    explanation: "Preferred conventionally uses $100 par, so a 6% preferred pays $6 annually. Corporate bonds use $1,000." },
  { id: "sie-prd-454", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 2,
    stem: "An investor wants no principal risk over 6 months. Best fit:",
    choices: ["A stock fund", "A 20-year bond", "A REIT", "A T-bill"],
    answerIndex: 3,
    explanation: "A short-dated government instrument has no credit risk and matures inside the window. The others all risk principal." },
  { id: "sie-prd-455", examSlug: "sie", topicId: "products", topicName: "Products & Their Risks", difficulty: 1,
    stem: "Which is TRUE of a bond ladder?",
    choices: ["It staggers maturities to manage reinvestment risk", "It concentrates in one maturity", "It uses leverage", "It holds only equities"],
    answerIndex: 0,
    explanation: "Staggering maturities means only a portion reprices at any one time, smoothing the effect of rate moves in either direction." },
  { id: "sie-trd-300", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which requires a signed customer agreement?",
    choices: ["A cash account", "A margin account", "An individual account", "A joint account"],
    answerIndex: 1,
    explanation: "Margin requires a signed agreement containing the credit and hypothecation terms. A cash account needs no customer signature." },
  { id: "sie-trd-301", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Who approves a new account?",
    choices: ["FINRA", "The SEC", "A principal", "The customer"],
    answerIndex: 2,
    explanation: "A principal must approve every new account; options accounts additionally require a registered options principal." },
  { id: "sie-trd-302", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is prohibited without written authority?",
    choices: ["Recommending a fund", "Sending a prospectus", "Explaining fees", "Discretionary trading"],
    answerIndex: 3,
    explanation: "Choosing the security, amount, or whether to trade requires prior written discretionary authority." },
  { id: "sie-trd-303", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Painting the tape creates:",
    choices: ["False market activity", "Real liquidity", "Tax losses", "Price stability"],
    answerIndex: 0,
    explanation: "Trading among cooperating parties manufactures the illusion of volume and interest — a prohibited manipulation." },
  { id: "sie-trd-304", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is the CTR threshold?",
    choices: ["$5,000", "$10,000", "$3,000", "$25,000"],
    answerIndex: 1,
    explanation: "Cash over $10,000 in a day triggers a mechanical CTR filing. The $5,000 figure is the judgement-based SAR." },
  { id: "sie-trd-305", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which account type ends at the age of majority?",
    choices: ["JTWROS", "Individual", "UTMA", "Corporate"],
    answerIndex: 2,
    explanation: "Control of a custodial account passes to the minor outright at majority — the assets were always legally theirs." },
  { id: "sie-trd-306", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Reg T applies to:",
    choices: ["Maintenance margin", "Short maintenance", "Commissions", "Initial margin"],
    answerIndex: 3,
    explanation: "Reg T is the Fed's 50% INITIAL requirement. FINRA sets the 25% long and 30% short maintenance minimums." },
  { id: "sie-trd-307", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which must be marked on an order ticket?",
    choices: ["Solicited or unsolicited", "The customer's income", "The firm's profit", "The market maker"],
    answerIndex: 0,
    explanation: "That marking determines whether suitability applies. Mismarking a solicited trade to escape the analysis is a serious violation." },
  { id: "sie-trd-308", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A wash sale disallows:",
    choices: ["A capital gain", "A capital loss", "Dividend income", "Interest income"],
    answerIndex: 1,
    explanation: "Repurchasing a substantially identical security within 30 days before or after disallows the loss — a 61-day window." },
  { id: "sie-trd-309", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE of arbitration?",
    choices: ["It is advisory", "It is appealable", "It is binding", "It is optional after filing"],
    answerIndex: 2,
    explanation: "Arbitration is binding with essentially no appeal. Mediation is the voluntary non-binding alternative." },
  { id: "sie-trd-310", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Books and records are generally kept for:",
    choices: ["One year", "Ten years", "Six months", "Three years"],
    answerIndex: 3,
    explanation: "Three years, the first two easily accessible. Formation documents run six years or the life of the firm." },
  { id: "sie-trd-311", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which describes commingling?",
    choices: ["Mixing customer and firm assets", "Combining two customer orders", "Trading two securities", "Merging accounts"],
    answerIndex: 0,
    explanation: "Customer property must remain segregated and identifiable so it is protected if the firm fails." },
  { id: "sie-trd-312", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "Which is TRUE of an unsolicited order?",
    choices: ["It must be refused if unwise", "It carries no suitability duty", "It requires principal pre-approval", "It cannot be executed"],
    answerIndex: 1,
    explanation: "Suitability attaches to RECOMMENDATIONS. An unsolicited order carries none but must be marked as such." },
  { id: "sie-trd-313", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "A firm may lend customer securities only with:",
    choices: ["The margin agreement alone", "Verbal approval", "Loan consent", "Principal approval"],
    answerIndex: 2,
    explanation: "Loan consent is a separate and optional part of the margin agreement. Hypothecation covers pledging as collateral, a different act." },
  { id: "sie-trd-314", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which is a red flag for money laundering?",
    choices: ["Regular payroll deposits", "A 401(k) rollover", "Dividend reinvestment", "Structured cash deposits"],
    answerIndex: 3,
    explanation: "Breaking cash into amounts below $10,000 to avoid reporting is structuring — a federal crime and a reportable red flag." },
  { id: "sie-trd-315", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 2,
    stem: "The Firm Element is designed by:",
    choices: ["The member firm", "FINRA", "The SEC", "The customer"],
    answerIndex: 0,
    explanation: "The firm runs an annual needs analysis and builds training around its own products and risks. The Regulatory Element is FINRA's." },
  { id: "sie-trd-316", examSlug: "sie", topicId: "trading", topicName: "Trading, Accounts & Prohibited Activities", difficulty: 1,
    stem: "Which ends all prior trading authority?",
    choices: ["A losing quarter", "The customer's death", "A complaint", "An address change"],
    answerIndex: 1,
    explanation: "Death cancels open orders and freezes the account pending documentation — discretion and powers of attorney all terminate." },
  { id: "sie-mkt-200", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which is a primary market transaction?",
    choices: ["An exchange purchase", "A block trade", "A new bond issue", "A short sale"],
    answerIndex: 2,
    explanation: "New securities with proceeds to the issuer define the primary market. The other three all move existing securities between investors." },
  { id: "sie-mkt-201", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "A market maker quotes:",
    choices: ["Only a bid", "Only an ask", "A single price", "Both a bid and an ask"],
    answerIndex: 3,
    explanation: "Two-sided quotes are what provide liquidity, and the spread between them compensates the dealer for inventory risk." },
  { id: "sie-mkt-202", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Which is TRUE of exempt securities?",
    choices: ["Registration is not required", "They carry no risk", "They are guaranteed", "They cannot decline"],
    answerIndex: 0,
    explanation: "Exemption addresses paperwork, not risk. A municipal bond can still default and still fluctuates in price." },
  { id: "sie-mkt-203", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Expansionary monetary policy tends to:",
    choices: ["Raise interest rates", "Lower interest rates", "Reduce the money supply", "Raise reserve requirements"],
    answerIndex: 1,
    explanation: "Injecting reserves increases the money supply and eases credit. Selling securities or raising rates does the reverse." },
  { id: "sie-mkt-204", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "An inverted yield curve has historically preceded:",
    choices: ["Expansions", "Bull markets", "Recessions", "Deflation only"],
    answerIndex: 2,
    explanation: "Inversion means short rates exceed long rates, an unusual configuration that has preceded downturns." },
  { id: "sie-mkt-205", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "The SEC's registration review checks:",
    choices: ["Investment merit", "Expected returns", "Management quality", "Disclosure completeness"],
    answerIndex: 3,
    explanation: "It is a disclosure regime, never a merit review. Claiming SEC approval of a security is itself a violation." },
  { id: "sie-mkt-206", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 2,
    stem: "Which entity nets daily obligations between firms?",
    choices: ["The NSCC", "The SEC", "FINRA", "The transfer agent"],
    answerIndex: 0,
    explanation: "The NSCC nets so firms settle differences rather than every gross transaction, cutting the value that must move." },
  { id: "sie-mkt-207", examSlug: "sie", topicId: "markets", topicName: "Capital Markets", difficulty: 1,
    stem: "Corporate profits are which indicator?",
    choices: ["Leading", "Lagging", "Coincident", "Unrelated"],
    answerIndex: 1,
    explanation: "Profits are reported after the period they describe, so they confirm a turn rather than predict it." },
];
